async function logout(): Promise<void> {
  const regions = regionArg()
  const cleared: string[] = []
  for (const region of regions) {
    for (const path of [qoderAccountsPath(region), qoderPoolStorePath(region)]) {
      try {
        await rm(path, { force: true })
