      "content": "{\n  \"name\": \"@dmh2002/dsh-connect-qoder\",\n  \"displayName\": \"DSH Connect Qoder\",\n  \"description\": \"把 Qoder（通义灵码国内版 / 国际版）接入 DeepSeek Harness：PAT 多账号池、每日签到、积分读数与模型管理。\",\n  \"version\": \"1.23.0\",\n  \"author\": \"dingminhua\",\n  \"copyright\": \"Copyright (c) 2026 LaoDing\",\n  \"license\": \"MIT\",\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"qoder\",\n    \"lingma\",\n    \"model-provider\",\n    \"credits\",\n    \"account-pool\",\n    \"check-in\"\n  ],\n  \"type\": \"module\",\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"bin\": {\n    \"dsh-connect-qoder\": \"lib/bin.js\"\n  },\n  \"icon\": \"icons/dsh-connect-qoder-128.png\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"3.18.4\"\n  },\n  \"files\": [\n    \"lib\",\n    \"icons\",\n    \"docs/assets\",\n    \"docs/PAT.md\",\n    \"docs/PRIVACY.md\",\n    \"docs/DESIGN.md\",\n    \"docs/PROMO_BADGE.md\",\n    \"screenshots.json\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"CHANGELOG.md\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"LICENSE\",\n    \"docs/DSH-0.2.1-RC1-FOLLOWUP.md\",\n    \"docs/DSH-0.2.2-RC1-FOLLOWUP.md\"\n  ],\n  \"scripts\": {\n    \"prepack\": \"npm run build\",\n    \"build\": \"tsdown\",\n    \"test\": \"vitest run\",\n    \"typecheck\": \"tsc -p tsconfig.json && tsc -p tsconfig.client.json\",\n    \"check\": \"pnpm run typecheck && pnpm run test && pnpm run build\",\n    \"probe:cosy\": \"node scripts/probe-cosy.mjs\",\n    \"probe:vault\": \"node scripts/dump-vault.mjs\",\n    \"pro