    {
      "path": "cordis.patch.yml",
      "content": "# Register the Qoder provider without changing the profile's default model.\n# PAT is configured in the plugin's settings card (or via environment\n# variable); no OAuth flow is started by the plugin itself.\n#\n# `id` deliberately stays the unscoped `dsh-connect-qoder`: it is the entry id,\n# the settings namespace (`settingsNamespaceOf`), and the `/plugins/<id>/…`\n# route prefix. Renaming it would silently orphan every existing install's\n# saved config. Only `name` — the package resolved through the profile's\n# node_modules — carries the npm scope.\n- insert:\n    - id: dsh-connect-qoder\n      name: '@dmh2002/dsh-connect-qoder'\n"
    },
    {
      "path": "src/index.ts",
      "content": "/**\n * dsh-connect-qoder：为 DeepSeek Harness 提供 Qoder（通义灵码国际/国内）模型\n * 供应商的 Cordis 插件。\n *\n * 设计沿用 dsh-connect-workbuddy（MIT，Copyright (c) 2026 LaoDing）的骨架：\n * 每个区域一条「凭据存储 → 回环 shim → pi-ai 适配器 → registerAdapter /\n * registerConfigurableProviders / registerModelDiscovery」栈，CN 与 Global\n * 双区域并行服务。区别（按 Qoder 上游的现实）：\n *   - 凭据是 Qoder PAT：设置卡片填 `regions.<region>.pat`，环境变量兜底\n *     （QODERCN_PERSONAL_ACCESS_TOKEN / QODER_PERSONAL_ACCESS_TOKEN），并叠加\n *     `$DSH_HOME/.qoder-accounts.<region>.json` vault 的多账号池；\n *   - 聊天直接走 Qoder cosy 网关协议（见 src/upstream.ts），模型目录为网关\n *     model/list 的实时快照（src/catalog.ts）；\n *   - **有** daily check-in（两个区域都有）：CN 直接调 sash 的 campaigns 活动；\n *     国际版额外需要设备风控头（本机 UMID 组件，见 device-risk.ts）。\n *     没有扫码 OAuth\n *     （账号增删走 PAT 粘贴的 accounts 路由），没有桌面临终诊断 / markup 恢复；\n *   - 多账号池「实测优先」：test 批量用各成员凭据探测目标模型，落\n *     `$DSH_HOME/.qoder-pool.<region>.json`；failover 循环在流首字节前按 rankPool\n *     换账号。\n *\n * @module dsh-connect-qoder\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport type { AdapterRegistrationHandle, DirectoryRegistrationHandle } from '@deepseek-ai/dsh-llm'\nimport { QoderUpstreamClient } from './upstream.ts'\nimport { failoverNoticeText, queuedFailoverNoticeText, upstreamDownFailoverNoticeText } from './failover-notice.ts'\nimport type { QoderUsage, QoderChatDelta, QoderRegion, QoderUpstreamError, UpstreamErrorKind, QoderCampaignFeed } from './upstream.ts'\nimport { isQoderUpstreamError } from './upstream.ts'\nimport type { QoderModelInfo } from './catalog.ts'\nimport { QoderCatalog, fallbackModelInfo, deriveCatalog, initialEnabledKeys, parseUpstreamModel, applyContextBudgets, modelDisplayName, withoutRouters, withoutAbstractModels, mapContextTier, mapContextTiers, migrateContextBudgets } from './catalog.ts'\nimport { QODER_FALLBACK_MODELS } from './catalog.ts'\nimport { readPromotion, type QoderPromotion } from './promo.ts'\nimport { defaultOffModelIds, offCapabilityOf, withEffectiveOff } from './off-thinking.ts'\nimport { imageDefaultFor } from './native-modality.ts'\nimport { createQoderShim, type QoderShim, type QoderServingAccount } from './shim.ts'\nimport { createQoderAdapter, type QoderAdapter, QODER_PROVIDERS, QODER_PROVIDER_DISPLAY_NAMES, regionOfProvider } from './adapter.ts'\nimport type { RetryPolicyConfig } from '@deepseek-ai/dsh-llm'\nimport { probeModel, probeUserMessage, redactUpstreamText, type QoderProbeClient, type QoderProbeError } from './probe.ts'\nimport {\n  registerQoderWebRoutes,\n  type QoderPoolDeps,\n  type QoderAccountDeps,\n  type QoderAccountEntryLike,\n  type QoderAccountValidationDeps,\n  type QoderSettingsDeps,\n  type QoderTransferDeps,\n} from './web-status.ts'\nimport {\n  QODER_SETTINGS_NS,\n  QODER_GITHUB_URL,\n  QODER_REGIONS,\n  QODER_POLL_MINUTES_FIELD,\n  QODER_SIDEBAR_PANEL_FIELD,\n  pollMinutesOf,\n  sidebarPanelEnabledOf,\n  unwrapVolatileDeep,\n  type QoderWebProbeResult,\n  type QoderWebProbeOutcome,\n  type QoderWebPoolTestRow,\n  type QoderWebPoolCheckinRow,\n  type QoderWebCredits,\n  type QoderWebCreditPackage,\n  type QoderWebAccountCredit,\n  type QoderWebRecovery,\n  type QoderWebQuotaExhaustion,\n  type QoderCreditPosition,\n} from './status-paths.ts'\nimport { qoderAccountId, maskPat, patFromEnv } from './credentials.ts'\nimport { QoderAccountStore, type QoderStoredAccount } from './accounts.ts'\nimport { QODER_CONNECT_VERSION } from './version.ts'\nimport {\n  exclusionOf,\n  fallbackCooldownOf,\n  poolModelOf,\n  rankPool,\n  resolvePoolTarget,\n  type QoderPoolCredits,\n  type QoderPoolProbe,\n  type QoderPoolMember,\n  type QoderPoolModel,\n  type QoderPoolTarget,\n} from './account-pool.ts'\nimport { readPoolDocument, writePoolDocument, writePoolProbes } from './account-pool-store.ts'\nimport { testAllAccounts, testOne, POOL_BATCH_GAP_MS, type QoderPoolRunnerDeps } from './account-pool-run.ts'\nimport { resolveCredentialRecovery, createAccountUsabilityProbe, type QoderProbeStore } from './credential-recovery.ts'\nimport { writeHostHeartbeat, clearHostHeartbeat } from './host-heartbeat.ts'\nimport {\n  appendCheckinBatch,\n  creditExpiryOf,\n  type QoderCheckinBatch,\n} from './credit-expiry.ts'\n\nexport { QODER_CONNECT_VERSION }\nexport { QODER_GITHUB_URL }\n\n// ---------------------------------------------------------------------------\n// 标识与注入\n// ---------------------------------------------------------------------------\n\nexport const name = 'dsh-connect-qoder'\n\n/** The model registry and settings service required before providers register. */\nexport const inject = ['llm', 'settings']\n\n/**\n * 积分读（`sash/api/v2/me/usage`）的超时上限。\n *\n * 这个读现在发生在**每次** `/usage` 路由请求上（卡片与 composer 的自动刷新轮询（`pollMinutes`，默认 5 分钟）+\n * 面板打开），所以它不能再无界：上游挂住会把整张卡片与 composer 读数一起挂住。\n */\nconst USAGE_FETCH_TIMEOUT_MS = 8_000\n\n/**\n * 给一个 promise 加硬超时，超时**按「这次没读到」处理**（resolve undefined），\n * 而不是抛错。\n *\n * 两条理由：\n *   1. `fetchUsage` 先 `ensureSession()` 再带 signal 打 sash，signal 只管得住后半段\n *      —— 会话过期时前半段（jobToken 交换）挂住，signal 还没生效。整体 race 才封得住。\n *   2. 超时必须落到**保旧值**那条分支，而不是 catch 分支：后者会把缓存写成\n *      `usage: undefined`，于是「网络慢」被显示成「没有积分数据」。\n *\n * 迟到的 rejection 要单独吞掉：promise 已经按超时结算之后，它再 reject 就是一次\n * 没人处理的 rejection。\n */\nexport function withHardTimeout<T>(promise: Promise<T>, timeoutMs: number): Promise<T | undefined> {\n  let timer: ReturnType<typeof setTimeout> | undefined\n  return new Promise<T | undefined>((resolve, reject) => {\n    timer = setTimeout(() => { resolve(undefined) }, timeoutMs)\n    // 这条 then 的两个回调就是 rejection 的处理者：超时之后 promise 才失败时，\n    // `reject` 对已结算的 promise 是空操作，而 promise 本身始终挂着处理器，\n    // 不会变成 unhandled rejection。\n    promise.then(resolve, reject)\n  }).finally(() => {\n    if (timer !== undefined) clearTimeout(timer)\n  })\n}\n\n/** The namespace the HOST actually serves this plugin under (workbuddy probe). */\nexport function settingsNamespaceOf(ctx: unknown): string {\n  const id = (ctx as { fiber?: { entry?: { options?: { id?: unknown } } } })?.fiber?.entry?.options?.id\n  return typeof id === 'string' && id !== '' ? id : QODER_SETTINGS_NS\n}\n\n// ---------------------------------------------------------------------------\n// Config\n// ---------------------------------------------------------------------------\n\nexport function asVolatile<T>(schema: z<T>): z<T> {\n  if (typeof (schema as unknown as { volatile?: () => z<T> }).volatile === 'function') {\n    return (schema as unknown as { volatile: () => z<T> }).volatile()\n  }\n  return schema\n}\n\n/** Unwrap a schemastery volatile's reactive `.get()` into a plain snapshot. */\nexport function unwrapVolatile<T>(value: T): T {\n  if (value !== null && typeof value === 'object' && 'get' in (value as object) && typeof (value as unknown as { get(): unknown }).get === 'function') {\n    return (value as unknown as { get(): T }).get()\n  }\n  return value\n}\n\nconst modelConfig = z.object({\n  key: z.string(),\n  displayName: z.string(),\n  priceFactor: z.number(),\n  contextWindow: z.number(),\n  maxOutputTokens: z.number(),\n  supportsImages: z.boolean(),\n  supportsThinking: z.boolean(),\n  canDisableThinking: z.boolean(),\n  isDefault: z.boolean(),\n  isFree: z.boolean(),\n  isNew: z.boolean(),\n  /**\n   * 该模型声明的思考强度档位（`['xhigh','low','medium']` 之类，已按强度升序）。\n   *\n   * 必须在这里声明成 `required(false)`，否则思考强度选择器整个不渲染。但**机制\n   * 不是「被 zod 剥掉」**（本注释原先这么写，是错的，已由实验更正）：实测\n   * schemastery **不剥未声明的键**（`nativeContextWindow` / `maxTokens` 那些都会\n   * 原样透传），真正会发生的是**缺席的数组被补成 `[]`**。\n   *\n   * 于是缺陷链条是：客户端从不写这个字段（0.4.2 已修）→ 落盘缺席 → 解析补 `[]`\n   * → 读取端 `modelFromStored` 的判据是 `length > 0` → 档位选择器消失\n   * （用户实拍「拉取的思考模式又不见了」「每次保存都会思考强度不见了」）。\n   * 也就是说：**声明仍然必需，必需的理由是那三个字段的判据（`length > 0` / 非空串）\n   * 与「缺席补 []」之间的落差，而不是剥键。** `contextTiers` 同理。\n   */\n  thinkingEfforts: z.array(z.string()).required(false),\n  defaultThinkingEffort: z.string().required(false),\n  contextTiers: z.array(z.number()).required(false),\n  /**\n   * 上游的活动优惠规则（`promotion`），原样往返。\n   *\n   * 用 `z.any()` 而不是嵌套 schema，理由只有两条：**不写第二套解析**（上游 snake_case\n   * → `QoderPromotion` 的映射只在 `parseQoderPromotion` 里有一份），以及**不让 schema\n   * 去「理解」上游文档**——上游字段随活动类型变化，逐个声明等于把上游的形状抄进配置层，\n   * 抄漏的那次就会像 `thinkingEfforts` 那样把数据抹掉。\n   *\n   * 注意它**不等于**「未来新增的键会被保住」：读回时走 `readPromotion` 的白名单重建，\n   * 插件不认识的键在那里就丢了（这是有意的——卡片只消费自己声明过的字段）。所以这个\n   * 字段的契约是「本插件已知的字段原样往返」，不是「上游文档原样存档」。\n   */\n  promotion: z.any<QoderPromotion>().required(false),\n})\n\nconst poolConfig = z.object({\n  enabled: z.boolean().default(false),\n  targetModelId: z.string().default(''),\n  probeInputTokens: z.number().default(0),\n  memberAccountIds: z.array(z.string()).default([]),\n  /**\n   * 用户手动排定的账号优先级（靠前的先用）。\n   *\n   * 与 `memberAccountIds` **分开**存：那个是成员资格（谁在池里），这个是顺序\n   * （先用谁）。合成一个数组会让「取消勾选再勾回来」意外改变优先级，而旧配置\n   * 里的那个顺序只是勾选历史，并不表达意图。\n   *\n   * 空数组 = 完全由 `rankPool` 的积分策略决定（修复前的行为）。\n   */\n  orderAccountIds: z.array(z.string()).default([]),\n})\n\n/**\n * 重试预算（issue #24）。**三个 0 都表示「用宿主默认」**。\n *\n * 用 0 而不是 `.optional()` 作缺省：配置界面把三个数字框摆在用户眼前，留空\n * 就是 0；而「0 次重试」是一个真实且有用的选择（彻底关掉原地重试），不能被\n * 当作「未配置」吞掉。所以判据是「值为 0 = 跟随宿主默认」，与「填 0 = 关掉」\n * 分开 —— 后者请填 `maxRetries: -1`？不行，那更绕。\n *\n * 结论：这里只把 **0 当默认**，并把「关掉重试」留给宿主默认里的 `maxRetries`\n * 之外的手段（本版不提供）。理由：把 0 解释成「关」会让**升级用户**的中文\n * 配置（schema 默认 0）一上来就关掉全部重试，那是静默的行为变化。\n */\n/**\n * 「上游排队时插件自己等多久」的默认上限（毫秒，issue #29）。\n *\n * 取 60 秒：上游实测申报值多为 30 秒（`queueType: p3`），留一倍余量；再长的\n * 申报值不做截断等待，原样交回宿主决定。\n */\nconst DEFAULT_QUEUE_WAIT_MS = 60_000\n\nconst regionRetryConfig = z.object({\n  /** 最多重试几次（0 = 跟随宿主默认）。 */  maxRetries: z.number().step(1).min(0).default(0).description('最多原地重试几次（0 = 跟随宿主默认）'),\n  /** 首次退避毫秒（0 = 跟随宿主默认）。 */\n  initialDelayMs: z.number().min(0).default(0).description('首次退避毫秒（0 = 跟随宿主默认）'),\n  /** 退避上限毫秒（0 = 跟随宿主默认）。 */\n  maxDelayMs: z.number().min(0).default(0).description('退避上限毫秒（0 = 跟随宿主默认）'),\n  /**\n   * 上游说「排队中、等 N 秒再来」时，插件自己在转发层等掉这一次的上限（毫秒，\n   * issue #29）。0 = 关掉（把失败原样交给宿主的重试阶梯）。\n   *\n   * 为什么需要它：宿主的重试阶梯是**递增**的（5s → 10s → 20s → 30s），而上游\n   * 申报的等待是定值（实测 30 秒）。于是前两次重试必然短于申报值 —— 现场实测\n   * 28 次重试、296 秒白等，且 11 次是在上游说「等 30 秒」后 5 秒内重发的。\n   * `pi-ai` 路由又没有 `providerRetryAfterMs` 通道（issue #24 已复核），插件\n   * 无法让宿主精确等待，只能在自己这一层等。\n   *\n   * 默认 60000：覆盖实测的 30 秒申报值并留余量；超过它的申报值不截断等待，\n   * 原样交给宿主。\n   */\n  queueWaitMs: z.number().min(0).default(60_000).description('上游排队时插件自己等待的上限毫秒（0 = 关掉）'),\n})\n\nconst regionConfig = z.object({\n  /** 本区域 PAT。留空读环境变量；env 与 vault 承接连带选择。 */\n  pat: z.string().default('').description('Qoder PAT（留空时读取环境变量）'),\n  /** 本区域 provider 是否启用；显式 false 才停用（opt-out）。 */\n  enabled: z.boolean().default(true),\n  /** 用户显式选择的账号 id（'' = 自动：settings → env → vault）。 */\n  accountId: z.string().default(''),\n  /** 是否在主界面展示积分（composer 面板）；opt-out。 */\n  showCreditsInMainUi: z.boolean().default(true),\n  /**\n   * 是否展示本区域的活动区（上游 campaigns）；**opt-out**。\n   *\n   * 与上面的积分开关同为区域级偏好，理由也一样：这一块是**读上游**得来的\n   * 附加内容，既不是配置也不影响请求。默认开着 —— 签到额度与限时活动本来就是\n   * 用户会来这一页看的东西；但它是每区域独立的，因为两只上游下发的活动本来就\n   * 不同（国际版签到需要设备风控组件，取不到时那一侧会如实报错）。\n   *\n   * 判据是 `!== false` 而不是 `=== true`：这是**内容开关**，不是「占用共享座位」\n   * 那种必须显式授予的东西（对比 `sidebarPanel`）。没写过 = 保持原样，\n   * 升级不能让一页本来有活动的人突然看不见。\n   */\n  showCampaigns: z.boolean().default(true),\n  /**\n   * 积分读数放在哪个席位。\n   *\n   * 两个席位，因为第一个不总是可用：\n   *\n   *   - `composer` —— 输入框工具栏（`conversation.input.right`），与 shell 自带\n   *     控件共享该 list 插槽。它更近、更易扫一眼，且是默认值，所以没主动选过的\n   *     人升级后界面不动。\n   *   - `stats` —— 输入框卡片下方的常驻栏（`conversation.composer.dock`），\n   *     即 shell 渲染「轮次 / tok/s / token / 缓存命中」那一行。那个 list 插槽的\n   *     自带占用者单独注册，因此另一个把东西停在输入框那行的第三方插件，无法把\n   *     这个读数挤到消失。\n   *\n   * 参考 dsh-connect-workbuddy 的 issue #62：装了第三方插件后读数从输入框那行\n   * 消失，根因是「席位本身」——list 插槽无法保证每个占用者都可见。把席位变成\n   * 用户的选择，正是让一个插件的存在不再决定另一个插件的可见性。\n   */\n  creditPosition: z.union([z.const('composer'), z.const('stats')]).default('composer').description('积分读数的位置：\"composer\" = 输入框工具栏（默认），\"stats\" = 输入框卡片下方的常驻栏，与 shell 自己的 token 统计同行。若输入框那行被其他插件占用，选 \"stats\"。'),\n  /** 用户勾选的模型 key 集合。 */\n  enabledModelKeys: z.array(z.string()).default([]),\n  /**\n   * 用户**显式**开启图片输入的模型 key 集合。\n   *\n   * 图像能力只来自这里，绝不从上游的 `is_vl` 平台标记推断——那是**平台**的\n   * 声明，不该替本插件下逐模型的能力结论（见 src/native-modality.ts：为什么\n   * 不采信、核对表现在按什么键控、结论是从哪来的）。\n   * 与 lastCatalog 分开存储，使勾选状态不随目录重写而耦合丢失。\n   *\n   * **它是白名单，不是追加清单**：列出的才开图，未列出的一律关。所以「用户\n   * 把全部勾都取消」与「用户从未保存过」在**数据上**都表现为空数组，而两者的\n   * 正确行为相反（前者应保持全关，后者应套用核对表种子）。空集无法区分它们，\n   * 因此判据是下面那个显式标记 {@link imageSelectionSaved}，不是 `length > 0`。\n   */\n  imageModelKeys: z.array(z.string()).default([]),\n  /**\n   * 用户是否**保存过**图片选择（与集合内容无关）。\n   *\n   * 存在的唯一理由是把「从未选过」与「选成了空集」分开：`imageModelKeys` 是\n   * 白名单，两种情况都是 `[]`，但前者要套核对表种子、后者要尊重「全关」。\n   * 靠 `imageModelKeys.length > 0` 推断会把后一种误判成前一种，用户取消全部\n   * 勾选后一刷新图又回来了（issue #22 的次因）。\n   *\n   * 缺省 `false` = 从未保存过（含升级上来的旧配置）：旧配置里 `imageModelKeys`\n   * 非空时另有兜底判据，见 `imageSelectionSavedOf`。\n   */\n  imageSelectionSaved: z.boolean().default(false),\n  /** 用户关闭的模型 key 集合（独立于硬性关闭）。 */\n  offModelKeys: z.array(z.string()).default([]),\n  /** 每个模型的显式上下文预算（必须是模型声明的 tier，否则用原生值）。 */\n  contextBudgets: z.dict(z.number()).default({}),\n  /**\n   * 每个模型保存的思考强度（档位名，如 `low` / `medium` / `xhigh`）。\n   *\n   * 「设置里选好、之后每个请求自动带上」——与 Qoder 客户端同形态（它的事件\n   * 名就叫 `reasoning-effort-changed`）。缺省表示用模型自己声明的默认档。\n   * 键是模型 key：不同模型的档位名不统一（Qwen 系 low/medium/xhigh，\n   * DeepSeek/GLM 系 low/high/max），所以必须逐模型存。\n   */\n  thinkingEfforts: z.dict(z.string()).default({}),\n  /** 账号池偏好。 */\n  pool: poolConfig.default({ enabled: false, targetModelId: '', probeInputTokens: 0, memberAccountIds: [] }),\n  /**\n   * 重试预算（issue #24）。缺省 = 宿主默认，行为与升级前一致。\n   *\n   * 为什么要能配：`llm-retry` 的等待阶梯由 provider 自己的策略决定，本插件此前\n   * 只传 `resolveRetryPolicy(undefined, …)`（宿主默认 5 次 / 500ms→10s）。上游\n   * 报 `10605 / RESOURCE_LIMIT` 的两种形态差很多（瞬时 5 秒 / `queueType:p2`\n   * 排队 30 秒），一套固定阶梯不可能同时贴合；而插件又没暴露配置项，用户只能改\n   * `node_modules` 里的构建产物 —— 升级即静默还原。\n   *\n   * 只暴露**三个**数字，不暴露 `mode` / `retryableCodes`：那两个会改变「哪些错误\n   * 值得重试」的语义（`always` 甚至会让一个必然失败的请求无限重试），不是「调预算」。\n   */\n  retry: regionRetryConfig.default({ maxRetries: 0, initialDelayMs: 0, maxDelayMs: 0 }),\n  /** 保存的模型目录（卡片“保存”时写入）。 */\n  lastCatalog: z.array(modelConfig).default([]),\n})\n\nexport interface Config {\n  regions: Record<string, unknown>\n  /**\n   * 是否在 DSH 侧边栏放一个 Qoder 面板（行 + 整页）。**默认关闭**。\n   *\n   * 参考：dsh-connect-workbuddy 的 `Config.sidebarPanel`（PR #188，MIT，\n   * Copyright (c) 2026 LaoDing）。\n   *\n   * 为什么要用户显式打开：这一行占的是 `sidebar.panellist` —— 所有插件共用的\n   * 全局侧边栏座位，点开还会接管中央面板。打开它是对用户整个侧边栏的决定，\n   * 不是对这张卡片的偏好；「插件」页本来就能看到同一张卡片，所以默认值必须是\n   * 「不替用户动侧边栏」。缺席读作关闭（`=== true` 判据见 `status-paths.ts`）。\n   */\n  sidebarPanel?: boolean\n}\n\nexport const Config: z<Config> = z.object({\n  regions: asVolatile(z.dict(regionConfig).default({}).description('Per-region Qoder settings, keyed cn | global')),\n  /**\n   * 打上游的自动刷新间隔（分钟），全局一档。\n   *\n   * 卡片与输入框积分读数共用这一个节奏：它们问的是同一个 `/usage` 路由，宿主侧\n   * 本来就把几乎同时到达的读合流成一次上游请求（见下方 usage 读合流），所以两个\n   * 表面各配一个间隔只会制造「错开的两次读」，不会省任何请求。\n   *\n   * 默认 **5**：composer 读数在这个设置存在之前就是 300s，升级不动任何人的屏幕；\n   * 卡片此前是 60s，改成 5 分钟是**有意的降频**——卡片上的数字是积分余额，变化\n   * 频率以分钟计，60s 一轮换来的只是「早四分钟看到一次几乎不变的数」，代价是每\n   * 分钟一次上游往返（两个区域各一）。想要更及时的读数，选 1 分钟即可。\n   *\n   * 五档枚举而不是自由数字：这是**对上游的请求频率**，手改配置写进一个 0 或负数\n   * 会变成每秒打点。`pollMinutesOf` 对任何不在五档里的值退回默认。\n   */\n  pollMinutes: z.union([\n    z.const(1), z.const(5), z.const(10), z.const(30), z.const(60),\n  ]).default(5).description('How often the card and the composer credit readout re-read upstream usage, in minutes. One global rhythm: both surfaces ask the same route and the Host coalesces near-simultaneous reads into one upstream call.'),\n  // Volatile 的理由与 workbuddy 同名项相同：卡片上的开关写它，而一次完整插件\n  // 重载会 dispose 两个 provider 栈、掉光在飞的请求 —— 为「多一行导航」付这个\n  // 价格完全不成比例。volatile 之后写入只走 `loader/volatile-update`，\n  // 顶层值随即被重新读出（`sidebarPanelEnabledOf` 已解包）。\n  sidebarPanel: asVolatile(\n    z.boolean()\n      .default(false)\n      .description('Add a Qoder panel to the DSH sidebar: a nav row that opens the credits / accounts / model catalog as a full page. Off by default — the row claims a global sidebar seat shared by every bundle, and the Plugins page already reaches the same content.'),\n  ) as unknown as z<boolean>,\n}) as unknown as z<Config>\n\n/**\n * 一份目录是否**声明了**思考档位。\n *\n * 「一个模型都没有档位」有两种完全不同的含义，必须分开：\n * 1. 上游当前没声明（`thinkingEfforts` 字段缺席或为空）—— 那它是「上游没\n *    档位」的诚实答案；\n * 2. 这份目录来自一次没拉到档位的时刻 —— 本机实测 14 个 cn 模型的\n *    `thinkingEfforts` 全是 `[]`，是旧 schema 把字段剥掉时的产物。用它当答案，\n *    卡片就不渲染档位选择器（用户实拍「思考强度有时候有、有时候没有」：点一次\n *    「从 Qoder 刷新」就有，重启后就没）。\n *\n * 两种情况从数据上分不开（空数组与缺席都判「没声明」），要不要重拉由**目录的\n * 来源**决定：调用方只在「本进程还没成功拉到实时目录」时才据此触发重拉（见\n * displayModels）—— 实时目录没档位是上游的诚实答案，重拉多少次都一样。\n *\n * 判据用 `length > 0` 而不是「字段在不在」：旧 schema 留下的是**空数组**而不是\n * 缺席，所以「字段在」恰恰不能作为「声明过」的证据。\n */\nexport function catalogSnapshotDeclaresEfforts(\n  models: readonly { thinkingEfforts?: readonly string[] }[],\n): boolean {\n  return models.some(model => (model.thinkingEfforts?.length ?? 0) > 0)\n}\n\n/**\n * 「手上的目录能不能当档位答案」——**判据与动作打包在一起**。\n *\n * 拆开成两个函数（判据一个、调用处自己判）会留下一条没被测试覆盖的接线：把调用处\n * 变异掉，单测仍然全绿（第一版就是这么自我欺骗的）。这里让规则自己执行动作并\n * 返回结论，于是「动作有没有真的发生」也能被断言。\n *\n * 检测到「一个档位都没声明」时**不改动要服务的模型列表**：模型不能从卡片上\n * 消失，缺的只是档位 —— 后台拉回来之后的下一次读取自然补上。返回 `stale`\n * 标记这次调用有没有触发过拉取。\n */\nexport function serveSavedCatalog(\n  models: readonly QoderModelInfo[],\n  onStale: () => void,\n): { models: readonly QoderModelInfo[], stale: boolean } {\n  if (catalogSnapshotDeclaresEfforts(models)) return { models, stale: false }\n  onStale()\n  return { models, stale: true }\n}\n\n/** 某区域的配置状态（缺省返回空对象）。 */\nexport function regionStateOf(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): Record<string, unknown> {\n  const regions = unwrapVolatile(config.regions) as Record<string, unknown> | undefined\n  const stored = regions?.[region]\n  if (stored !== undefined && stored !== null && typeof stored === 'object') return stored as Record<string, unknown>\n  return {}\n}\n\n/** 某区域是否启用（opt-out）。 */\nexport function regionEnabled(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): boolean {\n  const state = regionStateOf(config, region)\n  return state.enabled !== false\n}\n\n/**\n * 某区域的重试预算 → 宿主的 `RetryPolicyConfig`（issue #24）。\n *\n * 三个值全为 0（schema 默认）时返回 `undefined`：**交给宿主默认**，与升级前\n * 逐字一致。只要有一个非 0 就成对补齐 —— 宿主的 `resolveBackoff` 要求\n * `initialDelayMs <= maxDelayMs` 且都为正数，所以缺失的一侧用另一侧/默认填，\n * 而不是原样把 0 递进去（那会直接抛）。\n *\n * `mode` 恒为 `normal`（只重试宿主的可重试码）：`always` 会让一个必然失败的\n * 请求无限重试，那不是「调预算」，所以本版不暴露。\n */\nexport function retryPolicyOf(\n  config: { regions?: Record<string, unknown> | null },\n  region: QoderRegion,\n): RetryPolicyConfig | undefined {\n  const state = regionStateOf(config, region)\n  const raw = (state.retry ?? {}) as Record<string, unknown>\n  const num = (value: unknown): number => (typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : 0)\n  const maxRetries = num(raw.maxRetries)\n  const initialDelayMs = num(raw.initialDelayMs)\n  const maxDelayMs = num(raw.maxDelayMs)\n  if (maxRetries === 0 && initialDelayMs === 0 && maxDelayMs === 0) return undefined\n\n  // 补齐规则：给定的一侧优先；都缺就用宿主默认量级，且保证 initial <= max。\n  const initial = initialDelayMs > 0 ? initialDelayMs : Math.min(500, maxDelayMs > 0 ? maxDelayMs : 500)\n  const max = maxDelayMs > 0 ? maxDelayMs : Math.max(initial, 10_000)\n  return {\n    mode: 'normal',\n    ...maxRetries > 0 ? { maxRetries } : {},\n    backoff: { initialDelayMs: Math.min(initial, max), maxDelayMs: max },\n  }\n}\n\n/**\n * 某区域「上游排队时插件自己等多久」的上限（毫秒，issue #29）。\n *\n * 返回 `undefined` 表示关掉（0）：失败原样交给宿主的重试阶梯。本地读取而不是\n * 依赖 schema 默认值 —— 这样在设置存在之前写下的配置读出来是「关」还是「60 秒」\n * 由这里一句话决定，不随 schema 默认值漂移。\n *\n * 为什么默认开着：宿主的阶梯前两次一定短于上游申报的 30 秒（见 issue #29 的\n * 28 次重试实测），不在这层等掉就等于每次都在对方说「别来」的窗口里敲门。\n */\nexport function queueWaitMsOf(\n  config: { regions?: Record<string, unknown> | null },\n  region: QoderRegion,\n): number | undefined {\n  const state = regionStateOf(config, region)\n  const raw = (state.retry ?? {}) as Record<string, unknown>\n  const value = raw.queueWaitMs\n  if (typeof value === 'number' && Number.isFinite(value) && value >= 0) {\n    return value > 0 ? value : undefined\n  }\n  return DEFAULT_QUEUE_WAIT_MS\n}\n\n/** 某区域是否在主界面显示积分（opt-out）。 */\nfunction regionCreditsShown(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): boolean {\n  const state = regionStateOf(config, region)\n  return state.showCreditsInMainUi !== false\n}\n\n/**\n * 某区域是否展示活动区（opt-out）。\n *\n * 与 {@link regionCreditsShown} 同一条判据、同一种本地读取：这样在设置存在之前\n * 写下的配置读出来是「显示」—— 活动区当时就在，升级不该让它消失。\n */\nfunction regionCampaignsShown(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): boolean {\n  const state = regionStateOf(config, region)\n  return state.showCampaigns !== false\n}\n\n/**\n * 某区域的积分读数放在哪个席位。\n *\n * 本地读取而不是依赖 schema 默认值：这样在设置存在之前写下的配置读出来是\n * `composer` —— 当时唯一的席位 —— 所以升级不会移动屏幕上的任何东西。\n */\nfunction creditPosition(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): QoderCreditPosition {\n  const state = regionStateOf(config, region)\n  return state.creditPosition === 'stats' ? 'stats' : 'composer'\n}\n\n/** 某区域是否配置了凭据（设置 PAT 或环境变量其一）。 */\nexport function regionHasCredential(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): boolean {\n  const state = regionStateOf(config, region)\n  const pat = typeof state.pat === 'string' ? state.pat.trim() : ''\n  if (pat !== '') return true\n  return patFromEnv(region) !== undefined\n}\n\n/** 某区域显式选择的账号 id（undefined = 自动）。 */\nfunction selectedAccountId(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): string | undefined {\n  const state = regionStateOf(config, region)\n  const id = state.accountId\n  return typeof id === 'string' && id !== '' ? id : undefined\n}\n\n/** 某区域保存的 contextBudgets（过档位改写表：旧存档的 400K 读回即 500K）。 */\nfunction contextBudgetsOf(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): Record<string, number> {\n  const state = regionStateOf(config, region)\n  const raw = state.contextBudgets\n  if (raw === null || raw === undefined || typeof raw !== 'object') return {}\n  const out: Record<string, number> = {}\n  for (const [key, value] of Object.entries(raw)) {\n    if (typeof value === 'number' && Number.isFinite(value)) out[key] = value\n  }\n  return migrateContextBudgets(out)\n}\n\n/** 某区域保存的 offModelKeys。 */\nfunction offModelKeysOf(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): readonly string[] {\n  const state = regionStateOf(config, region)\n  return Array.isArray(state.offModelKeys) ? (state.offModelKeys as string[]) : []\n}\n\n/** 某区域保存的逐模型思考强度（模型 key → 档位名）。 */\nfunction thinkingEffortsOf(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): Record<string, string> {\n  const state = regionStateOf(config, region)\n  const raw = state.thinkingEfforts\n  if (raw === null || raw === undefined || typeof raw !== 'object') return {}\n  const out: Record<string, string> = {}\n  for (const [key, value] of Object.entries(raw)) {\n    if (typeof value === 'string' && value !== '') out[key] = value\n  }\n  return out\n}\n\n/** 某区域保存的 imageModelKeys（用户显式开启图片输入的模型）。 */\nfunction imageModelKeysOf(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): readonly string[] {\n  const state = regionStateOf(config, region)\n  return Array.isArray(state.imageModelKeys) ? (state.imageModelKeys as string[]) : []\n}\n\n/**\n * 用户是否**保存过**图片选择（决定要不要套核对表种子）。\n *\n * 主判据是显式标记 `imageSelectionSaved`（见配置 schema 里那段：空集既是\n * 「从未选过」也是「选成空集」，只有标记能把它们分开）。\n *\n * 旧配置兜底：`imageSelectionSaved` 是本版新增的键，升级上来的配置里没有它。\n * 那种配置只要有**非空**的 `imageModelKeys`，就说明用户当时确实保存过选择\n * （旧代码只会在保存时写这个集合），按「已保存」处理；空集则无从判断，按\n * 「从未保存」套种子——这正是升级前的行为，不倒退。\n */\nfunction imageSelectionSavedOf(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): boolean {\n  const state = regionStateOf(config, region)\n  if (state.imageSelectionSaved === true) return true\n  return imageModelKeysOf(config, region).length > 0\n}\n\n/**\n * 把用户的**显式**图片 opt-in 盖印到模型列表上——这是 `supportsImages`\n * 在运行时的**唯一**来源，上游的 `is_vl` 平台标记一律不采信。\n *\n * 与 workbuddy 的 `withImageSelection` 同构：所有运行时目录路径（启动种子、\n * 刷新、保存）都经过它，保证同一模型在三条路径上得到一致的图像能力答案。\n * 用户从未保存过时，用 `imageDefaultFor` 的核对表结论作种子，使首次打开就能\n * 显示正确默认，而不必先保存一次。\n *\n * `seeded` 的含义是「用户保存过选择」，由 {@link imageSelectionSavedOf} 判定，\n * **不是** `images.size > 0`：那是把「白名单为空」当成「没选过」，于是用户把\n * 勾全部取消后一刷新，种子又把图全打开了（issue #22 的次因）。\n *\n * `model.key` 与 `model.displayName` 都要交给查表：核对表的主键是内部短 id、\n * 厂商名是别名键，两个候选键覆盖两种来源（旧存档与外部选择器只拿得到显示名）。\n * issue #22 的主因就是这里只传了一个键、而表的键形与它不同，于是每次都查不中。\n */\nfunction withImageSelection(\n  models: QoderModelInfo[],\n  images: ReadonlySet<string>,\n  seeded: boolean,\n): QoderModelInfo[] {\n  return models.map(model => ({\n    ...model,\n    supportsImages: images.has(model.key)\n      ? true\n      : seeded\n        ? false\n        : imageDefaultFor({\n            id: model.key,\n            name: model.displayName,\n            ...(model.supportsImages === undefined ? {} : { supportsImages: model.supportsImages }),\n          }),\n  }))\n}\n\n/**\n * 把用户保存的「可关闭思考」选择盖印到运行时目录上。\n *\n * 上游声明的 `canDisableThinking` 并不可全信（见 src/off-thinking.ts）。运行时\n * 适配器只读模型自报的该字段，所以必须在此之前把校正后的答案写上去。用户尚未\n * 保存过（选择为空）时用 `defaultOffModelIds` 作为种子——只对上游显式声明可关闭、\n * 且不在已知拒绝集里的模型提供 off。\n */\nfunction stampOffSelection(\n  config: { regions?: Record<string, unknown> | null },\n  region: QoderRegion,\n  models: QoderModelInfo[],\n): QoderModelInfo[] {\n  const saved = new Set(offModelKeysOf(config, region))\n  const selection = saved.size > 0\n    ? saved\n    : new Set(defaultOffModelIds(models.map(offCapabilityOf)))\n  return withEffectiveOff(models, selection)\n}\n\n/**\n * 把用户的两项显式选择（图片输入、可关闭思考）盖印到运行时目录上。\n *\n * 两者机制相同：上游声明不可全信，用户的选择是唯一权威；未保存过时用核对表/\n * 内置规则作种子。合在一处便于所有运行时目录路径（启动、刷新、保存）一次盖齐，\n * 避免漏盖导致「某条路径上模型能力与另一条不一致」。\n */\nfunction stampRuntimeCatalog(\n  config: { regions?: Record<string, unknown> | null },\n  region: QoderRegion,\n  models: QoderModelInfo[],\n): QoderModelInfo[] {\n  // **国际版那几个抽象命名的条目在这里再去掉一次。**\n  //\n  // 上游 `configuredModels` 已经过滤过（它管的是「这次配什么」），这一处管的是\n  // 「装进运行时目录的东西」。两者不是重复：`stampRuntimeCatalog` 是\n  // `catalog.set()`（运行时目录）与 `cardCatalog` 的**唯一共同入口**，而\n  // `configuredModels` 只覆盖 `applySelection` 那条路。`refreshRegionCatalog`\n  // （点「刷新模型」走的路径）直接调 `stampRuntimeCatalog`，不经过\n  // `configuredModels` —— 停掉这一处之后那条路径仍会把抽象条目装回去。\n  //\n  // 放在这里的好处是三处同时生效：模型选择器（运行时目录）、卡片\n  // （`cardCatalog`）与池视图（读卡片那份），不会出现「卡片里没了、选择器里\n  // 还在」的半截状态。\n  const visible = withoutAbstractModels(models, region)\n  const images = new Set(imageModelKeysOf(config, region))\n  const withImages = withImageSelection(visible, images, imageSelectionSavedOf(config, region))\n  return stampOffSelection(config, region, withImages)\n}\n\n/** 某区域保存的 enabledModelKeys。 */\nfunction enabledModelKeysOf(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): readonly string[] {\n  const state = regionStateOf(config, region)\n  return Array.isArray(state.enabledModelKeys) ? (state.enabledModelKeys as string[]) : []\n}\n\n/** 某区域保存的 pool 偏好。 */\nfunction poolPreferencesOf(config: { regions?: Record<string, unknown> | null }, region: QoderRegion): {\n  enabled: boolean\n  targetModelId: string\n  probeInputTokens: number\n  memberAccountIds: readonly string[]\n  orderAccountIds: readonly string[]\n} {\n  const state = regionStateOf(config, region)\n  const raw = (state.pool ?? {}) as Record<string, unknown>\n  return {\n    enabled: raw.enabled === true,\n    targetModelId: typeof raw.targetModelId === 'string' ? raw.targetModelId : '',\n    probeInputTokens: typeof raw.probeInputTokens === 'number' ? raw.probeInputTokens : 0,\n    memberAccountIds: Array.isArray(raw.memberAccountIds) ? (raw.memberAccountIds as string[]) : [],\n    orderAccountIds: Array.isArray(raw.orderAccountIds) ? (raw.orderAccountIds as string[]) : [],\n  }\n}\n\n/** 把保存的目录条目解析为模型信息（历史兼容）。 */\nfunction modelFromStored(raw: Record<string, unknown>): QoderModelInfo | undefined {\n  if (typeof raw.key !== 'string' || typeof raw.displayName !== 'string') return undefined\n  // 活动规则：落盘形状就是解析后的 camelCase，读回只做校验。校验不过时当作\n  // 「这条目录条目没有活动」——这比带着一份读不懂的规则去判定要好。\n  const promotion = readPromotion(raw.promotion)\n  return {\n    key: raw.key,\n    displayName: raw.displayName,\n    priceFactor: typeof raw.priceFactor === 'number' ? raw.priceFactor : 1,\n    // 存档里的 contextWindow 是保存那一刻的生效窗口（可能正是被改写的 400K 档），\n    // 读回同样过改写表，否则旧快照会在实时目录缺席时把 400K 又显示回来。\n    contextWindow: typeof raw.contextWindow === 'number' ? mapContextTier(raw.contextWindow) : 200_000,\n    maxOutputTokens: typeof raw.maxOutputTokens === 'number' ? raw.maxOutputTokens : 32_768,\n    supportsImages: raw.supportsImages === true,\n    supportsThinking: raw.supportsThinking === true,\n    canDisableThinking: raw.canDisableThinking === true,\n    isDefault: raw.isDefault === true,\n    isFree: raw.isFree === true,\n    isNew: raw.isNew === true,\n    ...Array.isArray(raw.contextTiers) ? { contextTiers: mapContextTiers((raw.contextTiers as unknown[]).filter((v): v is number => typeof v === 'number')) } : {},\n    // 思考强度档位：从保存的目录里读回来，否则重启后模型行不再显示档位选择器。\n    ...Array.isArray(raw.thinkingEfforts) && raw.thinkingEfforts.length > 0\n      ? { thinkingEfforts: (raw.thinkingEfforts as unknown[]).filter((v): v is string => typeof v === 'string') }\n      : {},\n    ...typeof raw.defaultThinkingEffort === 'string' && raw.defaultThinkingEffort !== ''\n      ? { defaultThinkingEffort: raw.defaultThinkingEffort }\n      : {},\n    // 活动规则：落盘形状就是解析后的 camelCase，读回只做校验（见上）。\n    ...promotion === undefined ? {} : { promotion },\n  }\n}\n\n/** 某区域当前应展示的目录（保存 → 运行期 → fallback）。 */\nfunction configuredModels(\n  config: { regions?: Record<string, unknown> | null },\n  region: QoderRegion,\n  live: QoderModelInfo[],\n): QoderModelInfo[] {\n  const state = regionStateOf(config, region)\n  const saved = state.lastCatalog\n  if (Array.isArray(saved) && saved.length > 0) {\n    const parsed = saved\n      .map(item => modelFromStored((item ?? {}) as Record<string, unknown>))\n      .filter((m): m is QoderModelInfo => m !== undefined)\n    // 旧存档里的 `auto` 路由器在读点去掉（写点已由 `fetchModels` 拦下）。\n    // 刻意不迁移存档本身：存档保持上次刷新写下的原样，加载时不悄悄改写用户数据。\n    //\n    // 国际版那几个抽象命名的条目（Fast / Ultimate / Efficient / Sonus / Cantus）\n    // 同样在读点去掉：要求是「国际版不要显示」，而这几个 id 可能已经在别人的存档里。\n    const models = withoutAbstractModels(withoutRouters(parsed), region)\n    if (models.length > 0) return models\n  }\n  const fallback = withoutAbstractModels(QODER_FALLBACK_MODELS.map(fallbackModelInfo), region)\n  return live.length > 0 ? withoutAbstractModels(live, region) : fallback\n}\n\n/**\n * 把一次用量解析成卡片可渲染的积分包。\n *\n * ⚠️ **上游那个 `expiresAt` 不是积分包的到期**（issue #31 的主问题）：它是\n * `qoderUsage` 的同级字段，等于 `userId`（UUIDv7）前 48 bit + 14 天 ——\n * **账号级套餐 / 试用**的到期。`userQuota` / `addOnQuota` 自己都不带到期字段。\n * 此前它被挂到 `addon` 包上，于是「试用期到期」被显示成「积分包到期」，池排序\n * 也拿它当积分紧急度。现在它单独出 `planExpiresAtMs`，与积分彻底分开。\n *\n * 积分本身的到期只可能来自**签到批次**（上游 `validity.days` 只在活动里给过），\n * 那一路见 `credit-expiry.ts`。\n */\nexport function creditsOf(usage: QoderUsage): QoderWebCredits {\n  const packages: QoderWebCreditPackage[] = []\n  let total = 0\n\n  const add = (packageName: string, remaining: number, size: number): void => {\n    if (size <= 0) return\n    total += remaining\n    packages.push({ packageName, remain: remaining, size })\n  }\n\n  const userQuota = usage.userQuota\n  if (userQuota !== undefined && typeof userQuota.total === 'number') {\n    add('base', Math.max(userQuota.total - (userQuota.used ?? 0), 0), userQuota.total)\n  }\n  const addOnQuota = usage.addOnQuota\n  if (addOnQuota !== undefined && typeof addOnQuota.total === 'number') {\n    add('addon', Math.max(addOnQuota.total - (addOnQuota.used ?? 0), 0), addOnQuota.total)\n  }\n  const org = usage.orgResourcePackage\n  if (org !== undefined && typeof org.cap === 'number') {\n    add('org', Math.max(org.cap - (org.used ?? 0), 0), org.cap)\n  }\n\n  return {\n    total,\n    packages,\n    // 上游的 usage 报文不带「哪批积分何时过期」，所以这两项在这里恒为「不知道」，\n    // 由读了签到批次的调用方覆盖（`creditsWithExpiry`）。\n    expiringSoon: 0,\n    ...(usage.expiresAt === undefined ? {} : { planExpiresAtMs: usage.expiresAt }),\n  }\n}\n\n/**\n * 把签到批次的到期推算并进积分视图。\n *\n * 分成两步（而不是把批次塞进 `creditsOf`）的理由：`creditsOf` 是纯的、只吃\n * 一次 usage 报文；批次是**另一份状态**，进程重启后才需要落盘。分开之后，\n * 「没有批次」是一个自然状态（新装的插件、从没签到过），而不是一种要特判的错误。\n */\nexport function creditsWithExpiry(\n  credits: QoderWebCredits,\n  batches: readonly QoderCheckinBatch[],\n  nowMs: number = Date.now(),\n): QoderWebCredits {\n  const expiry = creditExpiryOf(batches, nowMs)\n  return {\n    ...credits,\n    expiringSoon: expiry.expiringAmount,\n    ...(expiry.nearestExpiryMs === undefined ? {} : { nearestExpiryMs: expiry.nearestExpiryMs }),\n  }\n}\n\ninterface QoderRegionStack {\n  upstream: QoderUpstreamClient\n  catalog: QoderCatalog\n  shim: QoderShim\n  store: QoderAccountStore\n  probeClient: QoderProbeClient\n  adapter?: QoderAdapter\n  /** Runtime probe store (batch tests + live failures), mirrors the disk store. */\n  poolRuntime: Record<string, QoderPoolProbe>\n  /**\n   * 已经对用户播报过的换号事实（见 `shouldAnnounceFailoverOnce`）。\n   *\n   * 有界：只在「同一件事重复发生」时增长，条目上限见\n   * `FAILOVER_ANNOUNCE_MAX_ENTRIES`，且账号一旦不再被排除就被清掉——上游恢复\n   * 后必须能重新说一次，否则「今天说过」会变成「永远不再说」。\n   */\n  announcedFailovers: Map<string, number>\n}\n\n/**\n * 换号播报去重的条目上限。\n *\n * 真实的键只有「失败账号 × 失败种类 × 接管账号」的组合，数量个位数；上限只是\n * 防止某个病态上游把两种 kind 交替着发、把 Map 撑大。超出时淘汰最久没用的\n * 那条 —— 淘汰只可能让用户**多看**一条，不会让一条该看的提示消失。\n */\nconst FAILOVER_ANNOUNCE_MAX_ENTRIES = 32\n\n// ---------------------------------------------------------------------------\n// apply\n// ---------------------------------------------------------------------------\n\nexport function apply(ctx: Context, config: Config): void {\n  const settingsNs = settingsNamespaceOf(ctx)\n  const log = (message: string): void => ctx.logger.warn(`dsh-connect-qoder: ${message}`)\n  let stopped = false\n\n  const stacks = {} as Record<QoderRegion, QoderRegionStack>\n  /**\n   * 每区域最近一次**上游明说**的额度耗尽（`liveQuotaExhaustion` 的落点）。\n   *\n   * 与 `stacks[].poolRuntime` 分开存：那份按账号、服务于池的换号决策；这份按\n   * 区域、只服务于 UI——usage 路由把它带进文档，卡片显示「最近一次」。进程内\n   * 状态（重启即清）：它说的是「上游最近一次说过」，不是「现在仍然耗尽」，\n   * 事实性由时间戳保证，不需要落盘承诺。\n   */\n  const quotaExhaustionByRegion: Partial<Record<QoderRegion, QoderWebQuotaExhaustion>> = {}\n  const usageCache: Partial<Record<QoderRegion, {\n    usage: QoderUsage | undefined\n    atMs: number\n    error?: string\n    /**\n     * 上一次**重读**失败了，但 `usage` 快照完好。路由把它映射成文档的\n     * `refreshError` 覆盖层，卡片据此说「刷新失败了，显示的是上次数据」。\n     */\n    staleError?: string\n  }>> = {}\n  const registration: Record<QoderRegion, { adapter?: AdapterRegistrationHandle, directory?: DirectoryRegistrationHandle }> = { cn: {}, global: {} }\n  /**\n   * 今日签到状态快照（区域 → 成员 id → 是否已领）。签到批次回写、成员表读取。\n   * 进程内即可：它描述的是「今天」，重启后由下一次签到重新写入。\n   */\n  const checkinState: Record<QoderRegion, Record<string, boolean>> = { cn: {}, global: {} }\n  /**\n   * 每区域的签到快照：每个成员「是否已领」+「下一窗何时刷新」（epoch 毫秒，\n   * 来自上游活动行的 `endAt`）。\n   *\n   * 为什么不能只留 `checkinState` 那个布尔表：「已领取」这句话离开「还有多久\n   * 刷新」是不完整的 —— 领取不是「今天到此为止」，只是这一窗从 `CLAIMABLE`\n   * 变成 `CLAIMED`，下一窗什么时候开上游早就写在 `endAt` 里了（实测活动窗是\n   * 当天 10:00 → 次日 09:59 UTC+8）。用户实拍里官网页面上那个 `09:22:23`\n   * 就是这个 `endAt − 当前时间`。\n   *\n   * 同样只在进程内：它描述的是「今天」，重启后由下一次签到重新写入。\n   */\n  const checkinSnapshots: Record<QoderRegion, Record<string, { claimed: boolean, refreshAtMs?: number }>> = { cn: {}, global: {} }\n\n  /**\n   * 每区域、每账号的**签到积分批次**（issue #31 建议 3）。\n   *\n   * 上游只在活动里给过 `validity.days`（30 天），`checkinSnapshots` 里没有\n   * 「什么时候领的」，所以算不出「这批 100 分什么时候作废」。这里补上\n   * `claimAtMs`（领取那一刻，本地记）与数额，由 `credit-expiry.ts` 按 FIFO\n   * 记账、按**悲观上界**显示。\n   *\n   * 与 `checkinSnapshots` 不同的是它**会落盘**：积分是有寿命的资产，进程重启\n   * 不该让「手上还有 100 分、30 天后过期」变成「不知道什么时候过期」。\n   */\n  const creditBatches: Record<QoderRegion, Record<string, QoderCheckinBatch[]>> = { cn: {}, global: {} }\n\n  /**\n   * 每区域、每账号**落过盘**的当日窗口结束时刻（issue #32 第三条）。\n   *\n   * 进程内快照 `checkinSnapshots` 一重启就没了，而 code 110 的 30 分钟兜底恰恰\n   * 只在「窗口时刻不知道」时生效 —— 于是兜底从「几乎不生效」变成「经常生效」。\n   * 这份是从 `$DSH_HOME/.qoder-pool.<region>.json` 的 `windows` 键读回来的。\n   */\n  const persistedWindows: Record<QoderRegion, Record<string, number>> = { cn: {}, global: {} }\n\n  /**\n   * 正在飞的批量动作（签到或测试）已处理完的那几行，按区域一个槽位。\n   *\n   * 为什么要它：两种批量都是**串行**的真实请求（一池六个号就是几分钟）。此前\n   * 卡片只能等整个响应回来才一次性写活动日志，于是六行日志盖上**同一个时刻**\n   * 落在一起（用户实拍：全是 05:44:54）——那几分钟里日志是空的，看起来跟卡死\n   * 没有区别。现在每处理完一个账号就往这里追加一行（带完成时刻），卡片用\n   * `action=progress` 每秒读一次，逐条落行、时间也是真的。\n   *\n   * 两个动作共用一把锁，所以不需要区分并发；批次结束即清空——完整结果本来就在\n   * 响应里，这个槽位只服务「在飞期间」。\n   */\n  const poolBatches: Partial<Record<QoderRegion, { action: 'checkin' | 'test', done: Array<{ atMs: number, row: QoderWebPoolTestRow | QoderWebPoolCheckinRow }> }>> = {}\n\n  function beginPoolBatch(region: QoderRegion, action: 'checkin' | 'test'): void {\n    poolBatches[region] = { action, done: [] }\n  }\n\n  function recordPoolBatchRow(region: QoderRegion, row: QoderWebPoolTestRow | QoderWebPoolCheckinRow): void {\n    const batch = poolBatches[region]\n    // 行级测试（只测一个号）不进槽位：它没有「批量在飞」这回事，卡片也只为批量\n    // 动作轮询进度——给它开槽位只会让下一次批量读到上一批的残行。\n    if (batch === undefined) return\n    batch.done.push({ atMs: Date.now(), row })\n  }\n\n  function endPoolBatch(region: QoderRegion): void {\n    delete poolBatches[region]\n  }\n\n  /**\n   * 每区域最近一次**实时**拉到的完整目录（含上游声明的思考档位），未过滤。\n   *\n   * 为什么要单独存：`stacks[region].catalog` 装的是**过滤后**（只含勾选模型）\n   * 的运行时目录，卡片不能用它；而保存的 `lastCatalog` 可能是**旧快照**，\n   * 上游新声明的思考档位会缺失（用户实拍「还是没有思考强度」——即使刚刚\n   * 「从 Qoder 刷新」成功过，卡片读的仍是那份没有档位的旧快照）。\n   * 实时目录优先于保存快照，才能反映上游当前声明了什么。\n   */\n  const fullCatalog: Record<QoderRegion, readonly QoderModelInfo[]> = { cn: [], global: [] }\n\n  /**\n   * 每区域**完整**的（未勾选过滤的）目录，由 `applySelection` / `refreshRegionCatalog`\n   * 写入 —— 卡片在「本进程还没成功拉到实时目录」时的兜底。\n   *\n   * 为什么不能退回运行时目录（issue #33）：运行时目录被 `deriveCatalog` 按勾选裁过，\n   * 用它兜底会让「未勾选的模型从卡片上消失」，而这正是 `displayModels` 的注释里\n   * 说要避免的那件事 —— 注释与实现自相矛盾。更关键的是，池的目标解析（以及测试\n   * 路由）读的就是 `displayModels`：兜底一旦是被裁的那份，用户「手选了一个没勾的\n   * 模型」或「自动档唯一的免费模型没被勾」就会在**冷启动、首次实时拉取失败**这个\n   * 窗口里解不出目标，症状与 issue #33 一模一样。\n   */\n  const cardCatalog: Record<QoderRegion, readonly QoderModelInfo[]> = { cn: [], global: [] }\n\n/**\n * 卡片展示用的模型列表（workbuddy 的 `displayModels` 同规）。\n *\n * 与运行时目录（`stacks[region].catalog`）的区别只有一条，但它是关键：\n * **运行时目录只含用户勾选的模型**（DSH 的选择器读它），而卡片必须看到**完整\n * 目录**，否则未勾选的模型根本不出现在卡片里，用户再也勾不上它们。\n *\n * 实时目录（`fullCatalog`）优先于运行时目录：实时目录反映上游**当前**声明了\n * 什么（含思考档位），而运行时目录是启动时由保存的 lastCatalog 装配的 ——\n * 那是上一次保存时的旧快照（issue #32 的教训：保存槽位丢了目录时必须显示\n * 实时目录，否则卡片会把用户正在用的模型报成「已下架」）。\n *\n * 「思考强度有时候有、有时候没有」（用户实拍）的机制也在这条读路径上：\n * `fullCatalog` 是纯内存的、只在启动时拉一次；启动那次失败的话，卡片每次\n * 读到的都是启动装配的旧快照 —— 一个档位都没有，直到用户手动点一次\n * 「从 Qoder 刷新」。所以读到「本进程还没成功拉过实时目录 + 手上的目录一个\n * 档位都没声明」时，**触发一次后台重拉**（fire-and-forget，见\n * ensureCatalogRefresh）并且**继续服务手上的目录** —— 模型不能从卡片上消失，\n * 缺的只是档位，拉回来之后下一次读取自然补上。\n */\nfunction displayModels(region: QoderRegion): readonly QoderModelInfo[] {\n  const full = fullCatalog[region]\n  // 兜底顺序：实时目录 → `applySelection` 写下的完整目录 → 运行时目录。\n  // 第三档只是最后一道保险（理论上 `applySelection` 在装配时就写过一次）：\n  // 它可能被裁过，但「有一份能显示的目录」仍好过空表。\n  const live = full.length > 0\n    ? full\n    : cardCatalog[region].length > 0 ? cardCatalog[region] : stacks[region].catalog.current()\n  if (full.length === 0) {\n    // 判据与动作打包在 serveSavedCatalog 里（空档位目录 → 触发一次拉取）。\n    // 只在还没有实时目录时判：真拉到的目录没档位是上游的诚实答案，再判就是\n    // 白白在读路径上打网络。\n    serveSavedCatalog(live, () => { ensureCatalogRefresh(region) })\n  }\n  // catalog 构造时种了静态兜底列表、`set()` 拒绝空数组，live 恒非空，\n  // 不需要再垫一层空兜底。\n  return live\n}\n\n  /**\n   * 幂等地触发一次该区域的目录拉取（**不等待**）。\n   *\n   * 为什么不等待：`displayModels` 是**读**路径，被 `/usage` 路由同步调用；在里面\n   * await 网络会让「卡片读一次快照」这个纯读动作每次都等一次上游。改为\n   * fire-and-forget + 在飞标记去重，拉取完成后下一次读取自然拿到新目录。\n   *\n   * 为什么需要它：目录此前**只在启动时拉一次**（`refreshModels`），而 `fullCatalog`\n   * 是纯内存的。于是「思考强度」在重启后必然退化成那份空快照 —— 除非用户恰好\n   * 去点一次「从 Qoder 刷新」。有没有点过刷新、以及进程活多久，就是「有时候有、\n   * 有时候没有」的全部来源。\n   */\n  const catalogRefreshInFlight: Partial<Record<QoderRegion, boolean>> = {}\n  const ensureCatalogRefresh = (region: QoderRegion): void => {\n    if (catalogRefreshInFlight[region] === true) return\n    catalogRefreshInFlight[region] = true\n    // 不 await：读路径不能被网络拖住。\n    refreshModels(region).finally(() => { catalogRefreshInFlight[region] = false })\n  }\n\n  let invalidateCatalog = (): void => {}\n\n  // 每个区域：上游客户端 + 回环 shim + vault store + 池运行期。\n  for (const region of QODER_REGIONS) {\n    const upstream = new QoderUpstreamClient(region, { logger: log })\n    const catalog = new QoderCatalog(QODER_FALLBACK_MODELS.map(fallbackModelInfo))\n    const store = new QoderAccountStore(region)\n    let poolRuntime: Record<string, QoderPoolProbe> = {}\n    // 开屏的磁盘读数**合并**进已有的运行期记录，而不是整个替换：`probeThrough`\n    // 等在 `apply` 期间就已经在跑，它们写的探针若被这次替换覆盖，等于上线后\n    // 一分钟内的失败判定被悄悄忘掉（磁盘那次读可能更旧）。\n    //\n    // 同一次读顺带装回签到批次与窗口时刻（issue #31 建议 3 / #32 第三条）：\n    // 这两份是「领到的积分什么时候作废」与「当日窗口何时结束」的唯一来源，\n    // 只活在进程内时，一次重启就把它们清零 —— 而它们描述的其实都是**已经\n    // 发生过的事实**，与进程活多久无关。\n    void readPoolDocument(region).then((document) => {\n      poolRuntime = { ...document.probes, ...poolRuntime }\n      const stack = stacks[region]\n      if (stack !== undefined) stack.poolRuntime = poolRuntime\n      // 内存里已经有的（本次进程刚签过）优先，磁盘的只补空缺。\n      creditBatches[region] = { ...document.credits, ...creditBatches[region] }\n      persistedWindows[region] = { ...document.windows, ...persistedWindows[region] }\n    })\n    // 换号播报去重：与 `poolRuntime` 同生命周期、每区域一份。\n    const announcedFailovers = new Map<string, number>()\n\n    const shim = createQoderShim({\n      upstream,\n      credential: () => resolveServingPat(region),\n      modelKeyOf: selector => catalog.keyOf(selector),\n      supportsImagesOf: selector => catalog.supportsImagesOf(selector),\n      // 设置里为这个模型保存的思考强度（模型选择器名 → 档位名）。目录换代后\n      // 旧 key 自然失配（返回 undefined），请求退回模型默认档，不需要额外清理。\n      reasoningEffortOf: selector => {\n        const key = catalog.keyOf(selector)\n        if (key === undefined) return undefined\n        return thinkingEffortsOf(config, region)[key]\n      },\n      logger: log,\n      resolveServing: async () => {\n        const serving = await resolveServing(region)\n        return serving === undefined\n          ? undefined\n          : { accountId: serving.id, accountName: serving.accountName, pat: serving.pat }\n      },\n      failoverAccount: async tried => nextFailoverCredential(region, tried),\n      // 上游说「排队中、等 N 秒」时，在这一层等掉（issue #29）：\n      // 宿主的重试阶梯是递增的（5s → 10s → 20s），前两次一定短于上游申报的\n      // 30 秒；`pi-ai` 路由又没有 `providerRetryAfterMs` 通道，插件只能自己等。\n      queueWaitMaxMs: queueWaitMsOf(config, region) ?? 0,\n      onServingFailure: (accountId, kind, message, context) => {\n        // 区域级通知先记（与池无关）：池关着时这是 code 110 唯一的 UI 出口。\n        const exhaustion = liveQuotaExhaustion(kind, message, context, Date.now())\n        if (exhaustion !== undefined) quotaExhaustionByRegion[region] = exhaustion\n        // 池关着也要记账（只进内存）：否则「这个号今天已用尽」永远不知道，\n        // 每个回合都要先撞一次 110、再白等 2 秒换号。\n        //\n        // issue #32：把「当日额度窗口何时结束」也递给它。真实请求撞 `110` 时\n        // 报文里没有等待时长，此前这条路径只能落一条没有 `retryAtMs` 的记录，\n        // 池子按 30 分钟兜底 —— 一个要等到次日窗口才恢复的号被每 30 分钟试探\n        // 一次。探测路径早就接了这个值（`probeThrough`），这里此前没接。\n        const probe = liveRequestProbe(kind, message, undefined, {\n          ...context,\n          // 进程内快照 → 其次磁盘（issue #32 第三条：重启不该让兜底必然生效）。\n          ...quotaRefreshOfStored(checkinSnapshots[region], persistedWindows[region], accountId),\n        })\n        if (probe === undefined || accountId === '') return\n        poolRuntime[accountId] = probe\n        // 持久化仍只写「池开着 + 是成员」的账号：见 `shouldRecordPoolFailure`\n        // 的两条守卫，那是写盘承诺，不该被内存记账顺手扩大。\n        if (shouldRecordPoolFailure(poolPreferencesOf(config, region), accountId)) {\n          void writePoolProbes(region, { [accountId]: probe })\n          log(`pool ${region}: ${maskPat(accountId)} marked ${probe.outcome} by live request`)\n        }\n      },\n      // 已知被排除（例如当日用尽、次日才恢复）的换号候选不再重试：过去这里会\n      // 先睡 2 秒、再拿同一个请求撞一次必然失败的上游。\n      isAccountExcluded: (accountId) => {\n        const probe = poolRuntime[accountId]\n        if (probe === undefined) return false\n        const targetModelId = poolTargetOf(region).modelId\n        // 上游恢复后必须能重新播报：记录只在仍然被排除时才有意义。\n        if (exclusionOf(probe, Date.now(), targetModelId) === undefined) {\n          clearAnnouncedFailoversFrom(announcedFailovers, accountId)\n          return false\n        }\n        return true\n      },\n      // 换号后把「哪个账号、因为什么」告诉用户。\n      //\n      // 与「将由账号 … 回答本次问题」不同：那条是关于**将要**发生的事，属于\n      // 宿主的调度决定；这条是插件**已经**自作主张换了号，用户有权知道。不提示\n      // 的话，用户看到一段正常回答，既不知道换过号，也不知道自己选的账号已经\n      // 出问题，下次还会踩进去。\n      //\n      // 三种措辞（issue #29）：上游整体不可用 → 明说「不是该账号的问题」；\n      // 单纯排队 → 「排队中」；其余走 kind 的通用理由。\n      failoverNotice: (from, _to, kind, context) => {\n        const label = { accountName: from.accountName, accountId: from.accountId }\n        if (context?.queue?.isQueued === true && context.queue.serviceAvailable === false) {\n          return upstreamDownFailoverNoticeText(label)\n        }\n        return context?.queue?.isQueued === true\n          ? queuedFailoverNoticeText(label)\n          : failoverNoticeText(label, kind)\n      },\n      // 同一个事实只说一次：一次 Agent 回合有十几轮调用，每轮都以同样的方式\n      // 换号时，用户不该读到十几条一模一样的引用条。\n      hasAnnouncedFailover: (from, to, kind) =>\n        shouldAnnounceFailoverOnce(announcedFailovers, {\n          fromAccountId: from.accountId,\n          toAccountId: to.accountId,\n          kind,\n        }),\n    })\n\n    stacks[region] = {\n      upstream, catalog, shim, store, probeClient: buildProbeClient(region), poolRuntime,\n      announcedFailovers,\n    }\n  }\n\n  /** The region's source PATs (settings + env). */\n  function sourcesOf(region: QoderRegion): { settingsPat?: string | undefined, envPat?: string | undefined } {\n    const state = regionStateOf(config, region)\n    const settingsPat = typeof state.pat === 'string' ? (state.pat as string).trim() : ''\n    const envPat = patFromEnv(region)\n    return {\n      ...settingsPat === '' ? {} : { settingsPat },\n      ...envPat === undefined ? {} : { envPat },\n    }\n  }\n\n  /** The region's auto-resolved serving PAT (settings → env). Vault is async. */\n  function resolveServingPat(region: QoderRegion): string | undefined {\n    const sources = sourcesOf(region)\n    if (sources.settingsPat) return sources.settingsPat\n    if (sources.envPat) return sources.envPat\n    return undefined\n  }\n\n  /** Full serving credential via the store (honors selection + vault). */\n  async function resolveServing(region: QoderRegion): Promise<\n    { id: string, pat: string, accountName: string, source: 'settings' | 'env' | 'vault' } | undefined\n  > {\n    return stacks[region].store.resolve(sourcesOf(region), selectedAccountId(config, region))\n  }\n\n  /** Next usable PAT for failover: rankPool over members, skip tried. */\n  async function nextFailoverCredential(region: QoderRegion, tried: readonly string[]): Promise<QoderServingAccount | undefined> {\n    const store = stacks[region].store\n    const prefs = poolPreferencesOf(config, region)\n    if (!poolAllowsFailover(prefs)) return undefined\n    const memberIds = prefs.memberAccountIds\n    const probes = stacks[region].poolRuntime\n    const now = Date.now()\n    // 请求路径不能上网，积分取卡片路由写入的快照（workbuddy 的 creditsSnapshot\n    // 同规）：新鲜时用真实余额参与排名，过期则退回「只有探针」的排名。\n    const fresh = now - (poolCreditsSnapshotAt[region] ?? 0) <= POOL_CREDITS_SNAPSHOT_MS\n    const snapshot = fresh ? poolCreditsSnapshot[region] : undefined\n    const candidates: QoderPoolMember[] = []\n    for (const accountId of memberIds) {\n      if (tried.includes(accountId)) continue\n      const credit = await store.credentialFor(accountId, sourcesOf(region))\n      if (credit === undefined) continue\n      const probe = probes[accountId]\n      const reading = snapshot?.get(accountId)\n      candidates.push({\n        account: { id: credit.id, accountName: credit.accountName },\n        ...reading === undefined ? {} : { credits: reading },\n        ...probe === undefined ? {} : { probe },\n      })\n    }\n    // 换号按同一个目标模型判：一条「模型 A 能用」的探针，不能替模型 B\n    // 担保。目标模型解析不出来时传 undefined，退回修复前的无作用域行为。\n    // 用户排定的优先级（`orderAccountIds`）压过积分策略，但可用性与临期积分\n    // 仍然优先（见 `rankPool` 的注释）。没排过就完全按积分策略。\n    const chosen = rankPool(\n      candidates,\n      now,\n      poolTargetOf(region).modelId,\n      prefs.orderAccountIds,\n    )[0]\n    if (chosen === undefined || chosen.excludedBy !== undefined) return undefined\n    const credit = await store.credentialFor(chosen.account.id, sourcesOf(region))\n    return credit === undefined ? undefined : { accountId: credit.id, accountName: credit.accountName, pat: credit.pat }\n  }\n\n  /** 成员积分快照：请求路径不能上网，排名用卡片路由最近一次的读数。 */\n  const poolCreditsSnapshot: Partial<Record<QoderRegion, ReadonlyMap<string, QoderPoolCredits>>> = {}\n  const POOL_CREDITS_SNAPSHOT_MS = 10 * 60_000\n  const poolCreditsSnapshotAt: Partial<Record<QoderRegion, number>> = {}\n  /** 这份快照是「问哪几个账号」问出来的：请求的成员集合变了就不能复用。 */\n  const poolCreditsRequested: Partial<Record<QoderRegion, string>> = {}\n  /**\n   * 卡片读数的复用窗口。\n   *\n   * 批量在飞时卡片每 2.5 秒重读一次 usage，而每次读取都会**为每个成员各发一次**\n   * usage 请求（`poolMemberCredits`）——六个号就是每分钟 144 次上游调用，纯属\n   * 浪费，还可能撞限流。积分不是秒级变化的东西，15 秒内复用同一份读数，肉眼\n   * 看不出差别，上游负载降一个数量级。（签到领了分是例外：那时会主动作废，\n   * 见 `runCheckinBatch` 末尾。）\n   */\n  const POOL_CREDITS_CARD_TTL_MS = 15_000\n\n  /**\n   * 池成员的最新积分（每成员一次 usage 读数）。由卡片路由付费——卡片正在看的\n   * 数字与排名快照同一次读取（workbuddy 的 poolMembersOf 同规），单个账号失败\n   * 只让那一行显示「—」，不拖垮整张表。\n   */\n  async function poolMemberCredits(region: QoderRegion, accountIds: readonly string[]): Promise<ReadonlyMap<string, QoderPoolCredits>> {\n    const requested = accountIds.join('\\u0000')\n    const cached = poolCreditsSnapshot[region]\n    if (cached !== undefined\n      && poolCreditsRequested[region] === requested\n      && Date.now() - (poolCreditsSnapshotAt[region] ?? 0) <= POOL_CREDITS_CARD_TTL_MS) {\n      return cached\n    }\n    const store = stacks[region].store\n    const now = Date.now()\n    const entries = await Promise.all(accountIds.map(async accountId => {\n      const credit = await store.credentialFor(accountId, sourcesOf(region)).catch(() => undefined)\n      if (credit === undefined) return undefined\n      const usage = await stacks[region].upstream.fetchUsage(credit.pat).catch(() => undefined)\n      if (usage === undefined) return undefined\n      // issue #31：临期金额只有一个来源 —— 签到批次。上游 usage 报文不带批次的\n      // 到期时刻，而那个伪装成 `packages[].expiresAtMs` 的 `expiresAt` 其实是\n      // 账号套餐到期，不该在这里被当成积分紧急度。\n      const view = creditsWithExpiry(creditsOf(usage), creditBatches[region]?.[accountId] ?? [], now)\n      return [accountId, {\n        total: view.total,\n        expiringSoon: view.expiringSoon,\n        ...(view.nearestExpiryMs === undefined ? {} : { nearestExpiryMs: view.nearestExpiryMs }),\n        ...(view.planExpiresAtMs === undefined ? {} : { planExpiresAtMs: view.planExpiresAtMs }),\n      }] as const\n    }))\n    const map = new Map(entries.filter((entry): entry is NonNullable<typeof entry> => entry !== undefined))\n    poolCreditsSnapshot[region] = map\n    poolCreditsSnapshotAt[region] = Date.now()\n    poolCreditsRequested[region] = requested\n    return map\n  }\n\n  /**\n   * 首屏用的成员积分：只答**已经量过**的那份快照，一次上游都不打。\n   *\n   * `poolMemberCredits` 是诚实但昂贵的版本——每个成员一次真实 usage 读数，串在\n   * usage 文档的尾巴上 await。冷进程（或上游慢/被限流）时它能把设置页的账号\n   * 列表扣住几十秒，这正是同族插件 issue #77 报的症状。\n   *\n   * 快照新鲜度仍按 `POOL_CREDITS_SNAPSHOT_MS` 判：过期的读数拿来当「现在」是\n   * 另一种谎，宁可让那一列显示「—」（没量过），完整文档随后立刻补上真数字。\n   * 返回 `undefined` 表示这一区还什么都没量过。\n   */\n  function cachedMemberCredits(region: QoderRegion, accountIds: readonly string[]): ReadonlyMap<string, QoderPoolCredits> | undefined {\n    const snapshot = poolCreditsSnapshot[region]\n    if (snapshot === undefined) return undefined\n    if (Date.now() - (poolCreditsSnapshotAt[region] ?? 0) > POOL_CREDITS_SNAPSHOT_MS) return undefined\n    // 快照是多问出来的那批 id 的答案；只挑这次要的那几个，避免把已退出成员\n    // 的旧读数算进去。\n    const picked = new Map<string, QoderPoolCredits>()\n    for (const accountId of accountIds) {\n      const reading = snapshot.get(accountId)\n      if (reading !== undefined) picked.set(accountId, reading)\n    }\n    return picked.size === 0 ? undefined : picked\n  }\n\n  /** A probe client for one region backed by chatStream. */\n  function buildProbeClient(region: QoderRegion): QoderProbeClient {\n    return {\n      probeChat: async (credential, modelKey, opts) => {\n        let firstBytes = 0\n        let error: QoderUpstreamError | undefined\n        try {\n          await stacks[region].upstream.chatStream(credential.pat, modelKey, [\n            { role: 'user', content: probeUserMessage(opts.inputTokens) },\n          ], {\n            ...opts.signal === undefined ? {} : { signal: opts.signal },\n            isReasoning: false,\n            isVl: false,\n            onDelta: (delta: QoderChatDelta) => {\n              // 探针只关心“有没有吐出首包”。\n              if (firstBytes === 0) firstBytes = cheapProbeLength(delta)\n            },\n          })\n        } catch (caught: unknown) {\n          if (isQoderUpstreamError(caught)) error = caught\n          else throw caught\n        }\n        if (error !== undefined) {\n          // issue #26：上游**自己申报**的两件事此前在这里被丢掉 ——\n          // ① `retryAfterMs`（「等 30 秒」被放大成 30 分钟冷却）；\n          // ② `queue`（`isQueued` ⇒ 明明在排队，却被报成「连不上上游」）。\n          // 两者都已经在上游客户端里解析好了（`QoderUpstreamError`），这一行\n          // 只是把它们带过门槛。\n          const probeError: QoderProbeError = {\n            kind: error.kind,\n            status: error.status,\n            message: error.message,\n            ...error.retryAfterMs === undefined ? {} : { retryAfterMs: error.retryAfterMs },\n            ...error.queue === undefined ? {} : { queue: error.queue },\n          }\n          return {\n            ok: false,\n            status: error.status,\n            retryAfter: null,\n            ...error.retryAfterMs === undefined ? {} : { retryAfterMs: error.retryAfterMs },\n            body: error.message,\n            error: probeError,\n          }\n        }\n        return { ok: true, status: 200, retryAfter: null }\n      },\n    }\n  }\n\n  /** Cheap text length of a delta for probe first-byte accounting. */\n  function cheapProbeLength(delta: QoderChatDelta): number {\n    let length = delta.content.length\n    if (delta.reasoningContent.length > 0) length += delta.reasoningContent.length\n    if (delta.toolCalls !== undefined) length += delta.toolCalls.length\n    return length\n  }\n\n  /** One real probe of one model through one credential. Never throws. */\n  async function probeThrough(region: QoderRegion, credential: { pat: string, accountName: string }, modelId: string, signal?: AbortSignal): Promise<QoderWebProbeResult> {\n    return probeModel({\n      client: stacks[region].probeClient,\n      credential,\n      modelKey: modelId,\n      nowMs: Date.now(),\n      // 「当日用量用尽」的恢复时刻是**次日窗口开启**，不是 30 分钟。\n      //\n      // `cooldownOf` 本来就支持这条来源（Retry-After > 上游报文里的重置时刻 >\n      // out-of-credit 的额度刷新点），但这一路此前**没有任何调用方传过**\n      // `quotaRefreshAtMs`，于是 out-of-credit 永远走 `atMs + 30min` 兜底：\n      // 一个要等到明天才恢复的号，30 分钟后就被当成可用号重新挑中，请求再\n      // 撞一次 110，如此循环。\n      //\n      // 来源用签到快照里的每日窗口结束时刻（`refreshAtMs`，上游给的\n      // `daily.endAt`），快照缺席时再看落过盘的那份（issue #32 第三条）。\n      // 两者都没有时仍然不传 —— 宁可用 30 分钟兜底，也不在本机编一个「次日\n      // 零点」：官方页面上那个数字才是准的，编出来的会让用户在错的时候回来。\n      ...quotaRefreshOfStored(\n        checkinSnapshots[region],\n        persistedWindows[region],\n        qoderAccountId(credential.pat),\n      ),\n      ...(signal === undefined ? {} : { signal }),\n    })\n  }\n\n  /**\n   * 对一个区域勾选的成员逐个签到（领取当日 Credits）。\n   *\n   * 与 `test` 批次同构：只跑**真的有凭据**的成员（幽灵 id 跳过，见 test 里那段\n   * 注释），逐个之间留间隔避免撞限流。每个成员独立成败——一个账号失败不影响\n   * 其余账号，结果逐行回报（workbuddy 的 checkin 批次同规）。\n   *\n   * 三种状态分得很清：`claimed`（这次领到）/ `already`（今天已领，幂等，\n   * **不是**失败）/ `failed`（真的失败：凭据被拒、上游报错）。\n   */\n  /**\n   * 把一行的签到结果并进快照：成员表据此显示「已签到 / 未签到」以及「还有多久刷新」。\n   *\n   * `claimed` 与 `already` 都算「今天已领」——两者的区别只对**本次操作**有意义\n   * （领到了 vs 早就领过），对「今天是否已签到」这个事实没有区别。\n   *\n   * 失败**不**写 `refreshAtMs`：这一次没拿到上游的开窗时间，宁可不说，也不把\n   * 上一次成功留下的时间当成这次的答案。\n   */\n  function applyCheckinRow(region: QoderRegion, row: QoderWebPoolCheckinRow): Promise<void> {\n    const next = { ...(checkinState[region] ?? {}) }\n    const nextSnapshot = { ...(checkinSnapshots[region] ?? {}) }\n    if (row.status === 'claimed' || row.status === 'already') {\n      next[row.accountId] = true\n      nextSnapshot[row.accountId] = {\n        claimed: true,\n        ...(row.refreshAtMs === undefined ? {} : { refreshAtMs: row.refreshAtMs }),\n      }\n    } else if (row.status === 'failed') {\n      next[row.accountId] = false\n      nextSnapshot[row.accountId] = { claimed: false }\n    }\n    checkinState[region] = next\n    checkinSnapshots[region] = nextSnapshot\n\n    // ---- 落盘的两件事（issue #31 建议 3 / #32 第三条）----\n    //\n    // 只对 `claimed` 记批次：`already` 是「今天早上/别人的进程领过」，我们不知道\n    // 那一刻、也不知道数额。按「宁缺勿错」写一个猜出来的 `claimAtMs` 会让「这批\n    // 积分 30 天后作废」这个提醒整体失真 —— 而它存在的意义就是准时。\n    const patches: {\n      credits?: Readonly<Record<string, readonly QoderCheckinBatch[]>>\n      windows?: Readonly<Record<string, number>>\n    } = {}\n    if (row.status === 'claimed' && row.validityDays !== undefined) {\n      const now = Date.now()\n      const batches = appendCheckinBatch(\n        creditBatches[region][row.accountId] ?? [],\n        {\n          atMs: now,\n          validityDays: row.validityDays,\n          ...(row.credit === undefined ? {} : { amount: row.credit }),\n        },\n        now,\n      )\n      creditBatches[region] = { ...creditBatches[region], [row.accountId]: batches }\n      patches.credits = { [row.accountId]: batches }\n    }\n    if (row.refreshAtMs !== undefined) {\n      persistedWindows[region] = { ...persistedWindows[region], [row.accountId]: row.refreshAtMs }\n      patches.windows = { [row.accountId]: row.refreshAtMs }\n    }\n    // 落盘的 Promise 交回给批次，而不是 fire-and-forget：切换号/重启之间只要\n    // 差几百毫秒，这一批积分就会在重启后彻底失去「何时作废」这个事实。批次\n    // 本来就是串行的（每个账号之间还有间隔），等这一次文件写没有任何代价。\n    if (patches.credits === undefined && patches.windows === undefined) return Promise.resolve()\n    return writePoolDocument(region, patches)\n  }\n\n  async function runCheckinBatch(region: QoderRegion): Promise<QoderWebPoolCheckinRow[]> {\n    const store = stacks[region].store\n    const prefs = poolPreferencesOf(config, region)\n    const client = stacks[region].upstream\n    const rows: QoderWebPoolCheckinRow[] = []\n    beginPoolBatch(region, 'checkin')\n    try {\n      let first = true\n      for (const accountId of prefs.memberAccountIds) {\n        const credit = await store.credentialFor(accountId, sourcesOf(region))\n        if (credit === undefined) continue\n        if (!first) await new Promise(resolve => setTimeout(resolve, POOL_BATCH_GAP_MS))\n        first = false\n        const base = { accountId, accountName: credit.accountName }\n        let row: QoderWebPoolCheckinRow\n        try {\n          const outcome = await client.claimDailyCredits(credit.pat)\n          // 「下一窗何时刷新」**两种成功都要带**（claimed 与 already）。上游的\n          // `endAt` 就是这个数，不带它 UI 只能说「已领取」，用户会以为要等到明天\n          // 零点 —— 而官网页面上写着次日 10:00（用户实拍）。\n          const refresh = outcome.status === 'unavailable' ? {} : outcome.nextRefreshAtMs === undefined ? {} : { refreshAtMs: outcome.nextRefreshAtMs }\n          if (outcome.status === 'claimed') {\n            row = {\n              ...base,\n              status: 'claimed',\n              ...(outcome.amount === undefined ? {} : { credit: outcome.amount }),\n              ...(outcome.validityDays === undefined ? {} : { validityDays: outcome.validityDays }),\n              ...refresh,\n            }\n          } else if (outcome.status === 'already-claimed') {\n            row = { ...base, status: 'already', ...refresh }\n          } else {\n            row = { ...base, status: 'failed', message: outcome.message }\n          }\n        } catch (error: unknown) {\n          row = { ...base, status: 'failed', message: error instanceof Error ? error.message : String(error) }\n        }\n        rows.push(row)\n        // 每签完一个就写进快照：成员表的「已签到 / 还有多久刷新」逐个落位。签到\n        // 不再抬遮罩（用户要求），界面靠这次即时写入加卡片在飞期间的轮询看到进度；\n        // 等整批结束才写，那几秒里表是不动的。\n        await applyCheckinRow(region, row)\n        // 同时交给进度槽位：卡片的活动日志据此**逐条**落行（用户实拍：六条日志\n        // 全压在同一秒，因为原先等整批响应回来才一次性写）。\n        recordPoolBatchRow(region, row)\n      }\n    } finally {\n      endPoolBatch(region)\n    }\n    // 签到会改变积分余额：必须**重新拉一次**，否则这个区域的积分会一直停在签到\n    // 前的数字，直到某个**与签到无关**的动作（改配置 / 点「从 Qoder 刷新」）\n    // 顺带触发 `refreshUsage` —— 用户看到的就是「我领了积分，但积分没刷新」\n    // （用户实拍）。此前这里只 `delete usageCache[region]`：作废了缓存却没有\n    // 任何人来重新填充它，等于把「读到新值」这件事推给了一个不会到来的下一次\n    // 无关动作。\n    //\n    // **await 而非 fire-and-forget**：客户端在收到签到响应后立刻调 `onChanged()`\n    // 重新读一次 usage（`AccountPool.runCheckinBatch` 末尾）。若这里不等待，\n    // 这次重读会发生在上游返回之前、读到刚被作废的空缓存，积分仍然不刷新 ——\n    // 竞态，而不是修复。\n    //\n    // 失败不影响签到本身：结果已经如实回报给用户了，积分补读失败只是这一格数字\n    // 没更新，下一次轮询会再试。\n    await refreshUsageCoalesced(region).catch(() => {})\n    // 成员积分读了会走卡片那个 15 秒复用窗口（见 `poolMemberCredits`）：签到\n    // 刚改过余额，这份快照必须作废，否则用户「领了分但积分没动」——正是这条\n    // 刷新逻辑当初要修的那个观感，只是换了个位置复现。\n    poolCreditsSnapshotAt[region] = 0\n    return rows\n  }\n\n  /** Cached usage read for one region. */\n  function usageEntryOf(region: QoderRegion): {\n    usage?: { credits: QoderWebCredits, atMs: number }\n    error?: string\n    staleError?: string\n  } | undefined {\n    const entry = usageCache[region]\n    if (entry === undefined) return undefined\n    return {\n      // 积分到期（`expiringSoon` / `nearestExpiryMs`）**不在这里合并批次**：\n      // 这份 usage 文档是**区域级**的（一个正在服务的账号），而批次是**按账号**\n      // 的事实。区域级文档里塞一个人的批次，换号之后就会张冠李戴。\n      // 逐账号的那一份在池表格里（`poolMemberCredits`），两处读的是同一个\n      // `creditsWithExpiry`，只是各取各的账号。\n      // 套餐到期（`planExpiresAtMs`）倒是账号级的，但它随 usage 一起下来，\n      // `creditsOf` 已经带上了。\n      ...(entry.usage === undefined ? {} : { usage: { credits: creditsOf(entry.usage), atMs: entry.atMs } }),\n      ...(entry.error === undefined ? {} : { error: entry.error }),\n      ...(entry.staleError === undefined ? {} : { staleError: entry.staleError }),\n    }\n  }\n\n  /**\n   * 在飞的积分刷新（区域 → promise）。\n   *\n   * `/usage` 现在每次请求都要现场刷一次积分，而这个路由的调用方不止一个：卡片\n   * 卡片轮询、composer 轮询（同一条 `pollMinutes` 节奏）、面板打开、手动刷新。它们可能几乎同时打到同一\n   * 区域 —— 没有合流的话，一次面板打开会连带触发好几条上游读。\n   *\n   * **所有**积分读都必须经过这里，包括那些 fire-and-forget 的后台补读（签到后\n   * 补读、目录刷新完补读、写配置后全区补读）。此前它们直接调 `refreshUsage`，\n   * 于是同一次操作能打出两次上游读 —— 上游一慢就稳定复现。合流只有在「一个入口」\n   * 的前提下才是真的。\n   */\n  const usageRefreshInFlight: Partial<Record<QoderRegion, Promise<void>>> = {}\n\n  /** One upstream credits read per region at a time; late callers join it. */\n  const refreshUsageCoalesced = (region: QoderRegion): Promise<void> => {\n    const running = usageRefreshInFlight[region]\n    if (running !== undefined) return running\n    const next = refreshUsage(region).finally(() => {\n      if (usageRefreshInFlight[region] === next) delete usageRefreshInFlight[region]\n    })\n    usageRefreshInFlight[region] = next\n    return next\n  }\n\n  const refreshUsage = async (region: QoderRegion): Promise<void> => {\n    const serving = await resolveServing(region)\n    if (!serving) return\n    const prior = usageCache[region]\n    try {\n      // 超时兜底：这个读现在发生在**每次** /usage 请求上（卡片与 composer 的\n      // 自动刷新轮询都打到这里），上游挂住不能把路由一起挂住。\n      //\n      // 为什么是整体 race 而不是只传 signal：`fetchUsage` 先 `ensureSession()`、\n      // 再带着 signal 打 sash —— signal 只管得住后半段。会话过期时前半段要去做\n      // jobToken 交换，它挂住的话 signal 还没生效，路由就无限期吊着（卡片每 60s\n      // 再打一次，会一层层堆上去）。超时后走下面的保旧值路径。\n      const usage = await withHardTimeout(\n        stacks[region].upstream.fetchUsage(serving.pat, AbortSignal.timeout(USAGE_FETCH_TIMEOUT_MS)),\n        USAGE_FETCH_TIMEOUT_MS,\n      )\n      if (usage === undefined) {\n        // 「这次没读到」（超时 / 5xx / 网关抖动），不是「凭据坏了」。旧写法把\n        // undefined 直接写进缓存，面板于是从「数字旧」变成「没数字」——以前这条\n        // 只在四个时机被触发所以少见，改成每请求一刷之后会被放大成常态。\n        // 所以保留上一次的好快照与它的读取时刻（atMs 不更新：它标的是**数据**何时\n        // 读到的，不是本次尝试的时刻），并把失败记成覆盖层 —— `refreshError` 这个\n        // 字段与卡片分支早就写在契约里，此前从没人赋值。\n        usageCache[region] = {\n          usage: prior?.usage,\n          atMs: prior?.atMs ?? Date.now(),\n          ...prior?.error === undefined ? {} : { error: prior.error },\n          staleError: prior?.staleError ?? 'credits read returned no data (timeout / transient upstream failure)',\n        }\n        return\n      }\n      usageCache[region] = { usage, atMs: Date.now() }\n    } catch (error: unknown) {\n      // `auth` 必须记为 `credential-rejected`，不能塞一个笼统的 kind 字符串：\n      // 卡片只认这三个字来渲染「凭据被拒」区块（以及切换到可用账号的按钮）。\n      // 过期 PAT 此前既没有积分、也没有任何提示，就是这一步把错误吞成了\n      // 「无数据」。其他 kind 原样保留，卡片按普通错误行显示上游原文。\n      //\n      // 但「凭据被拒」也得有凭据（issue #6）：只是 HTTP 403 兜底猜出来的 auth\n      //（上游把排队/用量限流也装在 403 里）不能这么写 —— 卡片会让用户去换一个\n      // 根本没坏的 PAT。没确认过的降级成 `unavailable`（普通错误行）。\n      const kind = isQoderUpstreamError(error) ? error.kind : undefined\n      const context = isQoderUpstreamError(error)\n        ? { status: error.status, code: error.code }\n        : undefined\n      usageCache[region] = {\n        usage: undefined,\n        atMs: Date.now(),\n        error: kind === 'auth' ? credentialOutcomeOf(context) : (kind ?? 'unknown'),\n      }\n    }\n  }\n\n  /**\n   * The region's catalog projected into the pool target picker's shape.\n   *\n   * 读的是**卡片那一份**目录（`displayModels`，含未勾选的模型），不是运行时目录\n   * （`stacks[region].catalog`，被 `deriveCatalog` 按勾选裁剪过）。这是 issue #33\n   * 的修法：「能不能测某个模型」与「它在不在 DSH 选择器里」是两件事，勾选管的是\n   * 后者。用运行时目录会让「手选了一个没勾的模型」或「自动档唯一的免费模型没被勾」\n   * 直接解不出目标 —— 测试路由回 `rows: []`，卡片却写着「测试用模型 X」。\n   */\n  function poolModelsOf(region: QoderRegion): QoderPoolModel[] {\n    return displayModels(region).map(model => poolModelOf(model))\n  }\n\n  /**\n   * 这个区域**该测哪个模型**（issue #26 的「自动」挑法）。\n   *\n   * 「自动」这一档不再永远钉在最热门的免费模型上：那个模型一旦排队，每一次\n   * 探测都会撞同一个队列（用户实拍：整池躺了半小时）。现在的规则是\n   * 「最近测成功过的优先 → 跳过刚被排过队的 → 上下文最大的」。\n   *\n   * 用户手选的模型**永远优先**（`resolveTargetModel` 里就短路了）—— 绝不因为\n   * 它在排队就偷偷换人测，那会与卡片上写的「测试用模型」对不上。\n   *\n   * 解析规则与目录都走共享的 `resolvePoolTarget`：池视图（卡片）与测试路由、\n   * 请求路径的换号判据必须解出**同一个**目标，否则「卡片写 A、实测 B」这类\n   * 分叉会在别处重新长出来（issue #33）。\n   */\n  function poolTargetOf(region: QoderRegion): QoderPoolTarget {\n    return resolvePoolTarget({\n      catalog: poolModelsOf(region),\n      preferredId: poolPreferencesOf(config, region).targetModelId,\n      probes: stacks[region].poolRuntime,\n      nowMs: Date.now(),\n    })\n  }\n\n  // -------------------------------------------------------------------------\n  // 目录 / 注册同步\n  // -------------------------------------------------------------------------\n\n  /** On-demand model read for discovery + refresh. */\n  async function discoverModels(region: QoderRegion, signal?: AbortSignal): Promise<QoderModelInfo[]> {\n    const serving = await resolveServing(region)\n    if (!serving) return []\n    const upstream = await stacks[region].upstream.fetchModels(serving.pat, signal)\n    const parsed = upstream.map(parseUpstreamModel)\n    return applyContextBudgets(parsed, contextBudgetsOf(config, region))\n  }\n\n  /**\n   * 拉取并安装一个区域的动态目录。返回安装后的目录；拉取失败抛错——\n   * 路由层据此答 500，启动路径自己吞掉落回兜底目录。\n   */\n  async function refreshRegionCatalog(region: QoderRegion, pat: string): Promise<QoderModelInfo[]> {\n    const upstream = await stacks[region].upstream.fetchModels(pat)\n    const parsed = upstream.map(parseUpstreamModel)\n    const withTiers = applyContextBudgets(parsed, contextBudgetsOf(config, region))\n    const stamped = stampRuntimeCatalog(config, region, withTiers)\n    // 运行时目录 = **只含勾选的模型**（workbuddy 同规）。DSH 的选择器通过适配器的\n    // `getModels()` 读它，所以这里过滤才是「选择器只列出我勾的那些」真正生效的地方。\n    // 卡片另走 `displayModels()`（完整目录），否则未勾选的模型会从卡片里消失、\n    // 用户再也勾不上——两个视图分开正是 workbuddy 的做法。\n    const saved = new Set(enabledModelKeysOf(config, region))\n    // 完整目录（含上游声明的思考档位）另存一份给卡片；运行时目录只留勾选的。\n    // 两者必须分开：卡片要看到未勾选的模型才勾得上，而档位信息只有实时目录里\n    // 才有（保存的 lastCatalog 可能是旧快照，甚至被旧 schema 剥掉档位字段）。\n    fullCatalog[region] = stamped\n    // 卡片在「实时目录还没到手」时的兜底也是完整目录（issue #33）：退回运行时\n    // 目录会让未勾选的模型在冷启动窗口里从卡片与目标解析里一起消失。\n    cardCatalog[region] = stamped\n    stacks[region].catalog.set(deriveCatalog(stamped, saved))\n    invalidateCatalog()\n    return stamped\n  }\n\n  /**\n   * 路由层（卡片「从 Qoder 刷新」按钮）用的完整刷新：装目录 + 刷积分。\n   * 此前的路由只调只读的 discoverModels——返回了新模型给卡片，却从不写入\n   * 运行时目录，卡片随后重取 usage 文档看到的仍是旧目录，刷了个寂寞。\n   */\n  async function refreshRegionForRoute(region: QoderRegion): Promise<QoderModelInfo[]> {\n    const serving = await resolveServing(region)\n    if (!serving) throw new Error(`no PAT configured for ${region}`)\n    const models = await refreshRegionCatalog(region, serving.pat)\n    void refreshUsageCoalesced(region)\n    return models\n  }\n\n  const refreshModels = (region: QoderRegion): Promise<void> => {\n    return (async () => {\n      const serving = await resolveServing(region)\n      if (!serving) {\n        log(`models refresh skipped for ${region}: no PAT configured`)\n        return\n      }\n      try {\n        await refreshRegionCatalog(region, serving.pat)\n      } catch (error: unknown) {\n        log(`dynamic ${region} model catalog unavailable; serving the static fallback list: ${String((error as Error)?.message ?? error)}`)\n      }\n      // 积分与目录独立成败：目录拉取失败绝不能拖死积分——此前 refreshUsage\n      // 链在目录成功的分支里，目录一挂积分永远不来，卡片上「看不到积分」。\n      void refreshUsageCoalesced(region)\n    })()\n  }\n\n  const syncRegionRegistration = (value: Config): void => {\n    for (const region of QODER_REGIONS) {\n      const enabled = regionEnabled(value, region)\n      const handle = registration[region].adapter\n      if (handle === undefined) continue\n      try {\n        handle.replace(enabled ? [QODER_PROVIDERS[region]] : [])\n      } catch (error: unknown) {\n        log(`region ${region} adapter sync failed: ${String((error as Error)?.message ?? error)}`)\n      }\n    }\n    const dirHandle = registration.cn.directory\n    if (dirHandle === undefined) return\n    try {\n      dirHandle.replace(QODER_REGIONS\n        .filter(region => regionEnabled(value, region))\n        .map(region => ({\n          provider: QODER_PROVIDERS[region],\n          displayName: QODER_PROVIDER_DISPLAY_NAMES[region],\n          settingsNs,\n          settingsPath: [],\n          declared: false,\n        })))\n    } catch (error: unknown) {\n      log(`provider directory sync failed: ${String((error as Error)?.message ?? error)}`)\n    }\n  }\n\n  const applySelection = (value: Config): void => {\n    for (const region of QODER_REGIONS) {\n      const full = configuredModels(value, region, stacks[region].catalog.current())\n      const withTiers = applyContextBudgets(full, contextBudgetsOf(value, region))\n      const stamped = stampRuntimeCatalog(value, region, withTiers)\n      // **必须在这里也过滤**：`applySelection` 在每次配置写入时跑，它若把完整\n      // 目录重新装回运行时目录，就会覆盖 refreshRegionCatalog 的过滤结果——\n      // 这正是「保存了模型，选择器里还是一整份」的原因（用户实拍两次）。\n      // 运行时目录只含勾选的；完整目录由 displayModels() 供卡片。\n      const saved = new Set(enabledModelKeysOf(value, region))\n      cardCatalog[region] = stamped\n      stacks[region].catalog.set(deriveCatalog(stamped, saved))\n    }\n    invalidateCatalog()\n    syncRegionRegistration(value)\n    for (const region of QODER_REGIONS) void refreshUsageCoalesced(region)\n  }\n\n  applySelection(config)\n\n  // -------------------------------------------------------------------------\n  // web-status deps\n  // -------------------------------------------------------------------------\n\n  const accountDeps = (region: QoderRegion): QoderAccountDeps => {\n    const store = stacks[region].store\n    return {\n      accounts: sources => store.accounts(sources ?? sourcesOf(region)),\n      credentialFor: (accountId, sources) => store.credentialFor(accountId, sources ?? sourcesOf(region)),\n      resolve: (sources, selectedId) => store.resolve(sources ?? sourcesOf(region), selectedId ?? selectedAccountId(config, region)),\n      add: (pat, name) => store.add(pat, name),\n      vaultAccounts: () => store.vaultAccounts(),\n      remove: accountId => store.remove(accountId),\n      rename: (accountId, name) => store.rename(accountId, name),\n    }\n  }\n\n  const accountValidationDeps: QoderAccountValidationDeps = {\n    validateForRegion: async (region, pat) => {\n      const job = await stacks[region].upstream.exchangeJobToken(pat)\n      return { name: job.name || '' }\n    },\n  }\n\n  /** Region-dispatch table for the single pool deps the route gets. */\n  function poolFor(region: QoderRegion): QoderPoolDeps {\n    const store = stacks[region].store\n    return {\n      preferences: reg => poolPreferencesOf(config, reg),\n      poolProbes: reg => stacks[reg].poolRuntime,\n      credentialFor: (reg, accountId) => store.credentialFor(accountId, sourcesOf(reg)),\n      probeOne: (reg, credit, modelId) => probeThrough(reg, credit, modelId),\n      // 两个区域**都有**每日签到（sash 的 campaigns 活动，已实测）。\n      // 差别只在认证细节：国际版额外需要设备风控头（本机 UMID 组件的三件套），\n      // 由 upstream 按 region 条件附加（见 QoderRegionConfig.requiresDeviceRisk）。\n      // 本机没有 Qoder 客户端（取不到组件）时，签到会在读取那一步如实报错，\n      // 而不是把「取不到设备身份」伪装成「今天没有活动」。\n      checkinSupported: () => true,\n      checkin: async reg => runCheckinBatch(reg),\n      // `onlyAccountId` 是卡片**行级**「测试」按钮的路径：那一行只碰那一行。\n      // 不给就还是整批（工具栏「测试全部」按钮、以及旧客户端的调用）。\n      test: async (reg, onlyAccountId) => {\n        const prefs = poolPreferencesOf(config, reg)\n        const target = poolTargetOf(reg)\n        if (target.modelId === undefined) return []\n        const deps: QoderPoolRunnerDeps = {\n          credentialFor: accountId => store.credentialFor(accountId, sourcesOf(reg)),\n          probe: (credit, modelId) => probeThrough(reg, credit, modelId),\n        }\n        const targets: Array<{ accountId: string, accountName: string }> = []\n        // 行级：只处理点名的那一个。**刻意不要求它是成员**——用户可能正在\n        // 犹豫要不要把一个号加进池，先测一下才决定。整批路径才按成员遍历。\n        const scope = onlyAccountId === undefined ? prefs.memberAccountIds : [onlyAccountId]\n        for (const accountId of scope) {\n          // 只测**真的还有凭据**的成员。用户的 PAT 被删除后 memberAccountIds\n          // 里会留下幽灵 id（配置里的名单不会随 vault 自动收缩），它们既测不出\n          // 结果、又会往池里写一条假的「凭据被拒」——用户看到的就是「有 2 个\n          // 已保存的账号当前没有可用的 PAT」这种本该自动消失的提示。\n          const credit = await store.credentialFor(accountId, sourcesOf(reg))\n          if (credit === undefined) continue\n          targets.push({ accountId, accountName: credit.accountName })\n        }\n        const modelIdOfTarget = target.modelId\n        // 单账号走 `testOne`（不 sleep：没有「下一行」要等），整批走批量 runner。\n        //\n        // 整批把每一行的测量在**它测完的那一刻**写进快照：批量是串行的真实探针，\n        // 一池六个号就是几分钟，界面据此逐行翻新状态（卡片在飞期间会重读快照）。\n        // 等整批结束才一次性写，用户在那几分钟里看到的就是一张不动的表 ——\n        // 那种「没有进度」和「卡死」在界面上分不出来，用户把它当成卡住过。\n        const rows = await (async (): Promise<QoderWebPoolTestRow[]> => {\n          const batch = onlyAccountId === undefined\n          if (batch) beginPoolBatch(reg, 'test')\n          try {\n            return batch\n              ? await testAllAccounts(targets, modelIdOfTarget, deps, row => {\n                  // 先记进度，再落探针：进度槽位装的是「这一行的结论已出」，即使\n                  // 这条结果解析不出探针（`poolProbeFromResult` 返回 undefined），\n                  // 活动日志也该照实写一行——否则用户点完什么都没看到。\n                  recordPoolBatchRow(reg, row)\n                  const probe = poolProbeFromResult(row.result)\n                  if (probe === undefined) return\n                  stacks[reg].poolRuntime = { ...stacks[reg].poolRuntime, [row.accountId]: probe }\n                  void writePoolProbes(reg, { [row.accountId]: probe })\n                })\n              : await Promise.all(targets.map(target => testOne(target, modelIdOfTarget, deps)))\n          } finally {\n            endPoolBatch(reg)\n          }\n        })()\n        const probes: Record<string, QoderPoolProbe> = {}\n        for (const row of rows) {\n          const p = poolProbeFromResult(row.result)\n          if (p) probes[row.accountId] = p\n        }\n        stacks[reg].poolRuntime = { ...stacks[reg].poolRuntime, ...probes }\n        void writePoolProbes(reg, probes)\n        return rows\n      },\n      applyProbes: async (reg, probes) => {\n        stacks[reg].poolRuntime = { ...stacks[reg].poolRuntime, ...probes }\n        void writePoolProbes(reg, probes)\n      },\n      updateMembership: (reg, memberAccountIds, enabled) => {\n        const next = { ...poolPreferencesOf(config, reg), memberAccountIds, ...(enabled === undefined ? {} : { enabled }) }\n        submitRegionSettings(reg, { pool: next })\n      },\n    }\n  }\n\n  function buildPoolDeps(): QoderPoolDeps {\n    return {\n      preferences: region => poolPreferencesOf(config, region),\n      // 注意这里**没有** `catalog`：池的模型目录只有一份，就是交给卡片的\n      // `deps.catalogs`（`displayModels`，完整目录）。issue #33 的教训见\n      // `QoderPoolDeps` 里那段注释 —— 有第二份就一定会分叉。\n      poolProbes: region => stacks[region].poolRuntime,\n      batchProgress: region => poolBatches[region],\n      memberCredits: (region, accountIds) => poolMemberCredits(region, accountIds),\n      cachedMemberCredits: (region, accountIds) => cachedMemberCredits(region, accountIds),\n      credentialFor: (region, accountId) => stacks[region].store.credentialFor(accountId, sourcesOf(region)),\n      probeOne: (region, credit, modelId) => probeThrough(region, credit, modelId),\n      test: (region, modelId) => poolFor(region).test(region, modelId),\n      checkinSupported: region => poolFor(region).checkinSupported(region),\n      checkin: region => poolFor(region).checkin!(region),\n      checkinState: region => checkinState[region],\n      checkinSnapshot: region => checkinSnapshots[region],\n      applyProbes: async (region, probes) => poolFor(region).applyProbes(region, probes),\n      updateMembership: (region, memberAccountIds, enabled) => poolFor(region).updateMembership(region, memberAccountIds, enabled),\n    }\n  }\n\n  /** Build the transfer deps once (region-dispatched). */\n  const transferDeps: QoderTransferDeps = {\n    exportAccounts: async region => {\n      // 必须经 transferRecordsFor 投影成 transfer 文件形状（`access_token` /\n      // `uid` / `nickname` / `domain`）。此前这里直接吐 vault 原始字段\n      // （`pat` / `accountName` / `id`）——**既没有 domain，字段名也不是\n      // snake_case**，于是导出物再导入时被区域门整批判 skipped\n      // （导出即导入 = 0 条成功）。投影留在 transfer.ts（而非内联在此），\n      // 是为了往返回归测试能直接走同一条代码路径。\n      const { transferRecordsFor } = await import('./transfer.ts')\n      const vault = await stacks[region].store.vaultAccounts()\n      return { accounts: transferRecordsFor(region, vault) }\n    },\n    previewImport: async (_region, text) => {\n      const { previewTransferFile } = await import('./transfer.ts')\n      return previewTransferFile(text)\n    },\n    importAccounts: async (region, text, indexes) => {\n      const { mergeTransferRecords } = await import('./transfer.ts')\n      const { changes, imported, skipped } = mergeTransferRecords(region, text, indexes)\n      for (const entry of changes.values()) await stacks[region].store.add(entry.pat, entry.accountName)\n      return { imported, skipped }\n    },\n  }\n\n  // Settings service (0.1.7+ `configure`/`mutate` surface; captured once the\n  // optional `settings` service is actually present).\n  interface SettingsRow { ns: string, value: Record<string, unknown> }\n  interface SettingsShapes {\n    describe(): SettingsRow[]\n    mutate(ns: string, ops: Array<{ op: 'set', path: string[], value: unknown }>, options?: unknown): Promise<void>\n  }\n  let settingsService: SettingsShapes | undefined\n  const settingsNsOf = settingsNs\n  ctx.inject(['settings'], (sctx) => {\n    settingsService = (sctx as unknown as { settings?: SettingsShapes }).settings\n  })\n\n  const pluginRow = (): SettingsRow | undefined => {\n    if (settingsService === undefined) return undefined\n    return settingsService.describe().find(row => String(row.ns).includes('dsh-connect-qoder'))\n  }\n\n  /**\n   * Two-level merge a settings field write, then `mutate` it (workbuddy's\n   * `__save` contract, so a partial payload never deletes sibling regions).\n   */\n  async function mutateField(field: string, incoming: unknown): Promise<void> {\n    const row = pluginRow()\n    if (row === undefined) throw new Error('settings namespace not yet available')\n    const current = unwrapVolatileDeep((row.value?.[field] ?? {}) as unknown) as Record<string, unknown>\n    const patch = (incoming ?? {}) as Record<string, unknown>\n    const merged: Record<string, unknown> = { ...current }\n    for (const [key, slot] of Object.entries(patch)) {\n      const prior = current[key]\n      const isPlain = (v: unknown): v is Record<string, unknown> => v !== null && typeof v === 'object' && !Array.isArray(v)\n      merged[key] = isPlain(prior) && isPlain(slot) ? { ...prior, ...slot } : slot\n    }\n    await settingsService!.mutate(row.ns, [{ op: 'set', path: [field], value: merged }], undefined)\n  }\n\n  const settingsDeps: QoderSettingsDeps = {\n    describe: () => (settingsService === undefined ? [] : settingsService.describe()),\n    set: async (field, value) => {\n      // `regions` 走两级合并（兄弟区域不能被吃掉）；`sidebarPanel` 是顶层标量，\n      // 没有兄弟槽，所以直接 set 到它自己那条路径上 —— 这正是 workbuddy\n      // `__save` 对 `UPSTREAM_SWITCH_FIELDS` 的处理（每个都是完整独立的值，\n      // `set` 在它自己的 path 上不可能覆盖旁边任何东西）。\n      if (field === QODER_SIDEBAR_PANEL_FIELD || field === QODER_POLL_MINUTES_FIELD) {\n        // 顶层标量：没有兄弟槽，直接 set 到它自己那条路径上 —— 这正是 workbuddy\n        // `__save` 对 `UPSTREAM_SWITCH_FIELDS` 的处理（每个都是完整独立的值，\n        // `set` 在它自己的 path 上不可能覆盖旁边任何东西）。\n        const row = pluginRow()\n        if (row === undefined) throw new Error('settings namespace not yet available')\n        await settingsService!.mutate(row.ns, [{ op: 'set', path: [field], value }], undefined)\n        return\n      }\n      if (field !== 'regions') throw new Error(`unsupported settings field: ${String(field)}`)\n      await mutateField(field, value)\n    },\n  }\n\n  /** Write one region's settings patch (whole `regions` dict replace). */\n  function submitRegionSettings(region: QoderRegion, patch: Record<string, unknown>): void {\n    const regions = (unwrapVolatile(config.regions) ?? {}) as Record<string, unknown>\n    const next = { ...regions, [region]: { ...((regions[region] as Record<string, unknown>) ?? {}), ...patch } }\n    void mutateField('regions', next)\n  }\n\n  /** Fresh per-account credit balances for the composer panel. */\n  async function accountCreditsOf(region: QoderRegion, signal?: AbortSignal): Promise<QoderWebAccountCredit[]> {\n    const store = stacks[region].store\n    const accounts = await store.accounts(sourcesOf(region))\n    const prefs = poolPreferencesOf(config, region)\n    const probes = stacks[region].poolRuntime\n    const now = Date.now()\n    const targetModelId = poolTargetOf(region).modelId\n    const selectedId = selectedAccountId(config, region)\n    /**\n     * 池开启时的**接管候选**（`rankPool` 第一个可用的成员）。\n     *\n     * 与 `nextFailoverCredential` 同一条判据（同一个 `rankPool`、同一个\n     * `orderAccountIds`、同一个目标模型作用域）——但它只在第一发被硬拒时\n     * 才真正接管线；第一发本来就是选中号。池关闭时缺席——没有换号机制。\n     */\n    let priorityId: string | undefined\n    if (poolAllowsFailover(prefs)) {\n      const candidates: QoderPoolMember[] = []\n      for (const accountId of prefs.memberAccountIds) {\n        const probe = probes[accountId]\n        candidates.push({\n          account: { id: accountId, accountName: accountId },\n          ...probe === undefined ? {} : { probe },\n        })\n      }\n      priorityId = rankPool(candidates, now, targetModelId, prefs.orderAccountIds)\n        .find(row => row.excludedBy === undefined)?.account.id\n    }\n    /**\n     * 每一发的第一击打给谁 —— 直接调 `resolveServing`，与 `src/shim.ts` 的\n     * 请求路径逐字同判（同一个 `store.resolve`）。「在用」跟着第一击走，\n     * 而不是跟着 rankPool 名次；只有第一击被排除**且池开着**时，实际买单的\n     * 才是接管者 `priorityId`（全灭时无人 current）。\n     */\n    const firstShotId = (await resolveServing(region))?.id\n    const firstShotExcluded = firstShotId !== undefined\n      && exclusionOf(probes[firstShotId], now, targetModelId) !== undefined\n    const out: QoderWebAccountCredit[] = []\n    for (const account of accounts) {\n      const credit = await store.credentialFor(account.id, sourcesOf(region))\n      const pat = credit?.pat\n      if (!pat) continue\n      let usage: QoderUsage | undefined\n      try {\n        usage = await stacks[region].upstream.fetchUsage(pat, signal)\n      } catch {\n        usage = undefined\n      }\n      const probe = probes[account.id]\n      const excludedBy = exclusionOf(probe, now, targetModelId)\n      const selected = account.id === selectedId || (account.source !== 'vault' && selectedId === undefined)\n      out.push({\n        id: account.id,\n        accountName: account.accountName || account.source,\n        selected,\n        // 与 `web-status.ts` 行循环的 `isCurrent` 逐字同判（src/shim.ts 的\n        // 请求路径就是这条）：池开且第一发被排除 → 接管者；其余 → 第一发\n        // 本人（池关时即使被排除也是他——没有第二个人）。\n        current: poolAllowsFailover(prefs) && firstShotExcluded\n          ? priorityId === account.id\n          : firstShotId === account.id,\n        ...excludedBy === undefined ? {} : { excludedBy },\n        // 原始探针结论（不做目标模型过滤，与 AccountPool.tsx 的 stateColor\n        // 吃到同一事实）——面板把「能不能用」折算成绿/红两种颜色。\n        ...probe === undefined ? {} : { probeOutcome: probe.outcome },\n        // 解禁时刻：原因里写「约 N 分钟后解禁」要的就是它。只有上游明确给过\n        // retryAtMs 的探针才有；缺席时面板只显示原因，不编倒计时。\n        ...probe?.retryAtMs === undefined ? {} : { retryAtMs: probe.retryAtMs },\n        // 这个时刻是谁给的（issue #32）：上游申报 vs 签到快照推的，卡片要分开说。\n        ...probe?.retrySource === undefined ? {} : { retrySource: probe.retrySource },\n        ...usage === undefined ? {} : { credits: creditsOf(usage).total },\n      })\n    }\n    return out\n  }\n\n  /**\n   * 一个区域的活动面：签到 + `VIEW_DETAILS` banner，供卡片「活动」区读。\n   *\n   * 复用 `resolveServing` 的同一份判定（settings → env → vault / 选中号），所以\n   * 卡片上看到的「这一区有哪些活动」和用量面板读到的是同一个账号的活动。\n   */\n  async function campaignsOf(region: QoderRegion, signal?: AbortSignal): Promise<QoderCampaignFeed> {\n    const serving = await resolveServing(region)\n    if (!serving) throw new Error('未配置凭据')\n    return stacks[region].upstream.fetchCampaignFeed(serving.pat, signal)\n  }\n\n  /**\n   * 凭据被拒后的恢复建议：逐个探测本区域其余账号，只把**真正答过话**的那个\n   * 承诺给用户（`credential-recovery.ts` 的实现早就写好了，此前从未接线——\n   * 卡片一直用「账号数 ≤ 1」猜，于是对着一条同样过期的记录说「可以切换试试」）。\n   */\n  async function credentialRecoveryOf(region: QoderRegion, rejectedAccountId: string): Promise<QoderWebRecovery> {\n    // 两个组件都要「按区域取到账号与凭据」，共用一份适配器。\n    const probeStore = (reg: QoderRegion): QoderProbeStore => ({\n      accounts: () => stacks[reg].store.accounts(sourcesOf(reg)).then(list => list.map(a => ({ id: a.id, accountName: a.accountName }))),\n      credentialFor: (accountId: string) => stacks[reg].store.credentialFor(accountId, sourcesOf(reg)),\n    })\n    const probe = createAccountUsabilityProbe({ store: probeStore, client: stacks[region].upstream })\n    return resolveCredentialRecovery({ region, store: probeStore(region), rejectedAccountId, probe })\n  }\n\n  /** The serving credential for a probe route (region's selection). */\n  async function probeModelOf(region: QoderRegion, modelId: string, signal?: AbortSignal): Promise<QoderWebProbeResult> {\n    const serving = await resolveServing(region)\n    if (!serving) return { modelId, outcome: 'credential-rejected', message: '未配置凭据' }\n    return probeThrough(region, { pat: serving.pat, accountName: serving.accountName }, modelId, signal)\n  }\n\n  // 宿主存活心跳：卡片用于「存活判定 / 一键不再显示」。\n  void writeHostHeartbeat()\n\n  // 浏览器路由（webServer 可选注入；缺失时卡片读镜像即可）。\n  ctx.inject(['webServer'], (ctxWithWeb) => {\n    registerQoderWebRoutes(ctxWithWeb, {\n      regionEnabled: region => regionEnabled(config, region),\n      regionCreditsShown: region => regionCreditsShown(config, region),\n      regionCampaignsShown: region => regionCampaignsShown(config, region),\n      creditPosition: region => creditPosition(config, region),\n      // GLOBAL，所以不带区域参数。`=== true`（见 `sidebarPanelEnabledOf`），\n      // 不是 `!== false`：这一行占的是所有 bundle 共用的侧边栏座位，缺席必须\n      // 读成「没要」。字段是 volatile，所以读取时先解包。\n      sidebarPanelEnabled: () => sidebarPanelEnabledOf(config),\n      // GLOBAL：与 sidebarPanel 同层，两个区域共用一条节奏（见 schema 注释）。\n      pollMinutes: () => pollMinutesOf(config),\n      lastQuotaExhaustion: region => quotaExhaustionByRegion[region],\n      regionUsable: (region, usable) => {\n        if (!usable) log(`region ${region} is signed out`)\n      },\n      store: accountDeps,\n      credentialSources: sourcesOf,\n      selectedAccountId: region => selectedAccountId(config, region),\n      // 删除账号后清掉指向它的区域选择：凭据没了，这个选择也没意义了。写 `''`\n      // 而不是删键——`''` 就是「自动」，正是 `writeAccountSlot` 在用户选「自动」\n      // 时写的那个值，两条路径落到同一状态。\n      clearSelection: region => { submitRegionSettings(region, { accountId: '' }) },\n      // 卡片读的是**完整目录**（displayModels），不是过滤后的运行时目录。\n      catalogs: {\n        cn: { current: () => [...displayModels('cn')] },\n        global: { current: () => [...displayModels('global')] },\n      },\n      contextBudgets: region => contextBudgetsOf(config, region),\n      thinkingEfforts: region => thinkingEffortsOf(config, region),\n      offModelKeys: region => offModelKeysOf(config, region),\n      imageModelKeys: region => imageModelKeysOf(config, region),\n      imageSelectionSaved: region => imageSelectionSavedOf(config, region),\n      enabledModelKeys: region => enabledModelKeysOf(config, region),\n      discoverModels,\n      refreshModels: refreshRegionForRoute,\n      usage: usageEntryOf,\n      // /usage 路由每次请求先现场刷一次积分再读缓存（对齐 workbuddy）。此前\n      // 缓存只在四个时机被写，聊天扣费后触发器数字永远不变，而面板表格（每\n      // 账号现场读）会变 —— 同一个账号两个数（用户实拍 800 vs 738）。\n      // 走合流版：卡片/composer/面板会几乎同时打到同一区域。\n      refreshUsage: refreshUsageCoalesced,\n      probeModel: probeModelOf,\n      accountCredits: accountCreditsOf,\n      campaigns: campaignsOf,\n      pool: buildPoolDeps(),\n      transfer: transferDeps,\n      accountValidation: accountValidationDeps,\n      settings: settingsDeps,\n      logger: log,\n    })\n  })\n\n  // 0.1.7 在每次设置写入后发 `loader/volatile-update`；借此收敛目录/注册/用量。\n  ;(ctx as unknown as { on(name: string, listener: () => void): unknown })\n    .on('loader/volatile-update', () => applySelection(config))\n\n  // 析构：关闭 shims + 清心跳（副作用一次执行）。\n  let disposed = false\n  ctx.effect(() => () => {\n    if (disposed) return\n    disposed = true\n    stopped = true\n    for (const region of QODER_REGIONS) void stacks[region].shim.close()\n    void clearHostHeartbeat()\n  })\n\n  // -------------------------------------------------------------------------\n  // 每区域 shim 就绪后注册 provider\n  // -------------------------------------------------------------------------\n\n  void Promise.all(QODER_REGIONS.map(region => stacks[region].shim.ready))\n    .then(async () => {\n      if (stopped) return\n\n      try {\n        const adapters = {} as Record<QoderRegion, QoderAdapter>\n        for (const region of QODER_REGIONS) {\n          adapters[region] = createQoderAdapter({\n            shim: stacks[region].shim,\n            catalog: stacks[region].catalog,\n            provider: QODER_PROVIDERS[region],\n            displayName: QODER_PROVIDER_DISPLAY_NAMES[region],\n            resolveAttachments: () => ctx.get('attachments'),\n            // issue #24：重试预算可配（缺省 = 宿主默认，与升级前一致）。\n            retryPolicy: retryPolicyOf(config, region),\n            retryPolicyPath: `dsh-connect-qoder regions.${region}.retry`,\n            // 逐模型的默认思考档位：用户在卡片里为某个模型选过档位时，那一次选择\n            // 就是这个模型的默认值；没选过的模型跟随上游自己声明的默认档\n            // （`src/default-effort.ts`）。适配器把它报给宿主，宿主的模型选择器\n            // 于是显示那一档而不是「Default」，请求里也会带上它。\n            defaultThinkingEfforts: () => thinkingEffortsOf(config, region),\n          })\n          stacks[region].adapter = adapters[region]\n        }\n        invalidateCatalog = () => {\n          for (const region of QODER_REGIONS) adapters[region].invalidate()\n        }\n\n        const releaseAdapter = {} as Record<QoderRegion, (() => void) | undefined>\n        let releaseDirectory: (() => void) | undefined\n        try {\n          for (const region of QODER_REGIONS) {\n            releaseAdapter[region] = registration[region].adapter = ctx.llm.registerAdapter([QODER_PROVIDERS[region]], adapters[region].adapter)\n          }\n          // registerConfigurableProviders 一次登记**两个区域**的 provider 条目\n          // （map 遍历 QODER_REGIONS），所以这里只有**一个**句柄。它沿用\n          // `registration.cn.directory` 这个槽位只是为了不新增字段：整个目录\n          // 条目集由这一个句柄持有，并按区域整体 replace（见 syncRegionRegistration）。\n          // 不要读成「global 漏了 directory 句柄」。\n          releaseDirectory = registration.cn.directory = ctx.llm.registerConfigurableProviders(\n            QODER_REGIONS.map(region => ({\n              provider: QODER_PROVIDERS[region],\n              displayName: QODER_PROVIDER_DISPLAY_NAMES[region],\n              settingsNs,\n              settingsPath: [],\n              declared: false,\n            })),\n          )\n        } finally {\n          const missing = QODER_REGIONS.some(region => releaseAdapter[region] === undefined) || releaseDirectory === undefined\n          if (missing) {\n            for (const region of QODER_REGIONS) releaseAdapter[region]?.()\n            releaseDirectory?.()\n          }\n        }\n\n        ctx.effect(() => () => {\n          for (const region of QODER_REGIONS) releaseAdapter[region]?.()\n          releaseDirectory?.()\n        })\n\n        syncRegionRegistration(config)\n\n        ctx.llm.registerModelDiscovery(settingsNs, async (request, signal) => {\n          const region = regionOfProvider(request.provider ?? '')\n          if (region === undefined) return []\n          if (!regionEnabled(config, region)) return []\n          try {\n            const models = await discoverModels(region, signal)\n            const saved = new Set(enabledModelKeysOf(config, region))\n            return deriveCatalog(models, saved.size > 0 ? saved : initialEnabledKeys(models)).map(model => ({\n              id: model.key,\n              name: modelDisplayName(model),\n              contextWindow: model.contextWindow,\n              maxTokens: model.maxOutputTokens,\n              inputModalities: model.supportsImages ? ['text', 'image'] : ['text'],\n            }))\n          } catch {\n            return []\n          }\n        })\n      } catch (error: unknown) {\n        ctx.logger.error('dsh-connect-qoder: provider registration failed', error)\n        return\n      }\n\n      // 每区域异步刷新目录（失败静默，fallback 目录继续服务）。\n      for (const region of QODER_REGIONS) refreshModels(region)\n    })\n    .catch((error: unknown) => {\n      ctx.logger.error('dsh-connect-qoder: loopback endpoint failed to start; providers not registered', error)\n    })\n\n  /** One batch result → a persisted pool probe. */\n  function poolProbeFromResult(result: QoderWebProbeResult): QoderPoolProbe | undefined {\n    return {\n      outcome: result.outcome,\n      atMs: Date.now(),\n      source: 'test-batch',\n      // 探针结果本来就带 modelId（测的就是某个模型），此前在这里被丢掉，\n      // 于是落盘成一条**无作用域**的结论：模型 A 可用、模型 B 429，表格\n      // 在两行都写「可用」。写进来是作用域的一半，另一半在读侧\n      // （exclusionOf 的 modelId 参数）—— 只改一侧等于没改。\n      ...(result.modelId === '' ? {} : { modelId: result.modelId }),\n      ...(result.retryAtMs === undefined ? {} : { retryAtMs: result.retryAtMs }),\n      // 解禁时刻的来源也要落盘（issue #32）：`retry-after` / `upstream-message`\n      // 是上游给的，`quota-refresh` 是快照推的 —— 卡片要分开说，不能混成一句。\n      ...(result.retrySource === undefined ? {} : { retrySource: result.retrySource }),\n      // issue #32 第一条建议：探针这条路上同样会有「上游没说、快照也没有」的\n      // 兜底冷却。与真实请求路径共用同一个判据函数，两条路才不会对同一件事\n      // 给出两种说法。\n      ...fallbackCooldownOf(result.outcome, result.retryAtMs, result.retrySource),\n      // 排队信息（issue #26）：上游说「排在第 1027 位」是要显示给人看的。\n      ...(result.queue === undefined ? {} : { queue: result.queue }),\n      ...(result.message === undefined ? {} : { message: result.message }),\n    }\n  }\n}\n\nconst FAIL_OVER_OUTCOME: Record<string, QoderWebProbeOutcome> = {\n  // `auth` 不在这张表里：它要分「确认过」与「只是状态兜底猜的」两种处置，\n  // 由 credentialOutcomeOf 按上游状态/业务码判定（issue #6）。放进表里就会\n  // 又变成一张「一律永久排除」的表。\n  'rate-limited': 'rate-limited',\n  'quota-exhausted': 'out-of-credit',\n  network: 'unavailable',\n  transient: 'unavailable',\n}\n\n/**\n * 「凭据被拒」这条结论**有没有凭据**。\n *\n * `auth` 这个 kind 只说「像凭据问题」，不说「凭什么」。两种来源的处置必须不同\n * （issue #6）：\n *\n * - **业务码 `105` 确认**（官方码表：登录态或 Access Token 已过期）—— 令牌真的\n *   被拒了，等也没用，永久剔除是对的。\n * - **HTTP 401** —— 401 在这套上游语义里就是凭据被拒，同样永久剔除。\n * - **只是 HTTP 403 兜底猜的**（`classifyHttpStatus` 的 `401/403 → auth`）——\n *   上游把「当日用量用尽」「排队中」「限流」也装在 403 里（实测 403 + 码 110 /\n *   10605）。此时永久剔除会把一个几分钟到几小时就自愈的账号踢出池，而且\n *   **不自愈**：用户被要求换 PAT，换了也没用（问题从来不在凭据）。\n *\n * 所以这里只把**确认过**的拒绝记成永久排除，没确认的降级为冷却（`unavailable`\n * ⇒ `exclusionOf` 走冷却期，到期自动回池）。\n *\n * `context` 缺席（旧调用方 / 不知道来源）时保持原语义：永久排除 —— 宁可多剔除，\n * 也不让一个坏账号一直留在池里被反复选中。\n */\nexport function credentialOutcomeOf(\n  context?: { status?: number | undefined, code?: string | undefined },\n): QoderWebProbeOutcome {\n  if (context === undefined) return 'credential-rejected'\n  if (context.code === '105') return 'credential-rejected'\n  if (context.status === 401) return 'credential-rejected'\n  return 'unavailable'\n}\n\n/**\n * 一次**真实请求**失败要写进账号池的那条测量；kind 不可映射时返回 undefined\n * （不写：内容策略拒绝是「这一次输入」的事实，不是账号的事实，见\n * `exclusionOf` 的 policy-rejected 分支）。\n *\n * 抽成模块级纯函数并导出，是因为它此前是 `onServingFailure` 里的一段内联字面量，\n * 而那段代码有一个**已经发生过的**缺陷：上游原文被丢掉（参数写成 `_message`），\n * 于是池里只有一句结论、没有依据 —— 用户实拍那条 `credential-rejected` 记录连\n * `message` 都没有，卡片只能空口指控「PAT 被拒」，而真相（`code 110` 当日用量\n * 用尽）就在被丢掉的那串字符里。探针路径早就带原文（`redactUpstreamText`），\n * 两条路径写同一个文件却只有一个带。\n *\n * 按本项目的既有教训（「判据与动作打包，于是动作有没有真的发生也能被断言」），\n * 把它做成可测函数而不是留在接线里：接线变异掉，测试照样全绿过一次了。\n *\n * `context`（上游状态 + 业务码）决定「凭据被拒」是永久排除还是冷却，见\n * {@link credentialOutcomeOf}。\n */\nexport function liveRequestProbe(\n  kind: UpstreamErrorKind,\n  message: string,\n  modelId?: string,\n  context?: {\n    status?: number | undefined\n    code?: string | undefined\n    /** 上游申报的等待时长（毫秒），issue #26。 */\n    retryAfterMs?: number | undefined\n    /** 上游说「我在排队」的证据，issue #26。 */\n    queue?: { isQueued: boolean, queueCount?: number, queueType?: string, retryAfterSeconds?: number, serviceAvailable?: boolean } | undefined\n    /**\n     * 「当日用量用尽」的恢复时刻（签到快照里的 `refreshAtMs`），issue #32。\n     *\n     * 真实请求撞 `110` 时，上游报文里**没有**等待时长（那是 `10605` 排队信封\n     * 才有的字段），于是这条路径此前只能落一条没有 `retryAtMs` 的记录，池子\n     * 按 30 分钟兜底 —— 一个要等到次日窗口才恢复的号，每 30 分钟被真实请求\n     * 撞一次。探测路径（`probeThrough`）早就接上了这个值，真实路径没有。\n     *\n     * 只在 `out-of-credit` 时采用，与 {@link cooldownOf} 同一顺序：上游申报的\n     * 时长优先，其次才是快照推出来的窗口时刻。\n     */\n    quotaRefreshAtMs?: number | undefined\n  },\n): QoderPoolProbe | undefined {\n  // 排队优先（issue #26）：上游明说「在排队、服务是好的、30 秒后再来」，\n  // 那就不该被记成「连不上上游」（`unavailable`）。上游自己的话比 kind 更具体。\n  //\n  // 但「排队」有两个形态，必须分开（issue #29）：\n  // - `serviceAvailable: true` → `queued`：等一等就好，换号也有意义；\n  // - `serviceAvailable: false` → `unavailable`：上游整体在拒服务\n  //   （现场 `queueCount: 0`），换号、换 PAT 都无效。记成账号级 `queued`\n  //   会让用户以为自己的凭据坏了。\n  const queued = context?.queue?.isQueued === true\n  const upstreamDown = queued && context?.queue?.serviceAvailable === false\n  const outcome = queued\n    ? upstreamDown ? 'unavailable' : 'queued'\n    : kind === 'auth' ? credentialOutcomeOf(context) : FAIL_OVER_OUTCOME[kind]\n  if (outcome === undefined) return undefined\n  const now = Date.now()\n  const retryAfterMs = context?.retryAfterMs\n  // 「什么时候能再用」有两个来源，必须分清（issue #32）：\n  // - 上游申报的等待时长（排队信封）—— 上游明说的时间；\n  // - 签到快照里的当日窗口结束时刻 —— **本地推算**的时间（上游只在活动页\n  //   给过「次日 10:00」这种口径，`110` 报文本身不带时刻）。\n  // 顺序与 `cooldownOf` 一致：申报值优先。`retrySource` 一路带到卡片，否则\n  // 用户会把「快照推的」读成「上游说的」。\n  const quotaRefreshAtMs = context?.quotaRefreshAtMs\n  const retry = retryAfterMs !== undefined && Number.isFinite(retryAfterMs) && retryAfterMs > 0\n    ? { retryAtMs: now + retryAfterMs, retrySource: 'upstream-reported' as const }\n    : outcome === 'out-of-credit' && quotaRefreshAtMs !== undefined && Number.isFinite(quotaRefreshAtMs)\n      ? { retryAtMs: quotaRefreshAtMs, retrySource: 'quota-refresh' as const }\n      : {}\n  return {\n    outcome,\n    atMs: now,\n    source: 'live-request',\n    // 真实请求能说出「哪个模型」时就带上；说不准就不写（而不是写个猜的）。\n    // 缺省时这条结论适用于任何模型，是修复前的粗糙行为，不是「所有模型都同意」。\n    ...(modelId === undefined || modelId === '' ? {} : { modelId }),\n    // 上游申报的等待时刻（issue #26）：上游说「等 30 秒」就是等 30 秒。此前这条\n    // 路把申报值丢了，池子按 30 分钟兜底 —— 差 60 倍。\n    // issue #32：申报值缺席时，`out-of-credit` 用签到快照的当日窗口时刻，别退\n    // 回 30 分钟。\n    ...retry,\n    // issue #32 第一条建议：连窗口时刻都没有时，这次排除走的是**本地兜底节奏**。\n    // `retryAtMs` 继续缺席（那个字段只放上游/推算给出的时刻），改用 `retrySource`\n    // 留下痕迹 —— 否则它与「上游没说、我们也不打算再试」在数据里长得一模一样。\n    ...fallbackCooldownOf(outcome, retry.retryAtMs, retry.retrySource),\n    ...queued\n      ? {\n          queue: {\n            ...context?.queue?.queueCount === undefined ? {} : { queueCount: context.queue.queueCount },\n            ...context?.queue?.queueType === undefined ? {} : { queueType: context.queue.queueType },\n          },\n        }\n      : {},\n    // 空串不写：那是「没有原因」，与「原因是空」是两件事（卡片按 undefined 说\n    // 「上游未给出」）。非空一律脱敏后带上 —— pt- 形态的凭据绝不能进落盘文件。\n    ...(message === '' ? {} : { message: redactUpstreamText(message) }),\n  }\n}\n\n/**\n * 一次真实请求的失败要不要记成**区域级**的「上游报额度耗尽」通知。\n *\n * 与 {@link liveRequestProbe} 的分工：那条按**账号**记、供池换号决策用，且有\n * 两道门（池关不记盘、非成员不记）；这条按**区域**记、纯粹给 UI 看——池关着时\n * 一次 code 110 的失败此前在任何面板上都无处显示（0.7.x 的「今日额度疑似已\n * 用尽」胶囊拆掉后留下的缺口）。只要 `kind` 是 `quota-exhausted`（上游业务码\n * 命中配额族）就记，展示口径「最近一次」——上游恢复正常不会主动通知，所以不\n * 设失效时刻，事实性由时间戳保证。\n *\n * 抽成纯函数的理由同 `liveRequestProbe`：接线变异掉时测试仍能钉住判据。\n */\nexport function liveQuotaExhaustion(\n  kind: UpstreamErrorKind,\n  message: string,\n  context: { status?: number | undefined, code?: string | undefined } | undefined,\n  nowMs: number,\n): QoderWebQuotaExhaustion | undefined {\n  if (kind !== 'quota-exhausted') return undefined\n  return {\n    ...(context?.code === undefined || context.code === '' ? {} : { code: context.code }),\n    message: redactUpstreamText(message),\n    atMs: nowMs,\n  }\n}\n\n/** 「这个区域此刻允不允许替用户换号」所需要的那一个偏好位。 */\nexport interface PoolGate {\n  enabled: boolean\n  memberAccountIds: readonly string[]\n}\n\n/**\n * **池开关是换号的唯一授权。** 关闭时不得改用任何别的账号。\n *\n * 这一条此前**缺着**：`nextFailoverCredential` 只读成员名单、从不读\n * `enabled`，于是「关掉账号池」这个最核心的开关**对换号完全无效** —— 只要\n * 成员非空，插件就永远在失败后悄悄换到另一个 PAT 计费，而用户以为自己关掉了\n * 自动行为。默认值是 `enabled: false`，所以这是**每一条全新安装**都在踩的路径。\n *\n * 注意作用域：签到/测试这两个**手动**批量动作**不**挂在这个开关上 —— 它们由\n * 用户亲手点击，不属于「插件替你决定」。只有换号与失败记录设门。\n */\nexport function poolAllowsFailover(prefs: PoolGate): boolean {\n  return prefs.enabled\n}\n\n/**\n * 该不该把一次「正在服务的请求失败」记成池状态。\n *\n * 两条守卫各挡一类误伤：\n *\n *  1. **池关不记**：关掉池子意味着插件不再替用户选号、也不再替用户换号。此时\n *     仍把失败写进池状态，用户下次开池会看到一堆根本没参与过任何决策的「上次\n *     失败」，也与「关了就完全回到手动选号」这条承诺冲突。\n *  2. **非成员不记**：勾选成员就是「我同意让这些号参与」。没勾的号不该因为一次\n *     恰好用了它的请求就被判出池 —— 那等于把用户没授权的开销当成默认值。\n *\n * `invalid-request` 一类不必在这里再挡：shim 的 `isFailoverEligible` 已经排除过\n * 它们（400 换谁都是 400），`liveRequestProbe` 不会为它们产出记录。\n */\nexport function shouldRecordPoolFailure(prefs: PoolGate, accountId: string): boolean {\n  if (!prefs.enabled) return false\n  if (accountId === '') return false\n  return prefs.memberAccountIds.includes(accountId)\n}\n\n/**\n * 一条换号播报的去重键：**同一个事实**才合并。\n *\n * 键里刻意含接管账号与失败种类：换成另一个账号回答、或失败原因变了\n * （限流 → 用尽），都是新事实，应当再说一次。反之，一次 Agent 回合里十几轮\n * 调用都以「A 用尽 → B 回答」进行时，它们只是同一件事重复了十几遍。\n */\nexport function failoverAnnounceKey(input: {\n  fromAccountId: string\n  toAccountId: string\n  kind: string\n}): string {\n  return `${input.fromAccountId}\\u0000${input.toAccountId}\\u0000${input.kind}`\n}\n\n/**\n * 记录并回答「这条播报是否应当发出」：第一次 true，之后同一个键 false。\n *\n * `seen` 是调用方的有界 Map（值只当作插入顺序序号用，不参与判断）。重复的键会\n * 被重新插入，从而在超限淘汰时保住仍然活跃的那一条。\n */\nexport function shouldAnnounceFailoverOnce(\n  seen: Map<string, number>,\n  input: { fromAccountId: string, toAccountId: string, kind: string },\n): boolean {\n  const key = failoverAnnounceKey(input)\n  if (seen.has(key)) {\n    seen.delete(key)\n    seen.set(key, 0)\n    return false\n  }\n  seen.set(key, 0)\n  while (seen.size > FAILOVER_ANNOUNCE_MAX_ENTRIES) {\n    const oldest = seen.keys().next()\n    if (oldest.done === true) break\n    seen.delete(oldest.value)\n  }\n  return true\n}\n\n/** 某个账号不再被排除时，把它参与过的播报记录一并清掉（下一次重新播报）。 */\nexport function clearAnnouncedFailoversFrom(seen: Map<string, number>, accountId: string): void {\n  const prefix = `${accountId}\\u0000`\n  for (const key of [...seen.keys()]) {\n    if (key.startsWith(prefix) || key.includes(`\\u0000${accountId}\\u0000`)) seen.delete(key)\n  }\n}\n\n/**\n * @deprecated 用 {@link quotaRefreshOfAccount}（按账号 id）或\n * {@link quotaRefreshOfStored}（再叠一层磁盘）。\n *\n * 保留它只为**不删已发布过的导出**（1.17.4 的 `lib/index.d.ts` 里有这个名字，\n * 补丁版本不该把它拿走）。但它正是 issue #32 那个坑的形状：它替调用方把 PAT\n * 派生成 id，而真实请求路径手里**本来就是 id** —— 再派生一次得到\n * `pat-<hash(pat-…)>`，永远取不到，修复静默失效而纯函数测试全绿。\n *\n * 只在你手里确实是 PAT 时用它；其余情况直接用 id 那个入口。\n */\nexport function quotaRefreshOf(\n  snapshot: Readonly<Record<string, { refreshAtMs?: number }>> | undefined,\n  pat: string,\n): { quotaRefreshAtMs?: number } {\n  return quotaRefreshOfAccount(snapshot, qoderAccountId(pat))\n}\n\n/**\n * 「当日用量用尽」(code 110) 的恢复时刻，从签到快照按**账号 id** 取。\n *\n * 上游在签到报文里给了这个时刻（`daily.endAt`），签到批次把它存进快照；这里\n * 就按 id 取。取不到时返回 `{}`（不传）—— 这是**故意的保守**：宁可用 30 分钟\n * 兜底，也不在本机编一个「次日零点」。官方页面上那个数字才是准的，编出来的会\n * 让用户在错的时间回来（与 `cooldownOf` 的既有注释同一条规矩）。\n *\n * ⚠️ **键是账号 id（`pat-…`），不是 PAT**，这是 issue #32 那个坑：真实请求路径\n * （`onServingFailure`）只拿得到 `accountId`，而探测路径手里是 PAT。曾经有一个\n * 内部先 `qoderAccountId(pat)` 再取的入口，把 `pat-abc…` 再哈希一次得到\n * `pat-<hash(pat-…)>`，于是永远取不到、修复静默失效（纯函数测试还全绿）。\n * 现在派生一律由**调用方**做，本函数只认 id —— 少一个入口就少一处能踩。\n */\nexport function quotaRefreshOfAccount(\n  snapshot: Readonly<Record<string, { refreshAtMs?: number }>> | undefined,\n  accountId: string,\n): { quotaRefreshAtMs?: number } {\n  const refreshAtMs = snapshot?.[accountId]?.refreshAtMs\n  return refreshAtMs === undefined ? {} : { quotaRefreshAtMs: refreshAtMs }\n}\n\n/**\n * 同上，但在进程内快照之外再看一眼**落过盘**的窗口时刻（issue #32 第三条）。\n *\n * 为什么需要第三个入口：`checkinSnapshots` 是进程内对象，注释里也写了「重启后\n * 由下一次签到重新写入」。而 110 的兜底冷却恰恰只在「窗口时刻不知道」时生效 ——\n * 于是进程一重启兜底就必然生效，用户看到的就是「这个号每半小时被试探一次」。\n * 窗口时刻本身是一个**绝对时间点**（上游活动行的 `endAt`），它跨重启仍然成立。\n *\n * 顺序：进程内快照优先（它带今天的 `claimed` 语境），其次磁盘。两者都没有时\n * 返回 `{}`，让调用方走兜底 —— 与这套代码一贯的「宁缺勿错」同规。\n */\nexport function quotaRefreshOfStored(\n  snapshot: Readonly<Record<string, { refreshAtMs?: number }>> | undefined,\n  stored: Readonly<Record<string, number>> | undefined,\n  accountId: string,\n  nowMs: number = Date.now(),\n): { quotaRefreshAtMs?: number } {\n  const fromSnapshot = quotaRefreshOfAccount(snapshot, accountId)\n  if (fromSnapshot.quotaRefreshAtMs !== undefined) return fromSnapshot\n  const fromDisk = stored?.[accountId]\n  // 已经过去的窗口时刻不算数：拿一个旧日期去当「下次恢复时刻」会让这个号被\n  // 判到很久以后才解禁，而那时上游早就恢复了。\n  return fromDisk === undefined || fromDisk <= nowMs ? {} : { quotaRefreshAtMs: fromDisk }\n}\n"
    },
    {
      "path": "src/accounts.ts",
      "content": "/**\n * Qoder 账号库：按区域隔离的 PAT 保险库 + 账号解析。\n *\n * 参考：dsh-connect-workbuddy（MIT，Copyright (c) 2026 LaoDing）的\n *   `src/auth.ts` —— 插件自有凭据文件的约定（`$DSH_HOME` 下按区域分文件、\n *   `withFileLock` + `writeFileAtomic`、`mode: 0o600`）、「账号列表与选中\n *   分离，选中存设置」「读取永不抛异常」的语义沿用其做法。\n * 改动：WorkBuddy 的账号来自桌面端登录文件 + OAuth 扫码；Qoder 的账号\n *   就是 PAT 本身，来源三种——设置卡片的 PAT 字段、环境变量、以及本模块\n *   维护的插件自有保险库（卡片「添加账号」与转账导入写入）。账号 id 由\n *   PAT 单向派生（见 `credentials.ts` 的 `qoderAccountId`），不依赖联机\n *   验证，也不把 token 材料泄进 id。\n *\n * 本模块不碰网络：PAT 的有效性验证（jobToken 交换）在 Host 路由层完成，\n * 这里只负责持久化与解析。\n *\n * @module dsh-connect-qoder/accounts\n */\n\nimport { readFile } from 'node:fs/promises'\nimport { join } from 'node:path'\nimport { withFileLock, writeFileAtomic } from '@deepseek-ai/dsh-atomic-write'\nimport { resolveDshHome } from '@deepseek-ai/dsh-home-paths'\nimport { qoderAccountId } from './credentials.ts'\nimport type { QoderRegion } from './upstream.ts'\n\n/** On-disk format version; readers reject anything else. */\nconst VAULT_FORMAT_VERSION = 1\n\n/** Filename prefix for one region's account vault. */\nconst VAULT_PREFIX = '.qoder-accounts'\n\n/** One stored PAT entry. */\nexport interface QoderStoredAccount {\n  /** Stable id derived from the PAT (`pat-<sha256[:16]>`). */\n  id: string\n  /** Display name from the gateway's jobToken exchange, or `''`. */\n  accountName: string\n  /** The credential itself. Never leaves the Host. */\n  pat: string\n  /** When the entry was added, epoch ms. */\n  addedAtMs: number\n}\n\n/** The vault document actually written to disk. */\ninterface VaultDocument {\n  version: typeof VAULT_FORMAT_VERSION\n  accounts: QoderStoredAccount[]\n}\n\n/**\n * One account as the account table sees it — token-free.\n *\n * `source` says where the credential lives: the settings card's PAT field,\n * an environment variable, or this vault. The first two are managed outside\n * the plugin (edit the field / the environment), so only `vault` entries are\n * removable through the card.\n */\nexport interface QoderAccountEntry {\n  id: string\n  accountName: string\n  source: 'settings' | 'env' | 'vault'\n}\n\n/** One resolved credential: the account plus its PAT. */\nexport interface QoderResolvedCredential extends QoderAccountEntry {\n  pat: string\n}\n\n/** Whether a parsed value looks like a stored account entry. */\nfunction isStoredAccount(value: unknown): value is QoderStoredAccount {\n  if (typeof value !== 'object' || value === null) return false\n  const candidate = value as Record<string, unknown>\n  return typeof candidate['id'] === 'string' && candidate['id'] !== ''\n    && typeof candidate['pat'] === 'string' && candidate['pat'] !== ''\n    && typeof candidate['accountName'] === 'string'\n    && typeof candidate['addedAtMs'] === 'number'\n}\n\n/** One region's vault path. */\nexport function qoderAccountsPath(region: QoderRegion): string {\n  return join(resolveDshHome(), `${VAULT_PREFIX}.${region}.json`)\n}\n\n/**\n * One region's account store.\n *\n * Reads never throw: a missing, unreadable, malformed, or version-mismatched\n * vault all mean \"no stored accounts\", which is a valid state — the pool and\n * the card simply show an empty account list. Writes go through the file lock\n * and an atomic replace, same as the credential copies in the sibling plugin.\n */\nexport class QoderAccountStore {\n  readonly region: QoderRegion\n\n  constructor(region: QoderRegion) {\n    this.region = region\n  }\n\n  /** The vault entries, in insertion order. */\n  async vaultAccounts(): Promise<QoderStoredAccount[]> {\n    let raw: string\n    try {\n      raw = await readFile(qoderAccountsPath(this.region), 'utf8')\n    } catch {\n      return []\n    }\n    let parsed: unknown\n    try {\n      parsed = JSON.parse(raw)\n    } catch {\n      return []\n    }\n    if (typeof parsed !== 'object' || parsed === null) return []\n    const document = parsed as Partial<VaultDocument>\n    if (document.version !== VAULT_FORMAT_VERSION) return []\n    if (!Array.isArray(document.accounts)) return []\n    return document.accounts.filter(isStoredAccount)\n  }\n\n  /**\n   * Every account this region can bill, merged from all three sources.\n   *\n   * Order is the resolution priority: the settings PAT first, then the\n   * environment PAT, then the vault. A PAT appearing in two sources is listed\n   * ONCE, under the higher-priority source — the id is derived from the PAT\n   * itself, so duplicates are exact.\n   */\n  async accounts(sources: { settingsPat?: string | undefined, envPat?: string | undefined }): Promise<QoderAccountEntry[]> {\n    const out: QoderAccountEntry[] = []\n    const seen = new Set<string>()\n    const settingsPat = sources.settingsPat?.trim()\n    if (settingsPat) {\n      const id = qoderAccountId(settingsPat)\n      seen.add(id)\n      out.push({ id, accountName: '', source: 'settings' })\n    }\n    const envPat = sources.envPat?.trim()\n    if (envPat) {\n      const id = qoderAccountId(envPat)\n      if (!seen.has(id)) {\n        seen.add(id)\n        out.push({ id, accountName: '', source: 'env' })\n      }\n    }\n    for (const stored of await this.vaultAccounts()) {\n      if (seen.has(stored.id)) continue\n      seen.add(stored.id)\n      out.push({ id: stored.id, accountName: stored.accountName, source: 'vault' })\n    }\n    return out\n  }\n\n  /**\n   * The PAT for one account id, from whichever source holds it.\n   *\n   * Resolving by id — rather than touching the region's selection — is what\n   * lets a pool batch address every account while the user's chosen account\n   * keeps serving traffic.\n   */\n  async credentialFor(\n    accountId: string,\n    sources: { settingsPat?: string | undefined, envPat?: string | undefined },\n  ): Promise<QoderResolvedCredential | undefined> {\n    const settingsPat = sources.settingsPat?.trim()\n    if (settingsPat && qoderAccountId(settingsPat) === accountId) {\n      return { id: accountId, accountName: '', source: 'settings', pat: settingsPat }\n    }\n    const envPat = sources.envPat?.trim()\n    if (envPat && qoderAccountId(envPat) === accountId) {\n      return { id: accountId, accountName: '', source: 'env', pat: envPat }\n    }\n    const stored = (await this.vaultAccounts()).find(account => account.id === accountId)\n    return stored === undefined\n      ? undefined\n      : { id: stored.id, accountName: stored.accountName, source: 'vault', pat: stored.pat }\n  }\n\n  /**\n   * The credential that serves traffic right now.\n   *\n   * `selectedId` is the user's explicit per-region choice (`''`/undefined =\n   * automatic). Automatic resolution follows source priority: settings PAT,\n   * then env PAT, then the first vault entry. An explicit id that resolves to\n   * nothing falls back to automatic rather than stranding the region — the\n   * card reports `selectionLost` so the user sees why.\n   */\n  async resolve(\n    sources: { settingsPat?: string | undefined, envPat?: string | undefined },\n    selectedId?: string,\n  ): Promise<QoderResolvedCredential | undefined> {\n    if (selectedId !== undefined && selectedId !== '') {\n      const chosen = await this.credentialFor(selectedId, sources)\n      if (chosen !== undefined) return chosen\n    }\n    const settingsPat = sources.settingsPat?.trim()\n    if (settingsPat) return { id: qoderAccountId(settingsPat), accountName: '', source: 'settings', pat: settingsPat }\n    const envPat = sources.envPat?.trim()\n    if (envPat) return { id: qoderAccountId(envPat), accountName: '', source: 'env', pat: envPat }\n    const first = (await this.vaultAccounts())[0]\n    return first === undefined\n      ? undefined\n      : { id: first.id, accountName: first.accountName, source: 'vault', pat: first.pat }\n  }\n\n  /**\n   * Add (or refresh) one vault entry. Keyed by the PAT-derived id: re-adding\n   * the same token updates its name in place rather than duplicating it.\n   */\n  async add(pat: string, accountName: string): Promise<QoderStoredAccount> {\n    const entry: QoderStoredAccount = {\n      id: qoderAccountId(pat),\n      accountName,\n      pat,\n      addedAtMs: Date.now(),\n    }\n    await this.mutate(accounts => {\n      const index = accounts.findIndex(account => account.id === entry.id)\n      if (index === -1) return [...accounts, entry]\n      const next = [...accounts]\n      next[index] = { ...next[index]!, accountName: entry.accountName, pat: entry.pat }\n      return next\n    })\n    return entry\n  }\n\n  /**\n   * Remove one vault entry. Only vault entries are removable — the settings\n   * and env PATs are managed outside the plugin. Returns whether anything\n   * was actually removed.\n   */\n  async remove(accountId: string): Promise<boolean> {\n    let removed = false\n    await this.mutate((accounts) => {\n      const next = accounts.filter(account => account.id !== accountId)\n      removed = next.length !== accounts.length\n      return next\n    })\n    return removed\n  }\n\n  /** Backfill a display name learned later (from a jobToken exchange). */\n  async rename(accountId: string, accountName: string): Promise<void> {\n    if (accountName === '') return\n    await this.mutate(accounts => accounts.map(account =>\n      account.id === accountId && account.accountName !== accountName\n        ? { ...account, accountName }\n        : account,\n    ))\n  }\n\n  /** Empty the vault. Used by the CLI's `logout`. */\n  async clear(): Promise<void> {\n    await this.mutate(() => [])\n  }\n\n  /** One locked read-modify-write of the vault document. */\n  private async mutate(edit: (accounts: QoderStoredAccount[]) => QoderStoredAccount[]): Promise<void> {\n    const path = qoderAccountsPath(this.region)\n    await withFileLock(path, async () => {\n      const accounts = edit(await this.vaultAccounts())\n      const document: VaultDocument = { version: VAULT_FORMAT_VERSION, accounts }\n      await writeFileAtomic(path, `${JSON.stringify(document, null, 2)}\\n`, {\n        mode: 0o600,\n        dirMode: 0o700,\n      })\n    })\n  }\n}\n"
    },
    {
      "path": "src/upstream.ts",
      "content": "/**\n * Qoder 上游 HTTP 客户端：cosy 签名请求、jobToken 交换、聊天 SSE、\n * 模型目录与用量查询。\n *\n * 端点映射（CN 与 Global 双区域）。两区域**各自一个网关主机**，chat / models /\n * jobToken 三个端点共用它（见 `QODER_REGIONS` 的 `gateway` 字段）：\n *\n * ```text\n * CN     gateway: gateway.qoder.com.cn\n *        chat:     /algo/api/v2/service/pro/sse/agent_chat_generation\n *        models:   /algo/api/v2/model/list\n *        jobToken: /algo/api/v3/user/jobToken\n *        openapi:  openapi.qoder.com.cn\n * Global gateway: api1.qoder.sh\n *        chat:     /algo/api/v2/service/pro/sse/agent_chat_generation\n *        models:   /algo/api/v2/model/list\n *        jobToken: /algo/api/v3/user/jobToken\n *        openapi:  openapi.qoder.sh\n * ```\n *\n * 注：早期注释称国际版的 models 走 `api2.qoder.sh`、jobToken 走\n * `center.qoder.sh`。实测（2026-10）三者对本插件用到的端点**完全等效**——\n * 对同一个假 PAT 都回 `401 personal token is invalid`（凭据层被拒，而非\n * `Signature invalid`），说明三者都接受同一套 cosy 签名、只是拒绝坏凭据。\n * 所以国际版统一用 `api1.qoder.sh`，不按端点分主机；若将来真要分流，请改\n * `QODER_REGIONS` 的配置表，而不是只改这段注释。\n *\n * @module dsh-connect-qoder/upstream\n */\n\nimport {\n  buildPayloadB64,\n  composeBearer,\n  cosyEncode,\n  currentRfc1123Date,\n  deriveFingerprint,\n  newCosySession,\n  pathSigFrom,\n  signLegacy,\n  signRequest,\n  type CosyFingerprint,\n  type CosySessionContext,\n} from './cosy.ts'\nimport { createChatBodyTemplate, buildQoderMessages, extractLatestUserPrompt, deepClone, applyModelKey, type QoderChatTemplate } from './messages.ts'\nimport { readDeviceRisk } from './device-risk.ts'\nimport { QODER_UPSTREAM_DOMAIN } from './status-paths.ts'\nimport { isRouterModelId } from './native-modality.ts'\n\n// ---------------------------------------------------------------------------\n// 区域\n// ---------------------------------------------------------------------------\n\nexport type QoderRegion = 'cn' | 'global'\n\nexport interface QoderRegionConfig {\n  /** 网关主机（chat / models / jobToken 共用）。 */\n  gateway: string\n  /** OpenAPI 主机（用量/计划/签到等 sash 接口）。 */\n  openapi: string\n  /** SSE 聊天端点。 */\n  chatPath: string\n  /** 模型目录端点。 */\n  modelsPath: string\n  /** jobToken 交换端点。 */\n  jobTokenPath: string\n  /** 每日签到的活动列表端点（sash 的 v1 campaigns）。 */\n  campaignsPath: string\n  /**\n   * 该区域的签到是否需要**设备风控头**（`Cosy-MachineToken/Code/Type`）。\n   *\n   * 国际版为 true：它的签到活动只下发给带这些头的请求，缺了拿不到活动列表\n   * （实测端点存在，返回 401 而不是 404）。国内版为 false —— 实测不需要，\n   * 多发反而在另一侧成为噪音。三件套由本机 UMID 组件生成，见 device-risk.ts。\n   */\n  requiresDeviceRisk: boolean\n}\n\n/** 一条活动（`GET /sash/api/v1/me/campaigns` 的条目，只取用得到的字段）。 */\nexport interface QoderCampaign {\n  campaignId: string\n  /** `CLAIM_BENEFIT` = 可领权益；`VIEW_DETAILS` = 纯展示（banner / 集结）。 */\n  actionType: string\n  /** `CLAIMABLE` = 今天可领；`CLAIMED` = 已领。 */\n  claimStatus: string\n  /** 奖励数额（Credits），来自 `benefit.amount`。 */\n  amount?: number\n  /**\n   * 有效期天数，来自 `benefit.validity.days`。\n   *\n   * 只在 `validity.mode === 'RELATIVE_DAYS'` 时给出 —— 「领取后再过 N 天作废」\n   * 这个口径成立的前提是**相对**。上游若哪天改成 `ABSOLUTE`（给一个绝对时刻），\n   * 天数就不再是那个意思，这里会**不写** `validityDays`：宁可不显示到期，也不\n   * 拿一个口径不对的数字去算「什么时候作废」（issue #31 建议 3）。\n   */\n  validityDays?: number\n  /**\n   * 这条活动**开窗**的时刻（epoch **秒** —— 上游给的就是秒，不是毫秒）。\n   *\n   * 实测（`campaignKey: act-20261009-057`）：`startAt` = 当天 10:00:00 UTC+8，\n   * `endAt` = 次日 09:59:00 UTC+8，与活动文案「每日 10:00（UTC+8）刷新」一致。\n   * 所以「下一次刷新还有多久」是**上游给的**，不是本地按零点或「上次领取 +24h」\n   * 猜出来的 —— 用户实拍里那个 `09:22:23` 就是 `endAt − 当前时间`。\n   */\n  startAt?: number\n  /** 这条活动**关窗**的时刻（epoch 秒），即下一次刷新的时刻。 */\n  endAt?: number\n  /** 上游的活动键（如 `act-20261021-587`），只作展示用。 */\n  campaignKey?: string\n  /** 这条活动的落地页：`placements[*].campaignUrl` 的第一个，缺则顶层 `campaignUrl`。 */\n  campaignUrl?: string\n  /**\n   * `placements[*].content` 按语言收拢后的**卡片文案**（`zh` / `en` 各一份，可能都缺）。\n   *\n   * 「1024 创造力集结」「首月订阅 Credits 翻倍」这类 banner 的标题、描述与\n   * 「查看详情」链接就在这儿 —— 上游只下发它有的语言，这里不做翻译、不编造。\n   */\n  content?: Record<string, QoderCampaignContent>\n}\n\n/** 一条活动卡片文案（某一语言）。 */\nexport interface QoderCampaignContent {\n  title?: string\n  description?: string\n  detailUrl?: string\n  buttonText?: string\n}\n\n/** `GET /sash/api/v1/me/campaigns` 的整份响应（含活动列表之外的顶层字段）。 */\nexport interface QoderCampaignFeed {\n  campaigns: QoderCampaign[]\n  /** 顶层活动落地页（成长页 iframe）；某条活动缺 `detailUrl` 时的兜底链接。 */\n  campaignUrl?: string\n  /** 上游显式说「这次不下发活动」（开关 / 非目标人群）。 */\n  showCampaign?: boolean\n  /** 上游显式说「本次不可领」。 */\n  claimable?: boolean\n}\n\n/** 一次签到尝试的结果。 */\nexport type QoderCheckinOutcome =\n  | {\n      status: 'claimed'\n      amount?: number\n      validityDays?: number\n      /**\n       * 下一窗的开门时刻（epoch 毫秒，来自上游 `endAt` × 1000）。\n       *\n       * 领取**不是**「今天到此为止」—— 领取只是把这一窗从 `CLAIMABLE` 变成\n       * `CLAIMED`，而下一窗什么时候开上游早就写在了 `endAt` 里。没有它，UI 只能\n       * 说「已领取」，用户会以为要等到明天零点（用户实拍：领取后页面上的倒计时\n       * 才是正确的那个数）。\n       */\n      nextRefreshAtMs?: number\n    }\n  | { status: 'already-claimed', nextRefreshAtMs?: number }\n  | { status: 'unavailable', message: string }\n\nconst CHAT_PATH = '/algo/api/v2/service/pro/sse/agent_chat_generation?FetchKeys=llm_model_result&AgentId=agent_common&Encode=1'\n/**\n * 每日签到走 `sash` 的**活动**接口。路径里没有「签到」二字（叫 campaigns），\n * 所以照着 checkin / signin / reward 猜永远猜不到——实测猜了 13 个全 404。\n * 注意是 **v1**（用量那套是 v2）。\n */\nconst CAMPAIGNS_PATH = '/sash/api/v1/me/campaigns'\n/**\n * sash 面专用的令牌交换端点（CLI / 网页那一族）。\n *\n * 与 {@link JOB_TOKEN_PATH}（桌面客户端那一族）**并存**，不是替代 —— 实测国际版\n * 的 chat 面只认前者换来的 `securityOauthToken`，而 sash / 额度面只认这里换来的\n * `token`；国内版两族等价。见 `QoderSessionHolder.sashToken`。\n */\nconst SASH_TOKEN_PATH = '/api/v1/jobToken/exchange'\nconst CAMPAIGNS_QUERY = '?forceRefresh=true'\n/** sash 接口要求的客户端标识（参考实现如此，缺了会被拒）。 */\nconst SASH_CLIENT_TYPE = '10'\nconst SASH_USER_AGENT = 'Qoder'\n/**\n * **cosy 面**（chat + models）的客户端身份：`cosy-clienttype` 与 `cosy-version`。\n *\n * 上游按这两个头决定下发哪一套模型目录。旧值 `5` / `0.1.43` 是 2026-10-11 写下\n * 时正确的身份，那时上游还没有 Sonus/Cantus/Fast；上游后来把新模型只发给新\n * 协议，于是旧身份拿到的是**静默的旧目录**——目录照常返回、对话照常能跑，只是\n * 少几个模型，没有任何报错指向这里（issue #21）。\n *\n * 实测（2026-10-29，两个区域各一枚真实 PAT，只读目录 + 一次对话）：\n *\n * | 区域   | `5` / `0.1.43` | `10` / `1.1.69`        |\n * | ------ | -------------- | ---------------------- |\n * | cn     | 9 条           | 10 条（+`fast`）       |\n * | global | 11 条          | 14 条（+`smodel`/`cmodel`/`fast`） |\n *\n * 两个值必须**成对**改：国内版只把 clienttype 提到 `10`、version 留在 `0.1.43`\n * 时，目录仍只有 9 条（拿不到 `fast`），而 chat 直接报\n * `HTTP 403 code 112`（「协议半改」的坏状态）。成对改之后 chat 两个区域都正常\n * 吐字，`qfmodel` / `dfmodel` 与新增的 `fast` / `smodel` 都实测通过。\n *\n * 与 sash 面**无关**：`sashRequest` / `fetchUsageDirect` / `jobTokenGet` 是逐条\n * 手写请求头，没有展开 {@link DEFAULT_HEADERS}，所以这条改动碰不到签到与用量\n * （实测改完两个区域的用量与活动列表照常 200）。\n *\n * `COSY_VERSION`（`src/cosy.ts`，进 bearer **载荷**的那个）刻意**不**跟着改：\n * 它只参与签名与身份声明，实测在头为 `10` / `1.1.69` 时保持 `0.1.43` 两个区域\n * 的目录、对话、用量、活动全部正常。改它是另一件事，没有收益，不做。\n */\nconst COSY_CLIENT_TYPE = '10'\nconst COSY_VERSION_HEADER = '1.1.69'\nconst MODELS_PATH = '/algo/api/v2/model/list?Encode=1'\nconst JOB_TOKEN_PATH = '/algo/api/v3/user/jobToken?Encode=1'\n\nexport const QODER_REGIONS: Readonly<Record<QoderRegion, QoderRegionConfig>> = {\n  cn: {\n    // 主机名只有一处事实（`status-paths.ts` 的 `QODER_UPSTREAM_DOMAIN`），卡片\n    // 的「诊断」栏读的也是它——这样「面板上写的域名」与「请求真正打到的域名」\n    // 不可能各说一套。\n    gateway: `https://${QODER_UPSTREAM_DOMAIN.cn}`,\n    openapi: 'https://openapi.qoder.com.cn',\n    chatPath: CHAT_PATH,\n    modelsPath: MODELS_PATH,\n    jobTokenPath: JOB_TOKEN_PATH,\n    campaignsPath: CAMPAIGNS_PATH,\n    requiresDeviceRisk: false,\n  },\n  global: {\n    gateway: `https://${QODER_UPSTREAM_DOMAIN.global}`,\n    openapi: 'https://openapi.qoder.sh',\n    chatPath: CHAT_PATH,\n    modelsPath: '/algo/api/v2/model/list?Encode=1',\n    jobTokenPath: '/algo/api/v3/user/jobToken?Encode=1',\n    campaignsPath: CAMPAIGNS_PATH,\n    requiresDeviceRisk: true,\n  },\n}\n\n// ---------------------------------------------------------------------------\n// 类型\n// ---------------------------------------------------------------------------\n\n/** 上游错误分类，供 shim 映射为 DSH 可判定的 code。 */\nexport type UpstreamErrorKind =\n  | 'network'           // 传输层（TLS/EOF/reset/超时）\n  | 'auth'              // 401/403：凭证被拒 / 会话过期\n  | 'rate-limited'      // 429：限流\n  | 'invalid-request'   // 400：请求不合法（重试无意义）\n  | 'content-policy'    // 内容审核拒绝\n  | 'quota-exhausted'   // 业务 code 表示额度耗尽\n  | 'transient'         // 418/5xx/provider_error：瞬时\n  | 'unknown'\n\nexport class QoderUpstreamError extends Error {\n  readonly kind: UpstreamErrorKind\n  readonly status: number\n  readonly code?: string | undefined\n  /**\n   * 上游**自己申报**的「请等这么久再试」，毫秒（issue #24）。\n   *\n   * 来自 `10605 / RESOURCE_LIMIT` 信封里的 `retryAfterSeconds`（实测形状：\n   * `{\"isQueued\":false,\"queueCount\":0,\"retryAfterSeconds\":5,\"serviceAvailable\":true}`），\n   * 或 HTTP `Retry-After` 头。取不到就是 `undefined` —— 「上游没说」与「上游说\n   * 等 0 秒」是两件事，抽取层不替它下结论。\n   *\n   * 这个值的去向有两处，都必须有：①写进给宿主的失败文案（否则用户只看到\n   * 「上游报了个 4xx」，看不到「上游只要求等 5 秒」）；②非流式失败响应上的\n   * `Retry-After` 头。宿主在 pi-ai 那条路由上**只从文案分类**，不读头，所以\n   * ①是唯一能让「申报值」影响等待的一条。\n   */\n  readonly retryAfterMs?: number | undefined\n  /**\n   * 上游说「我在排队」的证据（issue #26）。\n   *\n   * 与 {@link retryAfterMs} 分开是因为它们是**两件事**：`retryAfterMs` 说\n   * 「等多久再来」，`queue` 说「你现在排在第几位、服务本身是好的」。前者决定\n   * 冷却多长，后者决定**怎么跟用户说** —— 把排队说成「连不上上游」是错的\n   * （用户实拍：账号完全正常，六个模型同时可用）。\n   */\n  readonly queue?: QoderQueueState | undefined\n  constructor(kind: UpstreamErrorKind, message: string, status = 0, code?: string, retryAfterMs?: number, queue?: QoderQueueState) {\n    super(message)\n    this.name = 'QoderUpstreamError'\n    this.kind = kind\n    this.status = status\n    this.code = code\n    if (retryAfterMs !== undefined && Number.isFinite(retryAfterMs) && retryAfterMs > 0) {\n      this.retryAfterMs = retryAfterMs\n    }\n    if (queue !== undefined) {\n      this.queue = queue\n    }\n  }\n}\n\n/**\n * 上游的排队状态（issue #26 的实测信封）。\n *\n * 实测形状（HTTP 403 + `code 10605`）：\n *\n * ```json\n * {\"code\":\"10605\",\"message\":{\"isQueued\":true,\"modelKey\":\"dfmodel\",\n *   \"queueCount\":1027,\"queueType\":\"p3\",\"retryAfterSeconds\":30,\n *   \"serviceAvailable\":true,\"subCode\":\"CALL_COUNT_LIMIT\",\"waitTime\":119}}\n * ```\n *\n * `isQueued:true` + `serviceAvailable:true` 的意思是「**服务是好的**，你排在\n * 队列第 1027 位，30 秒后再来」。上游说得很清楚，插件此前把它读成了「连不上\n * 上游」。\n */\nexport interface QoderQueueState {\n  /** 上游明确说了「在排队」。 */\n  isQueued: boolean\n  /** 队列里的人头数（上游给的，不是本地估的）。 */\n  queueCount?: number\n  /** 队列类型（上游的 p1/p2/p3 之类）。 */\n  queueType?: string\n  /** 上游申报的等待秒数；与 `retryAfterMs` 同源，但保留原始单位。 */\n  retryAfterSeconds?: number\n  /**\n   * 上游自己说「服务本身可用吗」（issue #29）。\n   *\n   * 这个字段把两种形态分开，而它们此前被压成同一个 `queued`：\n   *\n   * - `isQueued:true` + `serviceAvailable:true` —— 服务是好的，你排在队里\n   *   （`queueCount` 通常 > 0）。等等就好，换号也有意义。\n   * - `isQueued:true` + `serviceAvailable:false` —— 上游**整体**在拒服务，\n   *   现场实测 `queueCount:0`（队列里一个人都没有）。这时换号、换 PAT 都没用\n   *   （issue #29 实测 global 区 14 个模型全 queued），把它写进账号级冷却会让\n   *   用户以为自己的凭据坏了。\n   *\n   * 缺席 = 上游没提这个字段；此时沿用旧行为（只按 `isQueued` 判排队），不推断。\n   */\n  serviceAvailable?: boolean\n}\n\nexport function isQoderUpstreamError(error: unknown): error is QoderUpstreamError {\n  return error instanceof QoderUpstreamError\n}\n\n/** jobToken 交换结果。 */\nexport interface QoderJobToken {\n  id: string\n  name: string\n  expireTime: number\n  securityOauthToken: string\n  refreshToken: string\n  userType: string\n}\n\n/** 模型目录条目（服务端 snake_case 原样透传 + 常用字段解析）。 */\nexport interface QoderUpstreamModel {\n  key: string\n  display_name: string\n  enable: boolean\n  is_default: boolean\n  is_vl: boolean\n  is_reasoning: boolean\n  is_free: boolean\n  price_factor: number | undefined\n  max_input_tokens: number | undefined\n  max_output_tokens: number | undefined\n  thinking_config: Record<string, unknown> | undefined\n  context_config: Record<string, { token_count: number; is_default?: boolean }> | undefined\n  /** 其余字段原样保留。 */\n  raw: Record<string, unknown>\n}\n\n/** 用量信息（sash/api/v2/me/usage 的 qoderUsage 形状，官方 SDK UsageInfo 核对）。 */\nexport interface QoderUsage {\n  userType?: string | undefined\n  expiresAt?: number | undefined\n  upgradeUrl?: string | undefined\n  userQuota?: { total?: number | undefined; used?: number | undefined; remaining?: number | undefined; percentage?: number | undefined } | undefined\n  addOnQuota?: { total?: number | undefined; used?: number | undefined; remaining?: number | undefined; percentage?: number | undefined; detailUrl?: string | undefined } | undefined\n  orgResourcePackage?: { used?: number | undefined; cap?: number | undefined; remaining?: number | undefined; percentage?: number | undefined; available?: boolean | undefined } | undefined\n  isQuotaExceeded?: boolean\n}\n\n/** 聊天流增量。 */\nexport interface QoderChatDelta {\n  role: string\n  content: string\n  reasoningContent: string\n  toolCalls: unknown[] | undefined\n  inputTokens: number\n  outputTokens: number\n  /**\n   * 命中的缓存 token 数（issue #4）：上游 `prompt_tokens_details.cached_tokens`。\n   *\n   * **它是 `inputTokens` 的子集，不是额外增量。** 实测（2026-10-22，cn，\n   * `qfmodel`）两轮真实请求的原始 usage 块：\n   *\n   * ```\n   * prompt_tokens: 2038, prompt_tokens_details: { cacheable_tokens: 0, cached_tokens: 2032 }\n   * prompt_tokens: 2057, prompt_tokens_details: { cacheable_tokens: 0, cached_tokens: 2051 }\n   * ```\n   *\n   * 所以**绝不能**写 `inputTokens = prompt_tokens + cached_tokens`——那是把命中\n   * 的前缀算两遍。宿主 `parseChunkUsage` 正是按「子集」理解它的：\n   * `input = max(0, prompt_tokens - cacheRead - cacheWrite)`，它要的就是原始的\n   * `prompt_tokens` 与 `cached_tokens` 两个数，各自原样交过去即可。\n   *\n   * `undefined` = 上游这一帧没报（或没给这个字段）。它与「命中 0」是两件事，\n   * 别在抽取层把前者写成后者。\n   */\n  cachedTokens?: number\n}\n\n// ---------------------------------------------------------------------------\n// 客户端\n// ---------------------------------------------------------------------------\n\nexport interface QoderUpstreamOptions {\n  logger?: (message: string) => void\n  /** 本机指纹盐（可选，混入派生种子）。 */\n  installSalt?: string\n  fetch?: typeof fetch\n}\n\n/** cosy 会话 + 指纹的持有者（每次 jobToken 交换后重建）。 */\nexport interface QoderSessionHolder {\n  session: CosySessionContext\n  fingerprint: CosyFingerprint\n  jobToken: QoderJobToken\n  /** 会话过期毫秒时间戳；0 表示未知。 */\n  expireAtMs: number\n  /**\n   * 另一族令牌：`POST /api/v1/jobToken/exchange` 换来的 `token`，sash 面专用。\n   *\n   * 国际版需要**两族并存**，实测（本机两个真实 PAT，只读）：\n   *\n   * | 面 | 认哪一族 |\n   * | --- | --- |\n   * | chat / cosy（模型对话） | 旧的 `securityOauthToken`（本字段缺席） |\n   * | sash / 额度（积分、签到） | 新的 `token`（本字段） |\n   *\n   * 换成新的会让国际版对话 403（code 105 登录态失效），继续用旧的会让国际版积分\n   * 401（TOKEN_EXPIRE）—— 而令牌 `expireTime` 还有 24 小时，所以不是过期问题。\n   * 国内版两族等价，这个差异**只在国际版显形**。\n   *\n   * 缺席 = 还没换过（或者换失败）。sash 那一支宁可回落到旧令牌（国内版足够）\n   * 也不整体失败。\n   *\n   * 参考：Liki4/qodercli2api、shuishuipingan/qoder2api-hub、\n   * eghrhegpe/dsh-connect-qoder 都走这个 exchange 端点。\n   */\n  sashToken?: string\n  /** 上面那枚令牌的过期毫秒时间戳；0 表示未知。 */\n  sashExpireAtMs?: number\n}\n\n/**\n * cosy 面（chat + models）的公共请求头。\n *\n * 协议版本见 {@link COSY_CLIENT_TYPE} / {@link COSY_VERSION_HEADER}：这两个值\n * 决定上游下发哪套模型目录，改之前先读那段注释（issue #21 的实测表）。\n */\nconst DEFAULT_HEADERS: Record<string, string> = {\n  'cosy-data-policy': 'agree',\n  'content-type': 'application/json',\n  'cosy-clienttype': COSY_CLIENT_TYPE,\n  'login-version': 'v2',\n  'user-agent': 'Go-http-client/2.0',\n  'cosy-scene': 'assistant',\n  'cosy-business-product': 'ide',\n  'cosy-business-type': 'agent',\n}\n\n/**\n * Qoder 上游客户端。每个区域一个实例；会话按需惰性交换与续期。\n */\nexport class QoderUpstreamClient {\n  readonly region: QoderRegionConfig\n  /** 本实例所属区域（`region` 是它的配置表；这里保留区域名本身）。 */\n  private readonly regionKey: QoderRegion\n  private readonly logger: (message: string) => void\n  private readonly installSalt: string | undefined\n  private readonly fetchImpl: typeof fetch\n  /**\n   * 按凭证键控的会话缓存。\n   *\n   * 一个区域实例会同时服务多个账号（账号池批量探测、按账号查额度），\n   * 不同 PAT 的 cosy 会话互不相通，所以会话必须按凭证分开缓存——用单个\n   * 字段会互相覆盖（上一个账号的会话被下一个冲掉）。键是 PAT 本身：\n   * 会话不可再交换，必须绑定到它交换来的那份凭证。\n   */\n  private readonly holders = new Map<string, QoderSessionHolder>()\n  /** 最近使用的主会话（默认解析路径复用它）。 */\n  private currentKey: string | undefined\n\n  constructor(region: QoderRegion, options: QoderUpstreamOptions = {}) {\n    this.region = QODER_REGIONS[region]!\n    this.regionKey = region\n    this.logger = options.logger ?? (() => {})\n    this.installSalt = options.installSalt\n    this.fetchImpl = options.fetch ?? globalThis.fetch\n  }\n\n  private log(message: string): void {\n    this.logger(`dsh-connect-qoder: ${message}`)\n  }\n\n  /** 某一凭证的会话是否已过期（或即将过期）。 */\n  isSessionValid(credential: string, nowMs = Date.now()): boolean {\n    const holder = this.holders.get(credential)\n    if (holder === undefined) return false\n    const remaining = holder.expireAtMs - nowMs\n    // 提前 5 分钟视为过期，给续期留时间。\n    return remaining > 5 * 60_000\n  }\n\n  /** 最近使用的凭证，沿用直觉意义上「当前账号」的引用。 */\n  currentCredential(): string | undefined {\n    return this.holders.has(this.currentKey ?? '') ? this.currentKey : undefined\n  }\n\n  /**\n   * 用 PAT（`pt-...` 或任意凭证）或 refresh token（`drt-...`）交换 jobToken。\n   * 设备指纹以凭证为种子派生（无 uid 可用前），保证稳定。\n   */\n  async exchangeJobToken(credential: string): Promise<QoderJobToken> {\n    const fingerprint = deriveFingerprint('', credential, this.installSalt)\n    const body = jobTokenBody(credential)\n    const date = currentRfc1123Date()\n    const sig = signLegacy(date)\n\n    const headers: Record<string, string> = {\n      'cosy-machinetoken': fingerprint.machineToken,\n      'cosy-machinetype': fingerprint.machineType,\n      'login-version': 'v2',\n      appcode: 'cosy',\n      accept: 'application/json',\n      'accept-encoding': 'identity',\n      'cosy-version': COSY_VERSION_HEADER,\n      'cosy-clienttype': COSY_CLIENT_TYPE,\n      date,\n      signature: sig,\n      'content-type': 'application/json',\n      'cosy-machineid': fingerprint.machineId,\n      'user-agent': 'Go-http-client/2.0',\n    }\n\n    const url = `${this.region.gateway}${this.region.jobTokenPath}`\n    const resp = await this.fetchImpl(url, { method: 'POST', headers, body })\n    const text = await resp.text()\n    if (resp.status !== 200) {\n      throw new QoderUpstreamError(classifyFailure(resp.status, text), `jobToken 交换失败: HTTP ${resp.status} ${truncate(text, 200)}`, resp.status, deepestBusinessCode(text))\n    }\n    let data: Record<string, unknown>\n    try {\n      data = JSON.parse(text) as Record<string, unknown>\n    } catch {\n      throw new QoderUpstreamError('unknown', `jobToken 响应不是 JSON: ${truncate(text, 200)}`, resp.status)\n    }\n    const jobToken: QoderJobToken = {\n      id: String(data.id ?? ''),\n      name: String(data.name ?? ''),\n      expireTime: Number(data.expireTime ?? 0),\n      securityOauthToken: String(data.securityOauthToken ?? ''),\n      refreshToken: String(data.refreshToken ?? ''),\n      userType: String(data.userType ?? 'personal_standard'),\n    }\n    if (!jobToken.id && !jobToken.securityOauthToken) {\n      throw new QoderUpstreamError('auth', `jobToken 交换响应缺少身份字段: ${truncate(text, 200)}`, resp.status)\n    }\n    const identity = { name: jobToken.name, aid: jobToken.id, uid: jobToken.id, yx_uid: '', organization_id: '', organization_name: '', user_type: jobToken.userType, security_oauth_token: jobToken.securityOauthToken, refresh_token: jobToken.refreshToken }\n    const session = newCosySession(identity, fingerprint.machineId, fingerprint.machineToken, fingerprint.machineType)\n    const holder: QoderSessionHolder = {\n      session,\n      fingerprint,\n      jobToken,\n      expireAtMs: jobToken.expireTime > 0 ? jobToken.expireTime : 0,\n    }\n    // sash 那一族令牌顺手换一枚。**必须在这里 await**：它是 sash 面的唯一凭据，\n    // 不等它落地就返回，会让紧接着的第一次积分 / 签到读到空令牌而 401 —— 而那个\n    // 401 与「真被拒」长得一模一样（实测正是如此：第一次 401、第二次 200），\n    // 排查起来极贵。第二次交换多花一次上游往返，换「第一次读积分就是对的」。\n    await this.refreshSashToken(credential, holder)\n    this.holders.set(credential, holder)\n    this.currentKey = credential\n    this.log(`jobToken 已交换: ${jobToken.name} (${jobToken.id})`)\n    return jobToken\n  }\n\n  /**\n   * 换一枚 sash 面专用的令牌（`POST /api/v1/jobToken/exchange`）。\n   *\n   * **不抛**：这一族换不到时 sash 那一支会回落到旧令牌（国内版本来就够用），\n   * 而整条交换失败只该让「积分读不到」，不该让 chat / 对话跟着挂 —— 那是完全\n   * 不同的两条链路。\n   *\n   * body 键是 `personal_token`：实测 `personal_access_token`（eghrhegpe 那个 fork\n   * 用的拼写）在当前上游回 **400 BadRequest**，两个区域都是。\n   */\n  private async refreshSashToken(credential: string, holder: QoderSessionHolder): Promise<void> {\n    const url = `${this.region.openapi}${SASH_TOKEN_PATH}`\n    try {\n      const resp = await this.fetchImpl(url, {\n        method: 'POST',\n        headers: { 'content-type': 'application/json', accept: 'application/json' },\n        body: JSON.stringify({ personal_token: credential }),\n      })\n      const text = await resp.text()\n      if (resp.status !== 200) {\n        this.log(`sash 令牌交换失败（HTTP ${resp.status}），sash 面将回落到旧令牌: ${truncate(text, 120)}`)\n        return\n      }\n      const data = parseJson(text)\n      // 上游在这一点上有过多种拼写（token / job_token / jobToken），全试。\n      const raw = data === undefined ? {} : data as Record<string, unknown>\n      const token = typeof raw['token'] === 'string' && raw['token'] !== ''\n        ? raw['token']\n        : typeof raw['job_token'] === 'string' && raw['job_token'] !== ''\n          ? raw['job_token']\n          : typeof raw['jobToken'] === 'string' && raw['jobToken'] !== '' ? raw['jobToken'] : ''\n      if (token === '') {\n        this.log(`sash 令牌交换响应里没有 token 字段: ${truncate(text, 120)}`)\n        return\n      }\n      holder.sashToken = token\n      // expires_at 是 ISO 字符串（实测 \"2026-10-13T17:36:02Z\"），不是 epoch 毫秒。\n      const expiry = typeof raw['expires_at'] === 'string' ? Date.parse(raw['expires_at']) : Number.NaN\n      holder.sashExpireAtMs = Number.isFinite(expiry) ? expiry : 0\n      this.log(`sash 令牌已交换（有效期至 ${holder.sashExpireAtMs > 0 ? new Date(holder.sashExpireAtMs).toISOString() : '未知'}）`)\n    } catch (error: unknown) {\n      this.log(`sash 令牌交换异常，sash 面将回落到旧令牌: ${String((error as Error)?.message ?? error).slice(0, 120)}`)\n    }\n  }\n\n  /**\n   * 取该会话用于 **sash 面** 的 Authorization 值。\n   *\n   * 新令牌优先（国际版必需）；没有就回落到旧的 `securityOauthToken`（国内版\n   * 两个面都认它，而且它是 chat 在用的那一个 —— 回落不会破坏任何东西）。\n   *\n   * 返回 `''` 表示两族都没有：那一支必须报「读不到」，绝不能带上一个空 bearer\n   * 去换一个 401 回来（那样分不清是没令牌还是令牌被拒）。\n   */\n  private sashBearerOf(holder: QoderSessionHolder): string {\n    if (typeof holder.sashToken === 'string' && holder.sashToken !== '') return holder.sashToken\n    return holder.jobToken.securityOauthToken\n  }\n\n  /**\n   * 确保存在未过期会话。credential 提供 PAT 或 refreshToken（`drt-` 前缀）。\n   * 已有有效会话时直接复用（不重复交换）。\n   */\n  async ensureSession(credential: string): Promise<QoderSessionHolder> {\n    if (this.isSessionValid(credential)) {\n      return this.holders.get(credential)!\n    }\n    await this.exchangeJobToken(credential)\n    return this.holders.get(credential)!\n  }\n\n  /**\n   * 拉取模型目录。响应形状（服务端 snake_case）：\n   * `{\"chat\":[{key, display_name, enable, is_vl, is_default, ...}], ...}`\n   */\n  async fetchModels(credential: string, signal?: AbortSignal): Promise<QoderUpstreamModel[]> {\n    const holder = await this.ensureSession(credential)\n    const url = `${this.region.gateway}${this.region.modelsPath}`\n    const data = await this.bearerGet(holder, url, signal)\n    const chat = Array.isArray(data.chat) ? data.chat : []\n    return chat\n      .map((entry): QoderUpstreamModel | undefined => {\n        if (!entry || typeof entry !== 'object') return undefined\n        const raw = entry as Record<string, unknown>\n        const key = typeof raw.key === 'string' ? raw.key : ''\n        const displayName = typeof raw.display_name === 'string' ? raw.display_name : ''\n        if (!key || !displayName) return undefined\n        return {\n          key,\n          display_name: displayName,\n          enable: raw.enable !== false,\n          is_default: raw.is_default === true,\n          is_vl: raw.is_vl === true,\n          is_reasoning: raw.is_reasoning === true,\n          is_free: raw.is_free === true,\n          price_factor: typeof raw.price_factor === 'number' ? raw.price_factor : undefined,\n          max_input_tokens: typeof raw.max_input_tokens === 'number' ? raw.max_input_tokens : undefined,\n          max_output_tokens: typeof raw.max_output_tokens === 'number' ? raw.max_output_tokens : undefined,\n          thinking_config: typeof raw.thinking_config === 'object' ? raw.thinking_config as Record<string, unknown> : undefined,\n          context_config: typeof raw.context_config === 'object'\n            ? raw.context_config as Record<string, { token_count: number; is_default?: boolean }>\n            : undefined,\n          raw,\n        }\n      })\n      .filter((m): m is QoderUpstreamModel => m !== undefined)\n      // **上游的 `auto` 路由器不是模型，不进名册。**\n      //\n      // 它是该区的默认路由：网关在请求时才决定把它解析成哪一个模型，所以价格、\n      // 上下文与行为都由别人临时决定，插件无法如实描述。真实目录里它正是唯一\n      // 没声明思考档位、却带着 `is_default: true` 的那一行。\n      //\n      // 过滤放在这里（解析层，唯一的写点）而不是各个读点：`discoverModels`、\n      // `refreshRegionCatalog`、CLI 的 `status` 全都经过这一个函数，漏一处就会\n      // 出现「刷新后没了、重启后又回来」这种最难查的不一致。旧存档里的那一行\n      // 另由 `catalog.ts` 的 `withoutRouters` 在读点兜住。\n      .filter(model => !isRouterModelId(model.key))\n  }\n\n  /**\n   * 聊天 SSE 流。onDelta 逐行回调；返回 null 表示正常结束。\n   * 令牌：`credential` 只在会话续期时使用。\n   */\n  async chatStream(\n    credential: string,\n    modelKey: string,\n    messages: Array<Record<string, unknown>>,\n    options: {\n      tools?: unknown[]\n      isReasoning?: boolean\n      /**\n       * 思考强度档位名（`low` / `medium` / `xhigh` …），来自插件设置里为该\n       * 模型保存的值。\n       *\n       * 实测自 Qoder 官方客户端（app.asar.unpacked 的 SDK）：档位**不走**\n       * `model_config`，而是请求体顶层的 `reasoningEffort` 加\n       * `parameters.reasoning_effort`——官方客户端两者同时写\n       * （`{..., reasoningEffort:\"none\", parameters:{...A.parameters,\n       *   reasoning_effort:\"none\"}}`），只写一个有可能被网关忽略。\n       * 缺席时不下发任何档位字段，由上游用模型自己的默认档。\n       */\n      reasoningEffort?: string\n      isVl?: boolean\n      signal?: AbortSignal\n      onDelta: (delta: QoderChatDelta) => void\n      userType?: string\n    },\n  ): Promise<void> {\n    const holder = await this.ensureSession(credential)\n    const template = deepClone(createChatBodyTemplate())\n    applyModelKey(template, modelKey, options.userType ?? holder.jobToken.userType, options.isVl ?? false)\n    if (options.isReasoning) {\n      template.model_config.is_reasoning = true\n      template.chat_context.extra.modelConfig.is_reasoning = true\n    }\n    if (options.reasoningEffort !== undefined && options.reasoningEffort !== '') {\n      // 两个位置都写：官方客户端如此，照抄以避免网关只认其中一个。\n      template.reasoningEffort = options.reasoningEffort\n      const params = (template.parameters ?? {}) as Record<string, unknown>\n      template.parameters = { ...params, reasoning_effort: options.reasoningEffort }\n    }\n    const prompt = extractLatestUserPrompt(messages)\n    const built = buildQoderMessages(messages, prompt, Array.isArray(options.tools) && options.tools.length > 0)\n    template.messages = built as unknown as unknown[]\n    if (options.tools !== undefined) {\n      template.tools = options.tools\n    }\n    template.request_id = randomId()\n    template.chat_record_id = template.request_id\n    template.request_set_id = randomId()\n    template.session_id = randomId()\n    template.business.id = randomId()\n    template.business.name = prompt.slice(0, 30) || 'hi'\n    template.business.begin_at = Date.now()\n\n    const body = JSON.stringify(template)\n    const url = `${this.region.gateway}${this.region.chatPath}`\n    const pathSig = pathSigFrom(url)\n\n    const encoded = cosyEncode(new TextEncoder().encode(body))\n    const date = String(Math.floor(Date.now() / 1000))\n    const payloadB64 = buildPayloadB64(holder.session.info)\n    const sig = signRequest(payloadB64, holder.session.cosyKey, date, encoded, pathSig)\n    const bearer = composeBearer(payloadB64, sig)\n\n    const headers: Record<string, string> = {\n      ...DEFAULT_HEADERS,\n      'cosy-machinetype': holder.session.machineType,\n      'cosy-date': date,\n      'cosy-user': holder.session.identity.uid,\n      'cosy-key': holder.session.cosyKey,\n      'cache-control': 'no-cache',\n      accept: 'text/event-stream',\n      authorization: bearer,\n      'cosy-version': COSY_VERSION_HEADER,\n      'cosy-machineid': holder.session.machineId,\n      'cosy-machinetoken': holder.session.machineToken,\n      'x-model-key': modelKey,\n      'x-model-source': 'system',\n    }\n\n    const resp = await this.fetchImpl(url, {\n      method: 'POST',\n      headers,\n      body: encoded,\n      ...(options.signal === undefined ? {} : { signal: options.signal }),\n    })\n    if (resp.status !== 200) {\n      const errText = await resp.text()\n      // 用 classifyFailure 而不是 classifyHttpStatus：chat 面的「当日用量用尽」\n      // 就是从这里进来的（实测 HTTP 403 + body `{\"code\":\"110\",…}`），只看状态会\n      // 把它判成凭据被拒，进而把好的账号永久踢出池。\n      throw new QoderUpstreamError(\n        classifyFailure(resp.status, errText),\n        `聊天请求失败: HTTP ${resp.status} ${truncate(errText, 300)}`,\n        resp.status,\n        deepestBusinessCode(errText),\n        // 上游申报的重试间隔（issue #24）：`10605 / RESOURCE_LIMIT` 就走这条\n        // 路径进来，以前读到即丢，用户只看到「上游报了个 4xx」。\n        retryAfterMsOf(errText) ?? retryAfterMsOfHeader(resp.headers.get('retry-after')),\n        // issue #26：排队证据（`isQueued`）与重试间隔在同一个信封里，一并带出。\n        queueOf(errText),\n      )\n    }\n    if (!resp.body) {\n      throw new QoderUpstreamError('transient', '聊天响应没有 body')\n    }\n\n    const reader = resp.body.getReader()\n    const decoder = new TextDecoder()\n    let buffer = ''\n    try {\n      for (;;) {\n        const { done, value } = await reader.read()\n        if (done) break\n        buffer += decoder.decode(value, { stream: true })\n        const lines = buffer.split('\\n')\n        buffer = lines.pop() ?? ''\n        for (const line of lines) {\n          const trimmed = line.trim()\n          if (trimmed === '' || !trimmed.startsWith('data:')) continue\n          const payload = trimmed.slice('data:'.length).trim()\n          if (payload === '[DONE]') continue\n          const delta = parseStreamDelta(payload)\n          if (delta !== undefined) options.onDelta(delta)\n        }\n      }\n    } finally {\n      reader.releaseLock()\n    }\n  }\n\n  /**\n   * 查询用量（只读）。`GET {openapi}/sash/api/v2/me/usage`。\n   *\n   * **认证用的是 jobToken 里的 `securityOauthToken`（`jt-…`），不是 PAT，\n   * 也不是 COSY 签名 bearer。** 三者实测（2026-10，CN）：\n   *\n   * | 凭据 | 结果 |\n   * | --- | --- |\n   * | 裸 PAT `pt-…` | 401 `TOKEN_EXPIRE / token is not active` |\n   * | COSY 签名 bearer（chat/models 用的那套） | 401 `TOKEN_INVALID / invalid token` |\n   * | `jt-…`（jobToken 交换产出） | **200，返回完整 qoderUsage** |\n   *\n   * 前两种之所以失败，是因为 `sash` 是**浏览器会话面**的接口：它既不收 PAT，\n   * 也不认 cosy 协议头（缺 Authorization 时它回\n   * `UNAUTHORIZED / missing cookie header`，可见它本来是给 cookie 会话用的）。\n   * 这解释了「令牌明明是好的、聊天也正常，积分却永远拿不到」——以前用错凭据。\n   */\n  async fetchUsage(credential: string, signal?: AbortSignal): Promise<QoderUsage | undefined> {\n    const url = `${this.region.openapi}/sash/api/v2/me/usage`\n    try {\n      const holder = await this.ensureSession(credential)\n      const data = await this.jobTokenGet(holder, url, signal)\n      return parseUsage(data)\n    } catch (error) {\n      // 凭据被上游拒（401/403，实测 Qoder 回 `TOKEN_EXPIRE / token is not\n      // active`）必须**抛出去**，不能和「网络抖了一下」一起降级成 undefined：\n      //  - 卡片需要它来说「积分为什么是空的」，否则用户只看到一片空白；\n      //  - credential-recovery 的 `try { await fetchUsage } catch { usable =\n      //    false }` 靠这个异常判定凭据是否可用——原实现静默返回 undefined，\n      //    await 正常结束，于是**过期凭据被判为可用**。\n      // 其他错误（超时、5xx、网关抖动）仍旧返回 undefined：那是「这次没读到」，\n      // 不是「凭据坏了」，报成凭据被拒会把用户引去换一个没问题的 PAT。\n      if (error instanceof QoderUpstreamError && (error.status === 401 || error.status === 403)) {\n        // 兜底：万一某个区域只认 PAT 直连，再试一次。两条都失败才报凭据被拒。\n        const direct = await this.fetchUsageDirect(url, credential, signal)\n        if (direct !== undefined) return direct\n        throw error\n      }\n      return undefined\n    }\n  }\n\n  /**\n   * `sash` 系列接口的取数：带 `Authorization: Bearer <jobToken.securityOauthToken>`。\n   *\n   * 与 {@link bearerGet} 的区别只有一个——**认证凭据不同**：`sash` 要的是\n   * jobToken 交换产出的 `jt-…`，不是 COSY 签名 bearer（实测后者回\n   * `TOKEN_INVALID / invalid token`），也不是裸 PAT（回 `TOKEN_EXPIRE`）。\n   * 也正因为如此，这里**不**带那套 cosy-* 协议头：它们属于 cosy 协议面。\n   * 但**设备风控三件套属于 sash 面**，按 `requiresDeviceRisk` 附加 —— 见下。\n   */\n  private async jobTokenGet(\n    holder: QoderSessionHolder,\n    url: string,\n    signal?: AbortSignal,\n  ): Promise<Record<string, unknown>> {\n    // sash 面用**专用那族**令牌（国际版必需，见 QoderSessionHolder.sashToken）。\n    const oauthToken = this.sashBearerOf(holder)\n    if (oauthToken === '') {\n      throw new QoderUpstreamError('auth', '两次令牌交换都没有拿到可用令牌，无法查询用量', 401)\n    }\n    // 设备风控头按区域附加：`requiresDeviceRisk` 的语义是「该区域的 sash 请求\n    // 都要带这三件套」，用量查询同属 sash 面，**不能只给签到带**。此前这里只发\n    // accept + authorization，国际版的积分查询因此少了 machine 三件套。\n    const resp = await this.fetchImpl(url, {\n      headers: {\n        accept: 'application/json',\n        authorization: `Bearer ${oauthToken}`,\n        ...(await this.deviceRiskHeaders()),\n      },\n      ...(signal === undefined ? {} : { signal }),\n    })\n    const text = await resp.text()\n    if (resp.status !== 200) {\n      throw new QoderUpstreamError(classifyFailure(resp.status, text), `请求失败: HTTP ${resp.status} ${truncate(text, 200)}`, resp.status, deepestBusinessCode(text))\n    }\n    try {\n      return JSON.parse(text) as Record<string, unknown>\n    } catch {\n      throw new QoderUpstreamError('unknown', `响应不是 JSON: ${truncate(text, 200)}`, resp.status)\n    }\n  }\n\n  /**\n   * 活动列表（`GET /sash/api/v1/me/campaigns?forceRefresh=true`）。\n   *\n   * 协议来自社区参考实现（L0NE-6/Qoder-Daily），已在本机 CN 账号实测通过：\n   * `GET {openapi}/sash/api/v1/me/campaigns?forceRefresh=true`，认证用与用量\n   * 查询同一套 `jt-` 令牌（`jobToken.securityOauthToken`）。\n   *\n   * 注意路径里**没有**「签到」二字——它叫 campaigns（活动/权益）。这也是我早期\n   * 把 `checkinSupported` 写死成 false 的原因：照着 checkin / signin / reward\n   * 猜路径一律 404（实测猜了 13 个），于是误判成「Qoder 没有签到」。\n   *\n   * 旧语义（签到挑用的那一小片）保留在这里：它就是 `fetchCampaignFeed` 的\n   * `campaigns` 投影，免得签到路径与卡片展示路径各写一份解析、日后漂移。\n   */\n  async fetchCampaigns(credential: string, signal?: AbortSignal): Promise<QoderCampaign[]> {\n    return (await this.fetchCampaignFeed(credential, signal)).campaigns\n  }\n\n  /**\n   * 完整活动面（含 `VIEW_DETAILS` banner 与顶层字段），给卡片「活动」区用。\n   *\n   * 实测（CN，2026-10-25）返回的整份形状：\n   * `{ uid, showCampaign, claimable, campaignUrl, campaigns:[{ campaignId, campaignKey,\n   *   actionType, startAt, endAt, claimStatus, benefit:{...},\n   *   placements:[{ type, campaignUrl, content:{ zh:{title,description,detailUrl},\n   *   en:{...} } }] }] }`。标题 / 描述 / 「查看详情」链接都在 `placements[*].content`\n   * 里，按语言各一份；上游只下发它有的语言，所以这里原样收拢，不做翻译。\n   *\n   * 解析对字段缺席是**宽容**的：活动形状常按节日变（1024 集结、首月翻倍这类只在\n   * 当期下发），缺字段就少渲染一点，绝不替上游编标题或链接。\n   */\n  async fetchCampaignFeed(credential: string, signal?: AbortSignal): Promise<QoderCampaignFeed> {\n    const holder = await this.ensureSession(credential)\n    const url = `${this.region.openapi}${this.region.campaignsPath}${CAMPAIGNS_QUERY}`\n    const data = await this.sashRequest('GET', holder, url, undefined, signal)\n    const rows = Array.isArray(data.campaigns)\n      ? data.campaigns\n      : Array.isArray((data.data as Record<string, unknown> | undefined)?.campaigns)\n        ? ((data.data as Record<string, unknown>).campaigns as unknown[])\n        : []\n    return {\n      campaigns: rows\n        .map((entry): QoderCampaign | undefined => projectCampaignEntry(entry))\n        .filter((c): c is QoderCampaign => c !== undefined),\n      ...(typeof data.campaignUrl === 'string' && data.campaignUrl !== ''\n        ? { campaignUrl: data.campaignUrl }\n        : {}),\n      ...(typeof data.showCampaign === 'boolean' ? { showCampaign: data.showCampaign } : {}),\n      ...(typeof data.claimable === 'boolean' ? { claimable: data.claimable } : {}),\n    }\n  }\n\n  /**\n   * 签到：领取今天那一份每日 Credits。\n   *\n   * 一次调用自足——先拉活动列表找出可领的那条，再领取。三种结果分得很清：\n   *   - `claimed`：领到了（带回数额与有效期）；\n   *   - `already-claimed`：今天已经领过（`CLAIMED` / 409 / `ALREADY_CLAIMED` /\n   *     `replayed`），**不是错误**——重复调用是幂等的；\n   *   - `unavailable`：今天上游没下发活动（未开窗 / 已领到活动行消失 / 企业号\n   *     不支持该活动），带上说明。\n   */\n  async claimDailyCredits(credential: string, signal?: AbortSignal): Promise<QoderCheckinOutcome> {\n    const campaigns = await this.fetchCampaigns(credential, signal)\n    const daily = campaigns.find(c => c.actionType === 'CLAIM_BENEFIT')\n    const claimable = campaigns.find(c => c.actionType === 'CLAIM_BENEFIT' && c.claimStatus === 'CLAIMABLE')\n    // 「下一次刷新」来自**这一窗的 `endAt`**（秒），无论这次是领到还是已领过。\n    // 关键：已领过时也带着它 —— 「已领取」这个答案离开「还有多久刷新」是不完整的，\n    // 用户看到「已领取」会以为要等到明天零点，而上游说的是次日 10:00。\n    const nextRefreshAtMs = daily?.endAt === undefined ? undefined : daily.endAt * 1000\n    if (claimable === undefined) {\n      const claimed = daily?.claimStatus === 'CLAIMED'\n      return claimed\n        ? { status: 'already-claimed', ...(nextRefreshAtMs === undefined ? {} : { nextRefreshAtMs }) }\n        : { status: 'unavailable', message: '上游今日没有下发可领取的签到活动' }\n    }\n    const holder = await this.ensureSession(credential)\n    const url = `${this.region.openapi}${this.region.campaignsPath}/${encodeURIComponent(claimable.campaignId)}/claim`\n    try {\n      const data = await this.sashRequest('POST', holder, url, {}, signal)\n      // 上游用 `status` 回报领取结果；`CLAIMED` 才算成功。\n      if (String(data.status ?? '') === 'CLAIMED') {\n        return {\n          status: 'claimed',\n          ...(claimable.amount === undefined ? {} : { amount: claimable.amount }),\n          ...(claimable.validityDays === undefined ? {} : { validityDays: claimable.validityDays }),\n          ...(nextRefreshAtMs === undefined ? {} : { nextRefreshAtMs }),\n        }\n      }\n      return { status: 'unavailable', message: `签到未完成（上游状态 ${String(data.status ?? '未知')}）` }\n    } catch (error) {\n      // 重复领取是幂等的：409 / ALREADY_CLAIMED / replayed 一律当「今天已领」。\n      if (error instanceof QoderUpstreamError && error.status === 409) {\n        return { status: 'already-claimed', ...(nextRefreshAtMs === undefined ? {} : { nextRefreshAtMs }) }\n      }\n      throw error\n    }\n  }\n\n  /**\n   * `sash` 接口的通用请求（活动列表 / 领取共用）。\n   *\n   * 认证与用量查询同一套：`Authorization: Bearer <jobToken.securityOauthToken>`。\n   * 但那两个接口需要 `cosy-clienttype: 10` 与 `user-agent: Qoder`——参考实现\n   * 如此，缺了会被拒；而夹带 cosy 协议头（chat/models 那套）反而不认。\n   *\n   * 这里的 `10` 与 cosy 面的 {@link COSY_CLIENT_TYPE} **恰好同值但不同源**：\n   * 这条是 sash 面自己的客户端标识（`SASH_CLIENT_TYPE`，逐条手写请求头），\n   * 改 cosy 面的协议版本不该顺手动它，反之亦然。两个数字各自独立被测。sash 面\n   * 也**不**发 `cosy-version`：它本来就不带那套协议头。\n   *\n   * **国际版额外需要设备风控头**（`Cosy-MachineToken/Code/Type`，见 device-risk.ts）：\n   * 签到活动只下发给带这些头的请求，缺了就拿不到活动列表。国内版不需要，所以按\n   * region 条件附加 —— 不要无条件发，多余的头在另一侧是噪音。\n   */\n  private async sashRequest(\n    method: 'GET' | 'POST',\n    holder: QoderSessionHolder,\n    url: string,\n    body: unknown,\n    signal?: AbortSignal,\n  ): Promise<Record<string, unknown>> {\n    // 同上：签到也是 sash 面。\n    const oauthToken = this.sashBearerOf(holder)\n    if (oauthToken === '') {\n      throw new QoderUpstreamError('auth', '两次令牌交换都没有拿到可用令牌，无法访问签到接口', 401)\n    }\n    const resp = await this.fetchImpl(url, {\n      method,\n      headers: {\n        authorization: `Bearer ${oauthToken}`,\n        'cosy-clienttype': SASH_CLIENT_TYPE,\n        accept: 'application/json',\n        'accept-language': 'zh-CN',\n        'user-agent': SASH_USER_AGENT,\n        ...(await this.deviceRiskHeaders()),\n        ...(method === 'POST' ? { 'content-type': 'application/json', origin: this.region.openapi } : {}),\n      },\n      ...(method === 'POST' ? { body: JSON.stringify(body ?? {}) } : {}),\n      ...(signal === undefined ? {} : { signal }),\n    })\n    const text = await resp.text()\n    if (resp.status !== 200 && resp.status !== 201) {\n      throw new QoderUpstreamError(classifyFailure(resp.status, text), `请求失败: HTTP ${resp.status} ${truncate(text, 200)}`, resp.status, deepestBusinessCode(text))\n    }\n    try {\n      return JSON.parse(text) as Record<string, unknown>\n    } catch {\n      throw new QoderUpstreamError('unknown', `响应不是 JSON: ${truncate(text, 200)}`, resp.status)\n    }\n  }\n\n  /**\n   * 本区域签到需要的设备风控头。\n   *\n   * 国内版返回空对象（不需要，发了反而是噪音）；国际版读取本机 UMID 组件的\n   * 三件套。读取失败**不**静默降级成「无头请求」——那样只会拿到一个空的活动\n   * 列表，用户看到「今天没有活动」而真实原因是取不到设备身份。所以这里让错误\n   * 抛出去，由调用方带着原因回报。\n   */\n  private async deviceRiskHeaders(): Promise<Record<string, string>> {\n    if (!this.region.requiresDeviceRisk) return {}\n    const risk = await readDeviceRisk(this.regionKey)\n    return {\n      'cosy-machinetoken': risk.machineToken,\n      'cosy-machinecode': risk.machineCode,\n      'cosy-machinetype': risk.machineType,\n    }\n  }\n\n  /**\n   * 直连回退：`Bearer <PAT>` 打同一个端点。返回 undefined 表示这条回退路径\n   * 也没给出 200（端点不接受直连 PAT，或网络失败）——由调用方决定是否把原始\n   * 的凭据被拒错误抛出去。\n   */\n  private async fetchUsageDirect(\n    url: string,\n    credential: string,\n    signal?: AbortSignal,\n  ): Promise<QoderUsage | undefined> {\n    try {\n      // 与 jobTokenGet 同规：该区域要求设备风控时，回退路径也要带上那三件套，\n      // 否则「主路径失败 → 走回退」恰好落在唯一漏发头的那条分支上。\n      const resp = await this.fetchImpl(url, {\n        headers: {\n          authorization: `Bearer ${credential}`,\n          accept: 'application/json',\n          'cosy-clienttype': '10',\n          'user-agent': 'Qoder',\n          ...(await this.deviceRiskHeaders()),\n        },\n        ...(signal === undefined ? {} : { signal }),\n      })\n      if (resp.status === 200) {\n        const data = await resp.json() as Record<string, unknown>\n        return parseUsage(data)\n      }\n      if (resp.status === 401 || resp.status === 403) {\n        // 两条路径都拒绝同一个 PAT：这就是凭据被拒，保留原始错误抛出。\n        return undefined\n      }\n    } catch {\n      // 直连路径失败不代表凭据坏了，交给调用方用原始错误判定。\n      // 注意：本机取不到 UMID 组件时 deviceRiskHeaders() 会在这里抛错，同样\n      // 落进这个分支 —— 结果是「回退没走成」，由 fetchUsage 把原始凭据错误抛给\n      // 上层，用户看到的是带原因的那条，而不是一条凭空消失的用量查询。\n    }\n    return undefined\n  }\n\n  private async bearerGet(holder: QoderSessionHolder, url: string, signal?: AbortSignal): Promise<Record<string, unknown>> {\n    const pathSig = pathSigFrom(url)\n    const payloadB64 = buildPayloadB64(holder.session.info)\n    const date = String(Math.floor(Date.now() / 1000))\n    const sig = signRequest(payloadB64, holder.session.cosyKey, date, '', pathSig)\n    const bearer = composeBearer(payloadB64, sig)\n    const headers: Record<string, string> = {\n      ...DEFAULT_HEADERS,\n      'cosy-machinetype': holder.session.machineType,\n      'cosy-date': date,\n      'cosy-user': holder.session.identity.uid,\n      'cosy-key': holder.session.cosyKey,\n      accept: 'application/json',\n      authorization: bearer,\n      'cosy-version': COSY_VERSION_HEADER,\n      'cosy-machineid': holder.session.machineId,\n      'cosy-machinetoken': holder.session.machineToken,\n    }\n    const resp = await this.fetchImpl(url, {\n      headers,\n      ...(signal === undefined ? {} : { signal }),\n    })\n    const text = await resp.text()\n    if (resp.status !== 200) {\n      throw new QoderUpstreamError(classifyFailure(resp.status, text), `请求失败: HTTP ${resp.status} ${truncate(text, 200)}`, resp.status, deepestBusinessCode(text))\n    }\n    try {\n      return JSON.parse(text) as Record<string, unknown>\n    } catch {\n      throw new QoderUpstreamError('unknown', `响应不是 JSON: ${truncate(text, 200)}`, resp.status)\n    }\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 纯函数（导出供测试）\n// ---------------------------------------------------------------------------\n\n/**\n * 把上游的一条 campaign 投影成 `QoderCampaign`（宽容：缺字段就少渲染，不编造）。\n *\n * `placements` 是数组，每个元素带 `content: { zh?: {…}, en?: {…} }`（POPUP / USAGE\n * 各一份）。同一语言的文案取**第一份非空**：同一活动通常多份完全相同，重复渲染\n * 只会让卡片上出现两行一样的东西。\n */\nexport function projectCampaignEntry(entry: unknown): QoderCampaign | undefined {\n  if (!entry || typeof entry !== 'object') return undefined\n  const raw = entry as Record<string, unknown>\n  const campaignId = typeof raw.campaignId === 'string' ? raw.campaignId : ''\n  if (campaignId === '') return undefined\n  const benefit = (typeof raw.benefit === 'object' && raw.benefit !== null ? raw.benefit : {}) as Record<string, unknown>\n  const validity = (typeof benefit.validity === 'object' && benefit.validity !== null ? benefit.validity : {}) as Record<string, unknown>\n  const placements = Array.isArray(raw.placements) ? (raw.placements as unknown[]) : []\n  let campaignUrl = ''\n  const content: Record<string, QoderCampaignContent> = {}\n  for (const p of placements) {\n    if (!p || typeof p !== 'object') continue\n    const slot = p as Record<string, unknown>\n    if (campaignUrl === '' && typeof slot.campaignUrl === 'string') campaignUrl = slot.campaignUrl\n    const slotContent = slot.content\n    if (!slotContent || typeof slotContent !== 'object') continue\n    for (const [lang, text] of Object.entries(slotContent as Record<string, unknown>)) {\n      if (!text || typeof text !== 'object') continue\n      const t = text as Record<string, unknown>\n      const row: QoderCampaignContent = {\n        ...(typeof t.title === 'string' ? { title: t.title } : {}),\n        ...(typeof t.description === 'string' ? { description: t.description } : {}),\n        ...(typeof t.detailUrl === 'string' ? { detailUrl: t.detailUrl } : {}),\n        ...(typeof t.buttonText === 'string' ? { buttonText: t.buttonText } : {}),\n      }\n      const prior = content[lang]\n      if (prior === undefined || (Object.keys(prior).length === 0 && Object.keys(row).length > 0)) {\n        content[lang] = row\n      }\n    }\n  }\n  return {\n    campaignId,\n    actionType: typeof raw.actionType === 'string' ? raw.actionType : '',\n    claimStatus: typeof raw.claimStatus === 'string' ? raw.claimStatus : '',\n    ...(typeof raw.campaignKey === 'string' && raw.campaignKey !== '' ? { campaignKey: raw.campaignKey } : {}),\n    ...(campaignUrl !== '' ? { campaignUrl } : {}),\n    ...(typeof benefit.amount === 'number' ? { amount: benefit.amount } : {}),\n    // `mode` 缺席时按相对天数处理：这是上游至今给过的唯一口径，也是 activity\n    // 文案「领取后 30 天有效」的说法。但**显式的**其它 mode 一律不采用天数 ——\n    // 见 `QoderCampaign.validityDays` 的注释。\n    ...(typeof validity.days === 'number' && (validity.mode === undefined || validity.mode === 'RELATIVE_DAYS')\n      ? { validityDays: validity.days }\n      : {}),\n    // 活动窗：秒 → 毫秒之外的**原值也留着**，倒计时由 UI 按 region 的时区算。\n    // 这里保留秒，因为 `endAt` 与 `startAt` 同源同单位，混着传才容易错。\n    ...(typeof raw.startAt === 'number' ? { startAt: raw.startAt } : {}),\n    ...(typeof raw.endAt === 'number' ? { endAt: raw.endAt } : {}),\n    ...(Object.keys(content).length > 0 ? { content } : {}),\n  }\n}\n\n/** jobToken 交换请求体。PAT 或 `drt-` refreshToken 二选一。 */\nexport function jobTokenBody(credential: string): string {\n  const isRefresh = credential.startsWith('drt-')\n  const inner = {\n    personalToken: isRefresh ? '' : credential,\n    securityOauthToken: '',\n    refreshToken: isRefresh ? credential : '',\n    needRefresh: isRefresh,\n    authInfo: {},\n  }\n  const outer = { payload: JSON.stringify(inner), encodeVersion: '1' }\n  const plain = JSON.stringify(outer)\n  return cosyEncode(new TextEncoder().encode(plain))\n}\n\nfunction randomId(): string {\n  return crypto.randomUUID()\n}\n\n/**\n * 解析一条 SSE 帧：\n * `data: {\"headers\":{...},\"body\":\"<inner json>\",\"statusCodeValue\":200}`\n * 内层：`{\"choices\":[{\"delta\":{...}}], \"usage\":{...}}` 或业务错误 `{\"code\":\"115\",\"message\":\"...\"}`。\n * 返回 undefined 表示本帧无可消费内容（或 [DONE] 之前的空帧）。\n */\nexport function parseStreamDelta(dataPayload: string): QoderChatDelta | undefined {\n  let wrapper: Record<string, unknown>\n  try {\n    wrapper = JSON.parse(dataPayload) as Record<string, unknown>\n  } catch {\n    return undefined\n  }\n  // 信封层错误：HTTP 200 建流后，上游把 provider 故障包在信封里投递。\n  const scv = wrapper.statusCodeValue\n  if (scv !== undefined && scv !== null && Number(scv) !== 200) {\n    const detail = typeof wrapper.body === 'string' ? wrapper.body : dataPayload.slice(0, 400)\n    // **这条路径就是本轮 bug 的现场**：用户实拍那句「Qoder 拒绝了这个账号的\n    // PAT」，来自这里对 `statusCodeValue: 403` + body `{\"code\":\"110\",…}` 的分类。\n    // 信封里的业务码比信封状态更具体，所以优先按码分（见 classifyFailure）。\n    throw new QoderUpstreamError(\n      classifyFailure(Number(scv), detail),\n      `上游信封错误: HTTP ${scv} ${truncate(detail, 300)}`,\n      Number(scv),\n      deepestBusinessCode(detail),\n      // issue #24 的现场就是这条：`code 10605 / subCode RESOURCE_LIMIT` 的信封\n      // 里带着 `retryAfterSeconds`，此前读到即丢。\n      retryAfterMsOf(detail),\n      // issue #26：同一个信封里还带着 `isQueued` —— 上游明说「在排队、服务\n      // 可用、30 秒后再来」。此前这条被整段丢掉，池子把它报成「连不上上游」。\n      queueOf(detail),\n    )\n  }\n  const innerStr = wrapper.body\n  if (typeof innerStr !== 'string' || innerStr === '') return undefined\n  let inner: Record<string, unknown>\n  try {\n    inner = JSON.parse(innerStr) as Record<string, unknown>\n  } catch {\n    return undefined\n  }\n  // 上游会投递 `body: \"null\"` 的**空帧**（实测 2026-10-29，cn 的 `mmodel`：\n  // 首帧 role-only 之后紧接一帧 `\"null\"`）。`JSON.parse('null')` 合法返回\n  // `null`，于是下一行 `inner.code` 直接 TypeError —— 整个流被这条空帧打断，\n  // 用户看到的是「这个模型坏了」，而模型本身完全正常。空帧就是「本帧无可消费\n  // 内容」，与解析失败同义：返回 undefined，让调用方跳过它。\n  if (inner === null || typeof inner !== 'object') return undefined\n\n  // 业务错误：{\"code\":\"115\",\"message\":\"...\"}\n  if (typeof inner.code === 'string' && inner.code !== '' && inner.code !== '0') {\n    const detail = typeof inner.message === 'string' ? inner.message : JSON.stringify(inner.message ?? '')\n    throw new QoderUpstreamError(\n      classifyBusinessCode(inner.code),\n      `上游业务错误 code=${inner.code}: ${String(inner.message ?? '')}`,\n      0,\n      inner.code,\n      // issue #26：业务码帧里同样可能带着排队信封（`isQueued` + 等待秒数）。\n      retryAfterMsOf(detail),\n      queueOf(detail),\n    )\n  }\n\n  const usageIn = readTokens(inner.usage, 'prompt_tokens')\n  const usageOut = readTokens(inner.usage, 'completion_tokens')\n  // 缓存命中数（issue #4）。取不到时是 `undefined` 而不是 0：上游这一帧没报\n  // 与「命中 0 个」是两件事，抽取层不该替上游下结论。\n  const usageCached = readCachedTokens(inner.usage)\n  const tokens = usageCached === undefined\n    ? { inputTokens: usageIn, outputTokens: usageOut }\n    : { inputTokens: usageIn, outputTokens: usageOut, cachedTokens: usageCached }\n\n  const choices = Array.isArray(inner.choices) ? inner.choices : []\n  for (const ch of choices as Array<Record<string, unknown>>) {\n    const delta = ch.delta as Record<string, unknown> | undefined\n    if (!delta) continue\n    const role = typeof delta.role === 'string' ? delta.role : ''\n    const content = typeof delta.content === 'string' ? delta.content : ''\n    const reasoning = typeof delta.reasoning_content === 'string' ? delta.reasoning_content : ''\n    const toolCalls = Array.isArray(delta.tool_calls) && delta.tool_calls.length > 0 ? delta.tool_calls : undefined\n    if (role !== '' || content !== '' || reasoning !== '' || toolCalls !== undefined) {\n      return { role, content, reasoningContent: reasoning, toolCalls, ...tokens }\n    }\n  }\n  if (usageIn > 0 || usageOut > 0) {\n    return { role: '', content: '', reasoningContent: '', toolCalls: undefined, ...tokens }\n  }\n  return undefined\n}\n\nfunction readTokens(usage: unknown, key: string): number {\n  if (!usage || typeof usage !== 'object') return 0\n  const v = (usage as Record<string, unknown>)[key]\n  return typeof v === 'number' ? v : 0\n}\n\n/**\n * 读缓存命中的输入 token 数（issue #4）。\n *\n * 为什么这里值得一个专门的函数、而不是顺手写进 `readTokens`：**它有三个可能的\n * 位置**，而各家的写法不统一（宿主 `parseChunkUsage` 里列过同一张表）：\n *\n *   1. `prompt_tokens_details.cached_tokens` —— OpenAI / OpenRouter，也是实测\n *      上 Qoder 网关正在用的那个（见 `QoderChatDelta.cachedTokens` 的真实样本）。\n *   2. `prompt_cache_hit_tokens` —— DeepSeek 系，顶层的另一个拼法。\n *   3. `cached_tokens` —— Kimi 文档里放顶层。\n *\n * 取**第一个存在**的那个，不做相加：它们是同一个量的三种写法，不是三个分量。\n *\n * 返回 `undefined` 表示「上游没报」。**不要**把它折成 0：那会让「这一帧没有\n * usage」与「这次一个都没命中」变成同一个数字，而宿主的百分比正是拿它算的\n * ——issue #4 的整个症状就是「0% 不可信」，用一个默认 0 去修它等于把病保留下来。\n *\n * 另一条**不可踩的坑**：`cached_tokens` 是 `prompt_tokens` 的**子集**（实测\n * 2032 / 2038），所以绝不能加进 `prompt_tokens`。宿主侧自己会做\n * `input = prompt_tokens - cacheRead`，两边各按「子集」理解才对得上。\n */\nfunction readCachedTokens(usage: unknown): number | undefined {\n  if (!usage || typeof usage !== 'object') return undefined\n  const record = usage as Record<string, unknown>\n  const details = record['prompt_tokens_details']\n  const fromDetails = details !== null && typeof details === 'object' && !Array.isArray(details)\n    ? readCount((details as Record<string, unknown>)['cached_tokens'])\n    : undefined\n  if (fromDetails !== undefined) return fromDetails\n  const fromHit = readCount(record['prompt_cache_hit_tokens'])\n  if (fromHit !== undefined) return fromHit\n  return readCount(record['cached_tokens'])\n}\n\n/** 有限、非负的数字；其它一律 `undefined`（`NaN` / 负数 / 字符串都不算数）。 */\nfunction readCount(value: unknown): number | undefined {\n  return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : undefined\n}\n\n/** 解析用量响应（兼容 qoderUsage 内层与平铺两种形状）。 */\nexport function parseUsage(data: Record<string, unknown>): QoderUsage | undefined {\n  const qoderUsage = data.qoderUsage as Record<string, unknown> | undefined\n  const source = qoderUsage ?? data\n  const userQuota = readBucket(source.userQuota)\n  const addOn = source.addOnQuota as Record<string, unknown> | undefined\n  const org = source.orgResourcePackage as Record<string, unknown> | undefined\n  const out: QoderUsage = {\n    userType: typeof source.userType === 'string' ? source.userType : undefined,\n    expiresAt: typeof source.expiresAt === 'number' ? source.expiresAt : undefined,\n    upgradeUrl: typeof source.upgradeUrl === 'string' ? source.upgradeUrl : undefined,\n    isQuotaExceeded: source.isQuotaExceeded === true,\n  }\n  if (userQuota) out.userQuota = userQuota\n  if (addOn) {\n    out.addOnQuota = {\n      ...readBucket(addOn),\n      detailUrl: typeof addOn.detailUrl === 'string' ? addOn.detailUrl : undefined,\n    }\n  }\n  if (org) {\n    out.orgResourcePackage = {\n      used: num(org.used), cap: num(org.cap), remaining: num(org.remaining),\n      percentage: num(org.percentage), available: org.available === true,\n    }\n  }\n  return out\n}\n\nfunction readBucket(value: unknown): { total?: number | undefined; used?: number | undefined; remaining?: number | undefined; percentage?: number | undefined } | undefined {\n  if (!value || typeof value !== 'object') return undefined\n  const v = value as Record<string, unknown>\n  return {\n    total: num(v.total), used: num(v.used), remaining: num(v.remaining), percentage: num(v.percentage),\n  }\n}\n\nfunction num(v: unknown): number | undefined {\n  return typeof v === 'number' ? v : undefined\n}\n\n/** HTTP 状态 → 错误分类（内容审核标记优先于状态码，与 Go 版一致）。 */\nexport function classifyHttpStatus(status: number, detail: string): UpstreamErrorKind {\n  // DataInspectionFailed / inappropriate content 等标记即使出现在\n  // 5xx/200 流里也按内容策略拒绝处理（Go 版 errors_test 同判）。\n  if (isContentPolicy(detail)) return 'content-policy'\n  if (status === 401 || status === 403) return 'auth'\n  if (status === 429) return 'rate-limited'\n  if (status === 400) return 'invalid-request'\n  if (status === 418 || status >= 500) return 'transient'\n  return 'unknown'\n}\n\n/**\n * 从上游错误体里取**业务码**（`{\"code\":\"110\",\"message\":\"…\"}`）。\n *\n * 上游在这一点上有过两种写法：字符串 `\"110\"` 与裸数字 `110`，都见过；这里\n * 一律归一成字符串。取不到（不是 JSON、没有 code、code 不是串/数）返回\n * `undefined` —— 调用方据此回落到 HTTP 状态分类，**绝不**把「读不出码」当成\n * 某种结论。\n */\nexport function businessCodeOf(detail: string): string | undefined {\n  const trimmed = detail.trim()\n  if (!trimmed.startsWith('{')) return undefined\n  let parsed: unknown\n  try {\n    parsed = JSON.parse(trimmed)\n  } catch {\n    return undefined\n  }\n  if (typeof parsed !== 'object' || parsed === null) return undefined\n  const raw = (parsed as Record<string, unknown>).code\n  if (typeof raw === 'string' && raw !== '') return raw\n  // 只接受整数码：`code: 1.5` 之类的东西不是上游的错误码，不该被当成认识的码。\n  if (typeof raw === 'number' && Number.isInteger(raw)) return String(raw)\n  return undefined\n}\n\n/**\n * 下钻的最大层数：防自嵌套/循环引用把解析变成死循环。\n *\n * 实测最深的两层就够（issue #6 的真实帧是「外层信封 → 内层业务码」），但这里给\n * 一点余量，因为上游换一次包装就会多一层，而多一层只是多一次 JSON.parse。\n */\nconst MAX_CODE_NESTING = 6\n\n/**\n * 取上游申报的「请等这么久再试」，毫秒（issue #24）。\n *\n * 实测形状（`HTTP 4xx` + `code 10605 / subCode RESOURCE_LIMIT`）：\n *\n * ```json\n * {\"code\":\"10605\",\"message\":\"{\\\"isQueued\\\":false,\\\"modelKey\\\":\\\"…\\\",\n *   \\\"queueCount\\\":0,\\\"queueType\\\":\\\"p2\\\",\\\"retryAfterSeconds\\\":5,\n *   \\\"serviceAvailable\\\":true,\\\"waitTime\\\":0}\",\"subCode\":\"RESOURCE_LIMIT\"}\n * ```\n *\n * 与 {@link deepestBusinessCode} 走同一条路（只沿 `message` 往里剥、有深度上限），\n * 因为这两个值在同一个信封里，分头解析迟早漂移。\n *\n * **只认 JSON 里的数字秒。** 不解析 HTTP `Retry-After` 头：宿主在 pi-ai 路由上\n * 只从文案分类、不读头（见 `llm-pi-ai/src/stream.ts` 的 `classifyPiAiError`），\n * 所以头带了也没人读；而这里读到的值会进文案，是**真的**能影响等待的那条路。\n * 头仍然照发（`Retry-After`），那是给别的消费者看的，不是本插件的判据。\n *\n * 上限 1 小时：超过就当上游没申报。一个离谱的值会让宿主放弃这次重试\n * （`llm-retry` 在 `> maxDelayMs` 时 `next()`），比不报更糟。\n */\nconst MAX_RETRY_AFTER_MS = 3_600_000\n\n/**\n * 解析 HTTP `Retry-After` 头（两种合法形式：秒数 / HTTP-date）。\n *\n * 只作**兜底**：上游的申报值在 body 里（`retryAfterSeconds`），头是次要来源。\n * 判据同 {@link retryAfterMsOf}：正数、且不超过 1 小时。\n */\nexport function retryAfterMsOfHeader(value: string | null | undefined, nowMs = Date.now()): number | undefined {\n  if (typeof value !== 'string' || value.trim() === '') return undefined\n  const text = value.trim()\n  if (/^\\d+$/u.test(text)) {\n    const seconds = Number(text)\n    const ms = Math.round(seconds * 1000)\n    return ms > 0 && ms <= MAX_RETRY_AFTER_MS ? ms : undefined\n  }\n  const at = Date.parse(text)\n  if (!Number.isFinite(at)) return undefined\n  const ms = at - nowMs\n  return ms > 0 && ms <= MAX_RETRY_AFTER_MS ? ms : undefined\n}\n\nexport function retryAfterMsOf(detail: string): number | undefined {\n  for (const record of envelopeRecords(detail)) {\n    // 字段名只认这一个：上游还有 `waitTime`（排队已等时长）与 `queueCount`，\n    // 那些都不是「该等多久」，拿错了会把等待算成 0 或算成别人的排队量。\n    const seconds = record.retryAfterSeconds\n    if (typeof seconds === 'number' && Number.isFinite(seconds) && seconds > 0) {\n      const ms = Math.round(seconds * 1000)\n      return ms <= MAX_RETRY_AFTER_MS ? ms : undefined\n    }\n  }\n  return undefined\n}\n\n/**\n * 沿一条失败信封往里剥，产出每一层的记录对象。\n *\n * **为什么需要它（issue #26）**：上游的信封有两种「往里包」的方式，两种都在\n * 现场出现过：\n *\n * ```json\n * { \"code\": \"403\", \"message\": \"{\\\"code\\\":\\\"10605\\\",\\\"message\\\":\\\"…\\\"}\" }   // 字符串\n * { \"code\": \"403\", \"message\": \"{\\\"code\\\":\\\"10605\\\",\\\"message\\\":{…}}\" }   // 对象\n * ```\n *\n * 第二种里，`message` **不是**字符串而是对象，而此前 `retryAfterMsOf` 与\n * `deepestBusinessCode` 都写着「`message` 是字符串才继续往里走」—— 于是\n * 走到第二层就停下，`retryAfterSeconds` 明明就在那层的 `message` 对象里，\n * 却读不出来。现场后果：上游说「等 30 秒」，插件读成「上游没说」，于是按\n * 30 分钟兜底冷却（差 60 倍）。\n *\n * 这里把「剥信封」收成**一处**实现，两个读者共用，避免两处再次漂移。深度\n * 上限沿用 {@link MAX_CODE_NESTING}。\n */\nfunction envelopeRecords(detail: string): Array<Record<string, unknown>> {\n  const records: Array<Record<string, unknown>> = []\n  let text: unknown = typeof detail === 'string' ? detail.trim() : ''\n  for (let depth = 0; depth < MAX_CODE_NESTING; depth += 1) {\n    let record: Record<string, unknown>\n    if (typeof text === 'string') {\n      if (!text.startsWith('{')) break\n      const parsed = parseJson(text)\n      if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) break\n      record = parsed as Record<string, unknown>\n    } else if (typeof text === 'object' && text !== null && !Array.isArray(text)) {\n      record = text as Record<string, unknown>\n    } else {\n      break\n    }\n    records.push(record)\n    const message = record.message\n    // 两种形态都继续往里走：字符串（要再解一层 JSON）与对象（直接就是下一层）。\n    if (typeof message === 'string') {\n      text = message.trim()\n    } else if (typeof message === 'object' && message !== null && !Array.isArray(message)) {\n      text = message\n    } else {\n      break\n    }\n  }\n  return records\n}\n\n/**\n * 上游的排队状态（issue #26）。\n *\n * 判据是上游**自己说的** `isQueued: true`；`serviceAvailable` 一并带出\n * （issue #29）：`true` 是「服务是好的，只是排在队里」，`false` 是「上游整体\n * 在拒服务」，两者对用户的行动指导完全不同 —— 判断见\n * {@link upstreamUnavailableOf}。返回 undefined 表示上游没提排队 —— 那时\n * 不许把任何失败说成「排队中」。\n *\n * `queueCount` 与 `retryAfterSeconds` 一并带出：前者让用户看到「排在第 1027\n * 位」，后者是「等 30 秒」—— 上游给了就显示，没给就不编。\n */\nexport function queueOf(detail: string): QoderQueueState | undefined {\n  for (const record of envelopeRecords(detail)) {\n    const isQueued = record.isQueued\n    if (typeof isQueued !== 'boolean') continue\n    const count = record.queueCount\n    const queueType = record.queueType\n    const seconds = record.retryAfterSeconds\n    // issue #29：`serviceAvailable` 与 `isQueued` 在同一个信封里，此前读到了\n    // 却不带出来，于是「上游整体不可用」被压成「你的账号在排队」。\n    const serviceAvailable = record.serviceAvailable\n    return {\n      isQueued,\n      ...typeof count === 'number' && Number.isFinite(count) && count >= 0 ? { queueCount: count } : {},\n      ...typeof queueType === 'string' && queueType !== '' ? { queueType } : {},\n      ...typeof seconds === 'number' && Number.isFinite(seconds) && seconds > 0 ? { retryAfterSeconds: seconds } : {},\n      ...typeof serviceAvailable === 'boolean' ? { serviceAvailable } : {},\n    }\n  }\n  return undefined\n}\n\n/**\n * 上游是不是在说「**整体**拒服务」，而不是「你这个账号在排队」（issue #29）。\n *\n * 判据只认上游自己给的字段，且必须是 `isQueued: true` + 显式的\n * `serviceAvailable: false` 两条同时成立：\n *\n * - 只有 `isQueued` 而没有 `serviceAvailable` ⇒ **不是**这个结论（上游没说，\n *   不推断；退回旧的「排队」语义）。\n * - `serviceAvailable: true` ⇒ 服务是好的，就是排队，正常等即可。\n *\n * 为什么要分开：现场证据（issue #29）里 `queueCount: 0` 与\n * `serviceAvailable: false` 同时出现 —— 队列里一个人都没有，是上游整体在拒。\n * 这种形态下换号、换 PAT 都无效，把它记成账号级冷却会误导用户去重配凭据。\n */\nexport function upstreamUnavailableOf(queue: QoderQueueState | undefined): boolean {\n  if (queue === undefined) return false\n  if (queue.isQueued !== true) return false\n  return queue.serviceAvailable === false\n}\n\n/**\n * 取**最深一层认识的**业务码（`{\"code\":\"10605\",\"message\":\"…\"}`）。\n *\n * 为什么不能只看最外层（issue #6）：上游的失败帧常是外层信封继续往里包，实拍帧：\n *\n * ```json\n * { \"code\": 403, \"message\": \"{\\\"code\\\":\\\"10605\\\",\\\"message\\\":\\\"qmodel 排队中，请稍后重试\\\"}\" }\n * ```\n *\n * 外层那个 `403` 是 HTTP 语义的码（`classifyBusinessCode('403')` → `unknown`），\n * 真正的业务码 `10605`（排队）藏在内层 `message` 里。只剥一层 ⇒ 读不到码 ⇒ 回落\n * HTTP 状态 ⇒ `403 → auth → credential-rejected → 永久剔除账号 + 叫用户换 PAT`。\n * 而 `10605`/`10408` 本来就在 `TRANSIENT_CODES` 里 —— 码表没缺，缺的是「读到它」。\n *\n * 三条纪律（都来自现场形态，不是风格偏好）：\n *\n * 1. **只沿 `parsed.message` 往里走。** 改成遍历 `error`/`data`/`result` 之类更宽\n *    的键集合，会把外层信封那个 HTTP 语义的 `code`（或 `code: 0` 之类无关字段）\n *    当成业务码返回 —— 那比现在更糟，因为 `classifyBusinessCode` 一旦命中就可能\n *    盖住真码。\n * 2. **认不出的码要记进 `fallback` 并继续往里找**，不能直接 return。用例\n *    「外层 403 + 内层 10605/402」就靠这条才过：外层认不出、里层才认得出，先\n *    返回外层就还是 `auth`。\n * 3. **认不出就原样回落 `classifyHttpStatus`** —— `TOKEN_EXPIRE` 这类字符串码、\n *    非 JSON body、空 body 的行为与改动前逐字一致（真被拒的那一侧不能被改坏）。\n */\nexport function deepestBusinessCode(detail: string): string | undefined {\n  let fallback: string | undefined\n  // 与 `retryAfterMsOf` 共用同一条剥壳路径（`envelopeRecords`）：issue #26 的\n  // 现场里 `message` 是**对象**的那种信封此前读不到内层业务码，于是 `10605`\n  // 被丢掉、403 回落成 `auth` —— 排队被说成「凭据被拒」。\n  for (const record of envelopeRecords(detail)) {\n    const raw = record.code\n    let code: string | undefined\n    if (typeof raw === 'string' && raw !== '') code = raw\n    // 只接受整数码：`code: 1.5` 之类的东西不是上游的错误码，不该被当成认识的码。\n    else if (typeof raw === 'number' && Number.isInteger(raw)) code = String(raw)\n    if (code !== undefined) {\n      // 认识的码说了算（纪律 2：认不出的不 return，继续往里找）。\n      if (classifyBusinessCode(code) !== 'unknown') return code\n      if (fallback === undefined) fallback = code\n    }\n  }\n  return fallback\n}\n\n/**\n * 一次失败的分类：**业务码优先于 HTTP 状态**，状态只作兜底。\n *\n * 这是本轮的根因所在（用户实拍：国际版「Qoder 拒绝了这个账号的 PAT」）。实测\n * 上游对**当日用量用尽**回的是\n *\n * ```\n * HTTP 403 {\"code\":\"110\",\"message\":\"Billing daily count exceeded\"}\n * ```\n *\n * 而旧实现只看状态：`403 → auth → credential-rejected → 「请添加新 PAT」`。\n * 那句话不只是文案难听 —— `credential-rejected` 在账号池里是**无条件永久排除**\n * （`exclusionOf` 连冷却期都不看，理由写得很对：令牌被拒，等也没用）。于是\n * 一个只是今天用满、明天自动恢复的账号被踢出池且**不会自愈**，同时被要求去做\n * 一件根本无效的事（换 PAT）。\n *\n * 官方码表（docs.qoder.com/zh/cli/sdk/errors）里 `105` 才是「登录态或 Access\n * Token 已过期」；`110`/`113`/`115`–`119`/`122` 全是**用量与配额**族。也就是说\n * 「403 就是凭据坏了」这个推断在协议层面根本不成立。\n *\n * 认识的码说了算；不认识的（如 `TOKEN_EXPIRE` 这类字符串码）回落状态分类，\n * 行为与改动前一致。\n *\n * 取码用 {@link deepestBusinessCode} 而不是 {@link businessCodeOf}：业务码可能\n * 藏在第二/三层包装里（issue #6 的实拍帧），只剥一层就会把「排队」当成\n * 「凭据被拒」，进而永久剔除一个其实几分钟就自愈的账号。\n */\nexport function classifyFailure(status: number, detail: string): UpstreamErrorKind {\n  const code = deepestBusinessCode(detail)\n  if (code !== undefined) {\n    const byCode = classifyBusinessCode(code)\n    if (byCode !== 'unknown') return byCode\n  }\n  return classifyHttpStatus(status, detail)\n}\n\n/** 业务 code → 错误分类（官方码表，见 {@link classifyFailure}）。 */\nexport function classifyBusinessCode(code: string): UpstreamErrorKind {\n  if (code === '105') return 'auth' // 登录态或 Access Token 已过期\n  // 用量与配额族：等周期重置或补额度，**不是**凭据问题。\n  // 402 / 6004 是 Go 参考实现与本项目早期实测带回来的，保留。\n  if (QUOTA_CODES.has(code)) return 'quota-exhausted'\n  if (code === '406') return 'content-policy' // 敏感内容或模型拒绝\n  // 请求本身无法满足：改输入或改配置，原地重试无意义。\n  if (REQUEST_CODES.has(code)) return 'invalid-request'\n  // 500 请求或网络失败 / 10408 超时 / 10500 模型服务内部错误 / 10605 排队。\n  if (TRANSIENT_CODES.has(code)) return 'transient'\n  return 'unknown'\n}\n\nconst QUOTA_CODES: ReadonlySet<string> = new Set([\n  '110', // 达到当日用量限制（本轮实测到的那一个）\n  '113', // 用量配额耗尽\n  '115', // 达到免费用户配额\n  '116', // 团队管理员 Credits 耗尽\n  '117', // 团队成员 Credits 耗尽\n  '118', // 个人 Credits 耗尽\n  '119', // 所选模型的免费额度已用完\n  '122', // Billing Group 的 Credits 达到上限\n  '402',\n  '6004',\n])\n\n/** 416 范围/结构无法满足 · 430 能力不支持 · 80411 输入过长 · 80412 媒体过多。 */\nconst REQUEST_CODES: ReadonlySet<string> = new Set(['416', '430', '80411', '80412'])\n\nconst TRANSIENT_CODES: ReadonlySet<string> = new Set(['500', '10408', '10500', '10605'])\n\nconst CONTENT_POLICY_MARKERS = [\n  'DataInspectionFailed',\n  'inappropriate content',\n  'input text data may contain',\n  'ContentFilter',\n  'SensitiveContent',\n]\n\nexport function isContentPolicy(detail: string): boolean {\n  return CONTENT_POLICY_MARKERS.some(marker => detail.includes(marker))\n}\n\n/** Parse JSON, or undefined when the body is not JSON at all. Never throws. */\nfunction parseJson(text: string): unknown {\n  try {\n    return JSON.parse(text) as unknown\n  } catch {\n    return undefined\n  }\n}\n\nfunction truncate(text: string, max: number): string {\n  return text.length <= max ? text : `${text.slice(0, max)}…`\n}\n"
