      "path": "src/web-status.ts",
      "content": "/**\n * Host 端浏览器路由：用量 / 账号积分 / 目录刷新 / 账号增删 / 探针 / 账号池 /\n * 传输 / __save 设置回退。\n *\n * 形态沿用 dsh-connect-workbuddy（MIT）的 `web-status.ts`：`ctx.webServer\n * .register({kind:'exact', path, handler})`，loopback Origin 校验 + 超长实体上限，\n * 每个（通常每区域）读写路由先做方法/来源/区域三查再干活。浏览器设置镜像只读；\n * 写入要么走宿主 settings 服务，要么走本文件的 `__save` 回退。\n *\n * 改动（按 Qoder 上游）：\n *   - **有** daily check-in（CN）：`pool` 的 checkin 动作拉活动列表并领取每日\n *     Credits（`sash/api/v1/me/campaigns`）。早先此处写着「没有 daily check-in」\n *     并回报 `checkinSupported: false` —— 那是没实测就下的结论；真实路径叫\n *     `campaigns`，名字里没有「签到」二字，所以照着 checkin/signin 猜必然 404；\n *   - 没有扫码 OAuth：账号增删走 `accounts` 路由的 add（PAT 粘贴，JobToken 交换\n *     验证并取显示名）/ remove（删 vault 条目）；\n *   - 没有桌面临终诊断 / markup 恢复：无 `diagnostics:write`；\n *   - 探针按**具体账号**寻址（池批量指定者或当前选择者），不是「当前目录随便\n *     哪个账号」。\n *\n * @module dsh-connect-qoder/web-status\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-host-webserver'\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport {\n  QODER_ACCOUNT_CREDITS_PATH,\n  QODER_ACCOUNTS_PATH,\n  QODER_ACCOUNTS_REFRESH_PATH,\n  QODER_CAMPAIGNS_PATH,\n  QODER_MODELS_REFRESH_PATH,\n  QODER_POOL_PATH,\n  QODER_PROBE_PATH,\n  QODER_SAVE_PATH,\n  QODER_TRANSFER_PATH,\n  QODER_USAGE_PATH,\n  accountActionOf,\n  fastDetailOf,\n  knownQoderRegionOfDomain,\n  poolAccountIdOf,\n  poolActionOf,\n  regionEnabledOf,\n  regionCreditsShownOf,\n  regionOfStatusUrl,\n  transferActionOf,\n  type QoderWebRegion,\n  type QoderCreditPosition,\n  type QoderPollMinutes,\n  type QoderWebQuotaExhaustion,\n  type QoderWebUsage,\n  type QoderWebAccount,\n  type QoderWebAccountCredit,\n  type QoderWebCredits,\n  type QoderWebModel,\n  type QoderWebPool,\n  type QoderWebPoolAccount,\n  type QoderWebPoolBatch,\n  type QoderWebPoolCheckinRow,\n  type QoderWebPoolExclusion,\n  type QoderWebPoolTestRow,\n  type QoderWebProbeResult,\n  type QoderWebRecovery,\n  type QoderTransferRecord,\n} from './status-paths.ts'\nimport type { QoderCampaignFeed, QoderRegion } from './upstream.ts'\nimport type { QoderModelInfo } from './catalog.ts'\nimport { resolvePoolTarget, poolModelOf, exclusionOf, rankPool } from './account-pool.ts'\nimport type { QoderPoolCredits, QoderPoolModel, QoderPoolProbe } from './account-pool.ts'\nimport type { QoderStoredAccount } from './accounts.ts'\nimport { isQoderAccountId } from './credentials.ts'\n\n// ---------------------------------------------------------------------------\n// 构件类型（Host 端注入给路由层）\n// ---------------------------------------------------------------------------\n\n/** One region's account + credential read/write surface. */\nexport interface QoderAccountDeps {\n  /** All accounts (settings + env + vault) as display entries. */\n  accounts(sources: { settingsPat?: string | undefined, envPat?: string | undefined }): Promise<QoderAccountEntryLike[]>\n  /** The PAT for one account id, without changing selection. */\n  credentialFor(accountId: string, sources: { settingsPat?: string | undefined, envPat?: string | undefined }): Promise<{ pat: string, accountName: string, source: 'settings' | 'env' | 'vault' } | undefined>\n  /** Resolve the serving credential for the region's selection. */\n  resolve(sources: { settingsPat?: string | undefined, envPat?: string | undefined }, selectedId: string | undefined): Promise<{ id: string, pat: string, accountName: string, source: 'settings' | 'env' | 'vault' } | undefined>\n  /** Add (or refresh) one vault entry; `name` from a validated JobToken. */\n  add(pat: string, name: string): Promise<QoderStoredAccount>\n  /**\n   * The vault entries only — NOT settings/env PATs.\n   *\n   * Deleting needs this distinction: a settings or env PAT is owned by whoever set\n   * it (outside this plugin), so removing a vault entry cannot delete it. Asking\n   * \"is this id one we store?\" is what lets the delete route refuse honestly\n   * instead of reporting a removal that changed nothing.\n   */\n  vaultAccounts(): Promise<QoderStoredAccount[]>\n  /** Remove one vault entry. */\n  remove(accountId: string): Promise<boolean>\n  /** Backfill a display name learned from a JobToken exchange. */\n  rename(accountId: string, name: string): Promise<void>\n}\n\nexport interface QoderAccountEntryLike {\n  id: string\n  accountName: string\n  source: 'settings' | 'env' | 'vault'\n}\n\n/** What the account route needs to validate an added PAT. */\nexport interface QoderAccountValidationDeps {\n  /** Region-gateway JobToken exchange; resolves the display name, throws on refusal. */\n  validateForRegion(region: QoderRegion, pat: string): Promise<{ name: string }>\n}\n\n/** What the pool route needs from the Host. Everything region-scoped. */\nexport interface QoderPoolDeps {\n  preferences(region: QoderRegion): {\n    enabled: boolean\n    targetModelId: string\n    probeInputTokens?: number\n    memberAccountIds: readonly string[]\n    /** 用户手动排定的优先级；空 = 完全由积分策略决定。 */\n    orderAccountIds?: readonly string[]\n  }\n  // **这里刻意没有 `catalog`。**（issue #33）\n  //\n  // 它曾经存在，而且指向 `stacks[region].catalog.current()` —— 被 `deriveCatalog`\n  // 按「已勾选模型」裁剪过的运行时目录。池视图读的是 `deps.catalogs`（卡片那份\n  // 完整目录），测试路由读的是它，于是两处必然分叉：目标模型只要不在\n  // `enabledModelKeys` 里（手选了一个没勾的模型，或「自动」档唯一的免费模型没被\n  // 勾），测试就永远解不出目标 —— 卡片写着「测试用模型 X」，点下去是 `rows: []`。\n  //\n  // 修法不是「把两份对齐」，是**只留一份**：目标解析一律读 `deps.catalogs`。\n  // 这里少一个字段，那个分叉在类型层面就不可能被接回来。\n  /** The measured probes currently in the runtime store. */\n  poolProbes(region: QoderRegion): Record<string, QoderPoolProbe>\n  /**\n   * 池成员的最新积分读数（成员 id → 余额），供成员表的积分列使用。\n   * workbuddy 同规：这一列由卡片路由付费（每成员一次 usage 读数），结果同时\n   * 写入宿主侧快照供请求路径的排名使用；非成员不读，显示「—」。\n   */\n  memberCredits?(region: QoderRegion, accountIds: readonly string[]): Promise<ReadonlyMap<string, QoderPoolCredits>>\n  /**\n   * The member credit readings the Host ALREADY has, synchronously — the\n   * first-paint source (issue #77 的 Qoder 版).\n   *\n   * `memberCredits` above is the honest-but-expensive version: one upstream\n   * usage read per member, awaited before the document returns. On a cold\n   * process (or against a slow/rate-limited upstream) that is exactly what made\n   * the settings page sit on a blank account list for tens of seconds. This dep\n   * answers the same shape from the last snapshot in memory and performs NO\n   * upstream read at all, so a first-paint document can never be held by it.\n   *\n   * `undefined` means \"nothing measured yet\" — the pool table then renders `—`\n   * for every balance, which is honest (never measured) rather than wrong.\n   *\n   * A Host built without this dep omits the pool block from a first-paint\n   * document instead of paying for `memberCredits`; see `buildWebUsage`.\n   */\n  cachedMemberCredits?(region: QoderRegion, accountIds: readonly string[]): ReadonlyMap<string, QoderPoolCredits> | undefined\n  /** Resolve one account's PAT WITHOUT changing selection. */\n  credentialFor(region: QoderRegion, accountId: string): Promise<{ pat: string, accountName: string } | undefined>\n  /** Probe one model through one specific PAT. */\n  probeOne(region: QoderRegion, credit: { pat: string, accountName: string }, modelId: string): Promise<QoderWebProbeResult>\n  /**\n   * Issue a `test` batch for the region's members, or for ONE account when\n   * `onlyAccountId` is given.\n   *\n   * The card's row-level \"测试\" button must touch only its own row: a batch\n   * there would re-probe every member (a real request and ~25k input tokens\n   * each) for a control that appears to act on one line.\n   */\n  test(region: QoderRegion, onlyAccountId?: string): Promise<QoderWebPoolTestRow[]>\n  /**\n   * 该区域是否提供每日签到。两个区域都为 true（国际版需要本机 UMID 组件产出的\n   * 设备风控头，取不到时签到如实报错）。路由据此在**到达上游之前**拒绝 checkin 动作。\n   */\n  checkinSupported(region: QoderRegion): boolean\n  /** Issue a `checkin` batch for the region's members (每个成员各领一次). */\n  checkin?(region: QoderRegion): Promise<QoderWebPoolCheckinRow[]>\n  /**\n   * 今日签到状态快照（成员 id → 是否已领）。由签到批次回写、成员表读取。\n   * 缺席的成员表示**还没读过**（UI 说「未知」），不是「未签到」。\n   *\n   * @deprecated 改用 {@link checkinSnapshot}：这个布尔表装不下「下一窗什么时候\n   * 刷新」—— 而那正是「已领取」这句话必须带的另一半（上游 `endAt`）。\n   */\n  checkinState?(region: QoderRegion): Readonly<Record<string, boolean>>\n  /**\n   * 今日签到快照：每个成员「是否已领」**与**「下一窗何时刷新」（epoch 毫秒，\n   * 来自上游活动行的 `endAt`）。\n   *\n   * 两个字段同源：都只有真的打过上游才存在。`refreshAtMs` 缺席时 UI 只说\n   * 「已领取」，**绝不**编一个本地猜测的倒计时。\n   */\n  checkinSnapshot?(region: QoderRegion): Readonly<Record<string, { claimed: boolean, refreshAtMs?: number }>>\n  /**\n   * 正在飞的批量动作（签到或测试）已经处理完的那几行，供卡片的 `action=progress`\n   * 轮询逐条写活动日志。\n   *\n   * 只读宿主内存、不碰上游：每处理完一个账号追加一行（带完成时刻），批次结束\n   * 即清空（响应里本来就有完整结果，这个槽位只服务「在飞期间」）。两个批量动作\n   * 共用一个锁，所以每个区域只需要一个槽位。\n   */\n  batchProgress?(region: QoderRegion): QoderWebPoolBatch | undefined\n  /** Persist the batch's measurements back to the runtime store. */\n  applyProbes(region: QoderRegion, probes: Record<string, QoderPoolProbe>): Promise<void>\n  /** Drop one account's membership from the prefs. */\n  updateMembership(region: QoderRegion, memberAccountIds: readonly string[], enabled?: boolean): void\n}\n\n/**\n * What the transfer route needs from the Host.\n *\n * `exportAccounts` must return records in the **transfer-file shape**\n * (`access_token` / `uid` / `nickname` / `domain`) — NOT the vault's internal\n * shape. The exported document gets re-imported through `importAccounts`, whose\n * region gate recognises a record only by its `domain`, so exporting the vault's\n * raw fields made every exported record unimportable (0 imported, all skipped).\n */\nexport interface QoderTransferDeps {\n  exportAccounts(region: QoderRegion): Promise<{ accounts: QoderTransferRecord[] }>\n  previewImport(region: QoderRegion, text: string): Promise<{ accounts: readonly { index: number, uid: string, nickname: string, email: string, hasToken: boolean }[], total: number }>\n  importAccounts(region: QoderRegion, text: string, indexes: readonly number[]): Promise<{ imported: number, skipped: number }>\n}\n\n/** A settings write surface for the __save fallback. */\nexport interface QoderSettingsDeps {\n  describe(): Array<{ ns: string, value: unknown }>\n  set(field: string, value: unknown): Promise<void>\n}\n\nexport interface QoderWebRouteDeps {\n  regionEnabled(region: QoderRegion): boolean\n  regionCreditsShown(region: QoderRegion): boolean\n  /**\n   * Whether this region's campaign feed (活动) is shown.\n   *\n   * Optional and absent reads as SHOWN — the feed existed before this switch,\n   * so a Host that predates it must render exactly as before.\n   */\n  regionCampaignsShown?(region: QoderRegion): boolean\n  /**\n   * WHERE this region's credit readout sits.\n   *\n   * Optional, and absent reads as `composer` —— 该设置存在之前唯一的席位，\n   * 所以早于本设置的宿主渲染得与从前完全一样。\n   */\n  creditPosition?(region: QoderRegion): QoderCreditPosition\n  /**\n   * Whether the OPTIONAL DSH sidebar panel is switched on (PR #188 同款).\n   *\n   * GLOBAL, so it takes no region — one nav row and one page serve both\n   * regions, and the same value therefore rides on every region's answer.\n   *\n   * Optional, and absent reads as OFF: the row claims a `sidebar.panellist`\n   * seat every bundle shares, so a Host that cannot answer must not be read as\n   * consent.\n   */\n  sidebarPanelEnabled?(): boolean\n  /** Global upstream-refresh interval in minutes; absent means the default 5. */\n  pollMinutes?(): QoderPollMinutes\n  /**\n   * The last upstream-asserted quota exhaustion on this region's chat path,\n   * or undefined when upstream never said so (see `QoderWebQuotaExhaustion`).\n   *\n   * Optional and absent reads as \"nothing to carry\" —— the doc field is\n   * omitted, not `null`.\n   */\n  lastQuotaExhaustion?(region: QoderRegion): QoderWebQuotaExhaustion | undefined\n  regionUsable?(region: QoderRegion, usable: boolean): void\n  store(region: QoderRegion): QoderAccountDeps\n  credentialSources(region: QoderRegion): { settingsPat?: string | undefined, envPat?: string | undefined }\n  selectedAccountId(region: QoderRegion): string | undefined\n  /**\n   * Drop the region's saved `accountId` selection (back to \"automatic\").\n   *\n   * Called after the account it pointed at is deleted: the choice is gone with its\n   * credential, and leaving it behind makes the card keep reporting\n   * `selectionLost` — \"the account you selected no longer exists\" — for a region\n   * that is in fact fine. Optional so an older Host without it still works; the\n   * stale selection then resolves to automatic on its own.\n   */\n  clearSelection?(region: QoderRegion): Promise<void> | void\n  /** The per-region RUNTIME catalog. */\n  catalogs: Record<QoderRegion, { current(): QoderModelInfo[] }>\n  /** Persisted context budgets by model key, one region. */\n  contextBudgets(region: QoderRegion): Record<string, number>\n  /** Persisted thinking strength per model key (`low` / `medium` / `xhigh` …). */\n  thinkingEfforts(region: QoderRegion): Record<string, string>\n  offModelKeys(region: QoderRegion): readonly string[]\n  /** Model keys the user explicitly enabled image input for (independent set). */\n  imageModelKeys(region: QoderRegion): readonly string[]\n  /**\n   * Whether the user ever saved an image selection (independent of its content).\n   *\n   * Optional so an older Host still wires up: without it the card falls back to\n   * `imageModelKeys.length > 0`, which is the pre-#22 behaviour.\n   */\n  imageSelectionSaved?(region: QoderRegion): boolean\n  enabledModelKeys(region: QoderRegion): readonly string[]\n  discoverModels?(region: QoderRegion, signal?: AbortSignal): Promise<QoderModelInfo[]>\n  /**\n   * Full refresh behind the card's refresh button: re-reads the upstream\n   * catalog AND installs it into the runtime catalog (plus a usage refresh),\n   * then returns the fresh list. Preferred over {@link discoverModels} for the\n   * refresh route; discoverModels alone never mutates runtime state, so a route\n   * wired to it answers new data while the card's next poll still sees the old.\n   */\n  refreshModels?(region: QoderRegion): Promise<QoderModelInfo[]>\n  /** A cached usage read for one region. */\n  usage(region: QoderRegion): {\n    usage?: { credits: QoderWebCredits, atMs: number }\n    error?: string\n    /** The last RE-READ failed but the snapshot below is intact (see refreshError). */\n    staleError?: string\n  } | undefined\n  /**\n   * Re-read this region's credits from upstream **into the cache** the `usage`\n   * dep reads from, awaited before the document is assembled.\n   *\n   * 对齐 workbuddy：那边的 usage 路由每次请求都现场并发拉积分\n   * （`web-status.ts` 的 `Promise.allSettled` + `toCredits`）。Qoder 移植时把这一处\n   * 换成了纯缓存读，而缓存只在「启动 / 配置写入 / 刷新模型 / 签到」四个时机被写，\n   * 于是聊天扣费后触发器上的数字**永远不会自己变新**，而面板表格（每账号现场读）\n   * 是新的 —— 同一个账号在同一个面板里显示两个数（用户实拍 800 vs 738）。\n   *\n   * Optional: a host that does not wire this dep falls back to the old pure\n   * cache read and the document still builds.\n   */\n  refreshUsage?(region: QoderRegion): Promise<void>\n  /** Probe one model through the region's selected credential. */\n  probeModel?(region: QoderRegion, modelId: string, signal?: AbortSignal): Promise<QoderWebProbeResult>\n  /** Fetch one region's per-account credit balances fresh (composer panel). */\n  accountCredits?(region: QoderRegion, signal?: AbortSignal): Promise<QoderWebAccountCredit[]>\n  /**\n   * One region's campaign feed (daily check-in + every `VIEW_DETAILS` banner).\n   *\n   * The card's activity area reads this while the panel is open. Optional so a\n   * host that does not wire it simply shows no activity section — the card is\n   * still a complete card, just without the upstream's current promotions.\n   */\n  campaigns?(region: QoderRegion, signal?: AbortSignal): Promise<QoderCampaignFeed>\n  /**\n   * What to tell the user after the upstream refused this region's credential.\n   *\n   * Probes the OTHER stored accounts and promises a switch only to one that\n   * actually answered — the alternative (guessing from the account count) says\n   * \"try switching\" about an account that may be just as expired.\n   */\n  credentialRecovery?(region: QoderRegion, rejectedAccountId: string): Promise<QoderWebRecovery>\n  pool?: QoderPoolDeps\n  transfer?: QoderTransferDeps\n  accountValidation?: QoderAccountValidationDeps\n  settings: QoderSettingsDeps\n  logger: (message: string) => void\n}\n\n// ---------------------------------------------------------------------------\n// 小工具\n// ---------------------------------------------------------------------------\n\nfunction json(res: ServerResponse, status: number, body: unknown): void {\n  if (res.writableEnded || res.destroyed) return\n  const text = JSON.stringify(body)\n  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' })\n  res.end(text)\n}\n\nfunction safeMessage(error: unknown): string {\n  return error instanceof Error ? error.message : String(error)\n}\n\nfunction loopbackOrigin(req: IncomingMessage): boolean {\n  const origin = req.headers.origin\n  if (origin === undefined) return true\n  return /^http:\\/\\/127\\.0\\.0\\.1:\\d+$/.test(origin) || /^http:\\/\\/localhost:\\d+$/.test(origin)\n}\n\nasync function readBody(req: IncomingMessage): Promise<string> {\n  return new Promise((resolve, reject) => {\n    let total = 0\n    const chunks: Buffer[] = []\n    req.on('data', (chunk: Buffer) => {\n      total += chunk.length\n      // Body cap: transfer files can be large but are bounded; 1 MiB is enough\n      // for a realistic account list.\n      if (total > 1024 * 1024) {\n        reject(new Error('request body too large'))\n        req.destroy()\n        return\n      }\n      chunks.push(chunk)\n    })\n    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))\n    req.on('error', reject)\n  })\n}\n\n/** Narrow the region on a route URL; 400 when absent/unknown. */\nfunction requiredRegion(res: ServerResponse, url: string): QoderRegion | undefined {\n  const region = regionOfStatusUrl(url)\n  if (region === undefined) {\n    json(res, 400, { error: 'unknown region' })\n    return undefined\n  }\n  return region\n}\n\n/** Project one model into the card's web row. */\nfunction webModelOf(m: QoderModelInfo): QoderWebModel {\n  return {\n    key: m.key,\n    name: m.displayName,\n    contextWindow: m.contextWindow,\n    nativeContextWindow: m.contextWindow,\n    maxTokens: m.maxOutputTokens,\n    // 倍率总是带上——包括恰好 1。workbuddy 的卡片行对「已声明的倍率」一律\n    // 渲染 `(1.00x)`，Qoder 自家菜单也写 `· x1.0`；把 1 当「无」丢掉，卡片上\n    // 就只剩没倍率的裸名字，与其他模型视觉不一致。\n    creditMultiplier: m.priceFactor,\n    ...(m.supportsImages === true ? { supportsImages: true } : {}),\n    supportsThinking: m.supportsThinking,\n    ...(m.canDisableThinking === true ? { canDisableThinking: true } : {}),\n    // 思考强度档位：上游 `thinking_config.enabled.efforts` 的键（已按强度升序）。\n    // 缺失时不写字段，卡片据此不渲染这一项——而不是渲染一个空标签。\n    ...(m.thinkingEfforts === undefined ? {} : { thinkingEfforts: m.thinkingEfforts }),\n    ...(m.defaultThinkingEffort === undefined ? {} : { defaultThinkingEffort: m.defaultThinkingEffort }),\n    ...(m.isDefault === true ? { isDefault: true } : {}),\n    ...(m.isFree === true ? { isFree: true } : {}),\n    ...(m.isNew === true ? { isNew: true } : {}),\n    ...(m.contextTiers === undefined ? {} : { contextTiers: m.contextTiers }),\n    // 活动规则原样交给卡片：判「此刻成不成立」是渲染时刻的事（窗口按上游时区\n    // 算），这里一旦挑定就会在窗口结束后继续挂着。\n    ...(m.promotion === undefined ? {} : { promotion: m.promotion }),\n  }\n}\n\n/** Redact upstream failure text for safe display/storage. */\nexport function redactQoderText(text: string): string {\n  // eslint-disable-next-line no-useless-escape\n  return text\n    .replace(/\\beyJ[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\b/gu, '[redacted token]')\n    .replace(/\\b(pt-|eyJ)[A-Za-z0-9_\\-]{6,}\\b/giu, '[redacted credential]')\n    .slice(0, 300)\n}\n\n/** Project one model into the pool's target picker shape. */\nfunction poolModelsOfCatalog(catalog: readonly QoderModelInfo[]): QoderPoolModel[] {\n  return catalog.map(model => poolModelOf(model))\n}\n\n// ---------------------------------------------------------------------------\n// 组装\n// ---------------------------------------------------------------------------\n\nexport interface QoderWebStatusMounted {\n  status(region: QoderRegion): Promise<QoderWebUsage>\n}\n\n/**\n * Mount the web routes for dsh-connect-qoder. Returns the status builder so\n * the Host can also answer from a cache (the route itself re-derives it).\n */\nexport function registerQoderWebRoutes(ctx: Context, deps: QoderWebRouteDeps): QoderWebStatusMounted {\n  const disposers: Array<() => void> = []\n  const regionOf = requiredRegion\n\n  const mount = (path: string, handler: (req: IncomingMessage, res: ServerResponse) => Promise<void>) => {\n    try {\n      const dispose = ctx.webServer.register({ kind: 'exact', path, handler })\n      if (typeof dispose === 'function') disposers.push(dispose)\n    } catch {\n      // A route already registered (e.g. re-inject) is fine; watch for it at shutdown.\n    }\n  }\n\n  // -------------------------------------------------------------------------\n  // GET /usage — per-region snapshot (the card's main document).\n  // -------------------------------------------------------------------------\n  mount(QODER_USAGE_PATH, async (req, res) => {\n    if (req.method !== 'GET') return json(res, 405, { error: 'method not allowed' })\n    const region = regionOfStatusUrl(req.url ?? '')\n    if (region === undefined) return json(res, 400, { error: 'unknown region' })\n    // `&detail=fast` 只要首屏文档（只用本地已有状态）；缺席或任何别的值都是\n    // 完整文档 —— 拼错一个参数只会慢，不会得到一份更空的文档。\n    const detail: QoderStatusDetail = fastDetailOf(req.url ?? '') ? 'fast' : 'full'\n    const usage = await buildWebUsage(deps, region, { detail })\n    return json(res, 200, usage)\n  })\n\n  // -------------------------------------------------------------------------\n  // GET /account-credits — per-account balances for the composer panel.\n  // -------------------------------------------------------------------------\n  mount(QODER_ACCOUNT_CREDITS_PATH, async (req, res) => {\n    if (req.method !== 'GET') return json(res, 405, { error: 'method not allowed' })\n    const region = regionOf(res, req.url ?? '')\n    if (region === undefined) return\n    if (deps.accountCredits === undefined) return json(res, 503, { reason: 'credits-unavailable', error: 'account credits unavailable' })\n    try {\n      const credits = await deps.accountCredits(region)\n      return json(res, 200, credits)\n    } catch (error: unknown) {\n      return json(res, 502, { error: safeMessage(error) })\n    }\n  })\n\n  // -------------------------------------------------------------------------\n  // GET /campaigns — one region's activity feed (check-in + VIEW_DETAILS banners).\n  // -------------------------------------------------------------------------\n  mount(QODER_CAMPAIGNS_PATH, async (req, res) => {\n    if (req.method !== 'GET') return json(res, 405, { error: 'method not allowed' })\n    const region = regionOf(res, req.url ?? '')\n    if (region === undefined) return\n    if (deps.campaigns === undefined) return json(res, 503, { reason: 'campaigns-unavailable', error: 'campaigns unavailable' })\n    try {\n      const feed = await deps.campaigns(region)\n      return json(res, 200, feed)\n    } catch (error: unknown) {\n      return json(res, 502, { error: safeMessage(error) })\n    }\n  })\n\n  // -------------------------------------------------------------------------\n  // POST /models/refresh — re-read one region's catalog.\n  // -------------------------------------------------------------------------\n  mount(QODER_MODELS_REFRESH_PATH, async (req, res) => {\n    if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n    const region = regionOf(res, req.url ?? '')\n    if (region === undefined) return\n    const refresh = deps.refreshModels ?? deps.discoverModels\n    if (refresh === undefined) return json(res, 503, { reason: 'refresh-unavailable', error: 'model discovery unavailable' })\n    try {\n      const models = await refresh(region)\n      return json(res, 200, { models: models.map(webModelOf) })\n    } catch (error: unknown) {\n      return json(res, 502, { error: safeMessage(error) })\n    }\n  })\n\n  // -------------------------------------------------------------------------\n  // POST /accounts/refresh — re-scan sources (settings / env / vault).\n  // -------------------------------------------------------------------------\n  mount(QODER_ACCOUNTS_REFRESH_PATH, async (req, res) => {\n    if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n    const region = regionOf(res, req.url ?? '')\n    if (region === undefined) return\n    const accounts = await deps.store(region).accounts(deps.credentialSources(region))\n    return json(res, 200, accounts.map(webAccountOf(deps, region)))\n  })\n\n  // -------------------------------------------------------------------------\n  // POST /accounts?action=add|remove — one vault mutation (add-PAT + remove).\n  // -------------------------------------------------------------------------\n  mount(QODER_ACCOUNTS_PATH, async (req, res) => {\n    if (!loopbackOrigin(req)) return json(res, 403, { error: 'forbidden' })\n    if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n    const region = regionOf(res, req.url ?? '')\n    if (region === undefined) return\n    const action = accountActionOf(req.url ?? '')\n    if (action === undefined) return json(res, 400, { error: 'action is required (add|remove)' })\n    const body = await readBody(req)\n    let parsed: Record<string, unknown>\n    try {\n      parsed = JSON.parse(body || '{}') as Record<string, unknown>\n    } catch {\n      return json(res, 400, { error: 'invalid JSON body' })\n    }\n    if (action === 'add') {\n      const pat = typeof parsed.pat === 'string' ? parsed.pat.trim() : ''\n      if (pat === '') return json(res, 400, { error: 'pat is required' })\n      // 用户在这次添加里填的显示名（可空）。**必须**用上：qoder 是 PAT 模式，\n      // 上游校验只回一个账号标识，而用户给这个 PAT 起的名字（「公司号」「备用」）\n      // 才是他认得的那个。此前只做在客户端、路由完全忽略它——名字填了等于没填，\n      // 存进去的永远是上游解析出的那个。\n      const preferred = typeof parsed.name === 'string' ? parsed.name.trim() : ''\n      if (deps.accountValidation === undefined) return json(res, 503, { reason: 'validation-unavailable', error: 'account validation unavailable' })\n      try {\n        const { name } = await deps.accountValidation.validateForRegion(region, pat)\n        // 用户没填才退回上游解析出的名字（两者都空时写空串，卡片渲染「未命名」）。\n        const displayName = preferred !== '' ? preferred : name\n        const stored = await deps.store(region).add(pat, displayName)\n        // `add` 命中已存在的 id 时只更新凭据、保留旧名；这次明确填了名字就改过去。\n        if (displayName !== stored.accountName) {\n          await deps.store(region).rename(stored.id, displayName)\n        }\n        return json(res, 200, { accountId: stored.id, accountName: displayName })\n      } catch (error: unknown) {\n        return json(res, 502, { error: safeMessage(error) })\n      }\n    }\n    // remove\n    const accountId = typeof parsed.accountId === 'string' ? parsed.accountId : ''\n    if (accountId === '') return json(res, 400, { error: 'accountId is required' })\n    const removed = await deps.store(region).remove(accountId)\n    return json(res, 200, { removed })\n  })\n\n  // -------------------------------------------------------------------------\n  // GET /probe?region=&model= — probe one model via the region's selection.\n  // -------------------------------------------------------------------------\n  mount(QODER_PROBE_PATH, async (req, res) => {\n    if (req.method !== 'GET') return json(res, 405, { error: 'method not allowed' })\n    const region = regionOf(res, req.url ?? '')\n    if (region === undefined) return\n    const model = new URL(req.url ?? '', 'http://127.0.0.1').searchParams.get('model') ?? ''\n    if (model === '') return json(res, 400, { error: 'model is required' })\n    if (deps.probeModel === undefined) return json(res, 503, { reason: 'probe-unavailable', error: 'probe unavailable' })\n    try {\n      const result = await deps.probeModel(region, model)\n      return json(res, 200, result)\n    } catch (error: unknown) {\n      return json(res, 502, { error: safeMessage(error) })\n    }\n  })\n\n  // -------------------------------------------------------------------------\n  // /pool?region=&action=checkin|test|remove|progress\n  //\n  // 前三个是 POST 动作；`progress` 是**只读的 GET 轮询**（卡片在批量在飞期间\n  // 每秒问一次「哪几行已经处理完」），所以必须在方法检查之前分岔。\n  // -------------------------------------------------------------------------\n  mount(QODER_POOL_PATH, async (req, res) => {\n    if (!loopbackOrigin(req)) return json(res, 403, { error: 'forbidden' })\n    const region = regionOf(res, req.url ?? '')\n    if (region === undefined) return\n    const action = poolActionOf(req.url ?? '')\n    if (action === undefined) return json(res, 400, { error: 'action is required (checkin|test|remove|progress)' })\n    if (deps.pool === undefined) return json(res, 503, { reason: 'pool-unavailable', error: 'pool unavailable' })\n    const pool = deps.pool\n\n    if (action === 'progress') {\n      if (req.method !== 'GET') return json(res, 405, { error: 'method not allowed' })\n      const batch = pool.batchProgress?.(region)\n      return json(res, 200, batch === undefined ? { action: 'progress' } : { action: 'progress', batch })\n    }\n    if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n\n    if (action === 'checkin') {\n      // 区域没有每日签到时**在到达上游之前**就拒绝：不值得为一个「这里没有」\n      // 花一次请求。作为能力拒绝（409 + reason）回报，而不是失败——调用方\n      // 要能分清「这里不提供」与「提供了但坏了」。卡片隐藏按钮是同一规则的\n      // UI 半边（workbuddy 同规）。\n      if (pool.checkinSupported(region) !== true) {\n        return json(res, 409, { reason: 'checkin-unsupported', error: 'this region does not offer a daily check-in' })\n      }\n      if (pool.checkin === undefined) {\n        return json(res, 503, { reason: 'pool-unavailable', error: 'pool check-in unavailable' })\n      }\n      const rows = await pool.checkin(region)\n      return json(res, 200, { action: 'checkin', rows })\n    }\n\n    if (action === 'test') {\n      // 与池视图用**同一条**目标解析、**同一份**目录（issue #26 / #33）。\n      //\n      // #26 把两处的判据统一了，但两处传进去的 `catalog` 不是同一份：卡片读\n      // `deps.catalogs`（完整目录），这里读 `pool.catalog`（被 `deriveCatalog` 按\n      // 「已勾选模型」裁剪过的运行时目录）。于是只要目标模型不在\n      // `enabledModelKeys` 里 —— 手选了一个没勾的模型，或「自动」档唯一的免费模型\n      // 没被勾 —— 这里就永远解不出目标：卡片写着「测试用模型 X」，点下去却是\n      // `rows: []`（issue #33 的现场，国内版与国际版都中）。\n      //\n      // 「能不能测某个模型」与「它在不在 DSH 选择器里」是两件事：勾选管的是后者。\n      // 所以目标解析吃**卡片那一份**目录，两处输入相同，结论就不可能分叉。\n      const now = Date.now()\n      const poolProbes = pool.poolProbes(region)\n      const target = resolvePoolTarget({\n        catalog: poolModelsOfCatalog(deps.catalogs[region].current()),\n        preferredId: pool.preferences(region).targetModelId,\n        probes: poolProbes,\n        nowMs: now,\n      })\n      if (target.modelId === undefined) {\n        // 「解析不出目标」是一种**能力拒绝**，不是「批量跑完了、一行都没有」。\n        // 此前回 `200 {rows: []}`，客户端只能把它渲染成「Host 未返回该账号的\n        // 结果」—— 字面像是账号坏了（凭据失效 / 号不在池里），实际是模型目标\n        // 没解出来，排查方向被带偏（issue #33 第 4 点）。\n        //\n        // 用 409 + 有区分度的 `reason`：调用方能分清「这里没有可测的目标」与\n        // 「测了、没结果」，文案也就能说实话。\n        return json(res, 409, target.source === 'stale'\n          ? {\n              action: 'test',\n              reason: 'target-model-stale',\n              staleTargetModelId: target.staleModelId,\n              error: `the saved target model ${String(target.staleModelId)} is not offered by this region`,\n            }\n          : {\n              action: 'test',\n              reason: 'no-free-model',\n              error: 'this region has no zero-multiplier model to test with',\n            })\n      }\n      // `accountId` 存在时只测那一个（行级按钮）。畸形值按形状拒掉，别让它\n      // 走到宿主内部才炸：与下方 delete 分支同一条规矩。\n      const only = poolAccountIdOf(req.url ?? '')\n      if (only !== undefined && !isQoderAccountId(only)) {\n        return json(res, 400, { error: 'accountId is not a well-formed account id' })\n      }\n      // 查一下这个号还在不在：不在就明确回报，而不是回一个空数组让人以为\n      // 「测过了、没问题」。\n      if (only !== undefined) {\n        const stored = (await deps.store(region).vaultAccounts()).find(entry => entry.id === only)\n        if (stored === undefined) {\n          return json(res, 409, { reason: 'account-not-found', error: 'no stored account with that id' })\n        }\n      }\n      const rows = await pool.test(region, only)\n      return json(res, 200, { action: 'test', modelId: target.modelId, ...only === undefined ? {} : { accountId: only }, rows })\n    }\n\n    // ---- 彻底删除一个账号（凭据 + 池成员 + 区域选择，一次做完）----\n    //\n    // 这一支以前只做了「从 memberAccountIds 里剔掉」——也就是**移出池**，不是删除。\n    // 用户点它期望账号消失，PAT 却原封不动留在 vault 里，下一次「全选」又勾回来，\n    // 于是看起来像「删不掉」（用户实拍：「删除唯一的号，但是号并没有删除干净」）。\n    // 移出池现在由**勾选框**表达（workbuddy 同规），这个动作只保留「彻底删除」。\n    const accountId = poolAccountIdOf(req.url ?? '')\n    if (accountId === undefined) return json(res, 400, { error: 'accountId is required' })\n    // id 来自查询参数、马上就要拿去当 vault 里的键比对。先在这里按形状拒掉畸形值：\n    // 让一次构造出来的请求得到 400，而不是走到宿主内部才炸成 500。\n    if (!isQoderAccountId(accountId)) {\n      return json(res, 400, { error: 'accountId is not a well-formed account id' })\n    }\n    // settings / env 里的 PAT **不属于本插件**：它们由用户在插件之外管理，删掉\n    // vault 条目对它无效。所以先问清楚这个 id 是不是本插件自己存的凭据，\n    // 不是的话明确回报，而不是回一个「其实没删掉什么」的 200。\n    const store = deps.store(region)\n    const stored = (await store.vaultAccounts()).find(entry => entry.id === accountId)\n    if (stored === undefined) {\n      return json(res, 409, { reason: 'account-not-deletable', error: 'only accounts added by this plugin can be deleted' })\n    }\n    const removed = await store.remove(accountId)\n    // 凭据没了，配置里指向它的两处残骸必须一起收掉，否则卡片会一直说\n    // 「所选账号已不存在」：区域的 accountId 与池的 memberAccountIds。\n    if (deps.selectedAccountId(region) === accountId) {\n      await deps.clearSelection?.(region)\n    }\n    const prefs = pool.preferences(region)\n    if (prefs.memberAccountIds.includes(accountId)) {\n      pool.updateMembership(region, prefs.memberAccountIds.filter(id => id !== accountId), prefs.enabled)\n    }\n    return json(res, 200, { removed })\n  })\n\n  // -------------------------------------------------------------------------\n  // POST /transfer?region=&action=export|preview|import\n  // -------------------------------------------------------------------------\n  mount(QODER_TRANSFER_PATH, async (req, res) => {\n    if (!loopbackOrigin(req)) return json(res, 403, { error: 'forbidden' })\n    if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n    const region = regionOf(res, req.url ?? '')\n    if (region === undefined) return\n    const action = transferActionOf(req.url ?? '')\n    if (action === undefined) return json(res, 400, { error: 'action is required (export|preview|import)' })\n    if (deps.transfer === undefined) return json(res, 503, { reason: 'transfer-unavailable', error: 'transfer unavailable' })\n    const transfer = deps.transfer\n    const body = await readBody(req)\n    let parsed: { text?: unknown, indexes?: unknown } = {}\n    try {\n      parsed = JSON.parse(body || '{}') as { text?: unknown, indexes?: unknown }\n    } catch {\n      return json(res, 400, { error: 'invalid JSON body' })\n    }\n\n    if (action === 'export') {\n      const answer = await transfer.exportAccounts(region)\n      return json(res, 200, answer)\n    }\n    if (action === 'preview') {\n      const text = typeof parsed.text === 'string' ? parsed.text : ''\n      const answer = await transfer.previewImport(region, text)\n      return json(res, 200, answer)\n    }\n    // import\n    const text = typeof parsed.text === 'string' ? parsed.text : ''\n    const indexes = Array.isArray(parsed.indexes)\n      ? (parsed.indexes as unknown[]).filter((i): i is number => typeof i === 'number' && Number.isFinite(i))\n      : []\n    const answer = await transfer.importAccounts(region, text, indexes)\n    return json(res, 200, answer)\n  })\n\n  // -------------------------------------------------------------------------\n  // POST /__save — Host-side settings write fallback (field/value).\n  // -------------------------------------------------------------------------\n  mount(QODER_SAVE_PATH, async (req, res) => {\n    if (!loopbackOrigin(req)) return json(res, 403, { error: 'forbidden' })\n    if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n    const bodyText = await readBody(req)\n    let body: { field?: unknown, value?: unknown }\n    try {\n      body = JSON.parse(bodyText) as { field?: unknown, value?: unknown }\n    } catch {\n      return json(res, 400, { error: 'invalid JSON body' })\n    }\n    const field = body.field\n    if (typeof field !== 'string' || field === '') return json(res, 400, { error: 'field is required' })\n    try {\n      // **必须在服务端按槽位合并。**\n      //\n      // 客户端只发它要写的那一个区域（`{ [region]: value }`），因为它无法读到\n      // 另一侧的当前状态。此前这里直接把 body.value 整个写进 settings，于是\n      // 保存 cn 模型的这一次操作会把**整个 global 槽位删掉**——用户看到的现象\n      // 是「保存模型保存不了」，而磁盘上被抹掉的是另一侧的全部配置（已发生）。\n      //\n      // 服务端有 `describe()`，能读到现值，所以这里做一次真正的按槽位合并：\n      // 请求里没提到的区域原样保留。\n      await deps.settings.set(field, mergeSlotWise(field, deps.settings.describe(), body.value))\n      return json(res, 200, { ok: true })\n    } catch (error: unknown) {\n      return json(res, 500, { error: safeMessage(error) })\n    }\n  })\n\n  const mounted: QoderWebStatusMounted = { status: region => buildWebUsage(deps, region) }\n\n  ctx.effect(() => () => {\n    for (const dispose of disposers) {\n      try { dispose() } catch { /* already disposed */ }\n    }\n  })\n\n  return mounted\n}\n\n// ---------------------------------------------------------------------------\n// 快照组装\n// ---------------------------------------------------------------------------\n\n/** Project one account entry to its web shape with the selection flag. */\nfunction webAccountOf(deps: QoderWebRouteDeps, region: QoderRegion) {\n  return (account: QoderAccountEntryLike): QoderWebAccount => ({\n    id: account.id,\n    accountName: account.accountName,\n    source: account.source,\n    selected: account.id === deps.selectedAccountId(region) || (account.source !== 'vault' && deps.selectedAccountId(region) === undefined),\n  })\n}\n\n/**\n * 按区域槽位合并一次 settings 写入。\n *\n * 客户端只带它要写的那一个区域（`{ [region]: value }`）——它没有另一侧的当前\n * 状态，无法自己做合并；而宿主有 `describe()`，所以合并必须发生在这里。\n *\n * 规则：\n *   - `regions.<region>` 是**槽位级**的：请求里出现的槽位整份替换（槽位内部的\n *     字段级合并已经在客户端完成——`nextRegionModels` 从现槽位起 merge），未出现\n *     的槽位**原样保留**；\n *   - 若宿主当前没有这个槽位，则整份采用请求值。\n *\n * 这条规则是必须的，不是优化：缺了它，保存任一区域都会静默删除另一区域的全部\n * 配置（用户实拍「保存模型保存不了」）。\n */\nfunction mergeSlotWise(\n  field: string,\n  described: Array<{ ns: string, value: unknown }>,\n  incoming: unknown,\n): unknown {\n  // 非 `regions` 字段（未来扩展）：没有槽位语义，整份采用请求值。\n  if (field !== 'regions') return incoming\n  if (!isRecord(incoming)) return incoming\n\n  const current = described.find(entry => entry.value !== undefined)?.value\n  const currentRegions = isRecord(current) && isRecord(current['regions']) ? current['regions'] : undefined\n  if (currentRegions === undefined) return incoming\n\n  const merged: Record<string, unknown> = { ...currentRegions }\n  for (const [region, value] of Object.entries(incoming)) {\n    merged[region] = isRecord(value) && isRecord(currentRegions[region])\n      ? { ...(currentRegions[region] as Record<string, unknown>), ...value }\n      : value\n  }\n  return { ...(isRecord(current) ? current : {}), regions: merged }\n}\n\n/** Whether a value is a plain (non-array, non-null) object. */\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === 'object' && value !== null && !Array.isArray(value)\n}\n\n/**\n * This region's usage entry, refreshed from upstream first.\n *\n * 对齐 workbuddy：那边的 usage 路由每次请求都现场拉积分，所以数字总是新的。Qoder\n * 移植时换成了纯缓存读，而缓存只在「启动 / 配置写入 / 刷新模型 / 签到」四个时机\n * 被写 —— 聊天扣费后触发器上的数字**永远不会自己变新**，而面板表格（每账号现场\n * 读）是新的，于是同一个账号在同一个面板里显示两个数（用户实拍 800 vs 738）。\n *\n * 三条约束，缺一不可：\n *   1. **失败绝不能把文档打回空白**。`refreshUsage` 的失败由宿主记成覆盖层\n *      （`staleError` → 文档的 `refreshError`），这里只 await、不抛；\n *   2. **dep 缺席（旧宿主）时退回原来的缓存读**，行为与从前一致；\n *   3. 刷新**之后**才读缓存，否则读到的还是上一轮的旧快照 —— 修了等于没修。\n */\nasync function freshUsageEntryOf(deps: QoderWebRouteDeps, region: QoderRegion): Promise<\n  { usage?: { credits: QoderWebCredits, atMs: number }, error?: string, staleError?: string } | undefined\n> {\n  try {\n    await deps.refreshUsage?.(region)\n  } catch {\n    // 刷新链本身出错（不该发生：宿主侧已把上游异常收进缓存），照常回落到缓存读。\n  }\n  return deps.usage(region)\n}\n\n/**\n * How much of the usage document a caller wants.\n *\n * `full` is the default and the only thing that existed before: it awaits a\n * live upstream credit re-read for the selected account AND one live read per\n * pool member. `fast` is the card's first-paint document — it answers from\n * local state only, so no upstream stall can hold it (issue #77 的同族修复).\n */\nexport type QoderStatusDetail = 'full' | 'fast'\n\n/** Build one region's main usage document. */\nexport async function buildWebUsage(\n  deps: QoderWebRouteDeps,\n  region: QoderRegion,\n  options: { detail?: QoderStatusDetail } = {},\n): Promise<QoderWebUsage> {\n  const fast = options.detail === 'fast'\n  const sources = deps.credentialSources(region)\n  const store = deps.store(region)\n  const accounts = await store.accounts(sources)\n  const selectedId = deps.selectedAccountId(region)\n\n  // Resolve the serving credential; decide signed-in vs signed-out.\n  let serving = await store.resolve(sources, selectedId)\n  if (serving === undefined) {\n    const selectionExplicit = selectedId !== undefined && selectedId !== ''\n    const selectionLost = selectionExplicit && accounts.length > 0\n    deps.regionUsable?.(region, false)\n    // 账号池**在没有账号时也必须给出来**：它是「添加 PAT / 导入账号」的**唯一**\n    // 入口（账号工具由账号池区渲染，见客户端 `renderPool`）。此前这一支刻意不带\n    // `pool`，理由是「不出现 pool 段就等于没有任何账号正在使用」——但那个表达\n    // 让最需要添加账号的页面（一个账号都没有）恰恰没有添加入口（用户实拍）。\n    // 「当前没有正在计费的账号」这件事改由每一行的 `current` 表达：没有账号时\n    // 自然全为 false，无需靠整段缺席来暗示。\n    const pool = deps.pool === undefined\n      ? undefined\n      : await buildPoolView(deps, region, accounts, deps.catalogs[region].current(), undefined, fast)\n    const lastQuotaExhaustion = deps.lastQuotaExhaustion?.(region)\n    return {\n      status: 'signed-out',\n      accounts: accounts.map(webAccountOf(deps, region)),\n      enabled: deps.regionEnabled(region),\n      showCreditsInMainUi: deps.regionCreditsShown(region),\n      // 缺席读成「显示」：这块内容早在这个开关之前就有。\n      showCampaigns: deps.regionCampaignsShown?.(region) ?? true,\n      creditPosition: deps.creditPosition?.(region) ?? 'composer',\n      ...lastQuotaExhaustion === undefined ? {} : { lastQuotaExhaustion },\n      // GLOBAL（不带区域参数）：侧边栏只有一行、一个整页。`=== true` 见\n      // `QoderWebRouteDeps.sidebarPanelEnabled` —— 缺席不是同意。\n      ...deps.sidebarPanelEnabled?.() === true ? { sidebarPanelEnabled: true } : {},\n      ...deps.pollMinutes?.() !== undefined ? { pollMinutes: deps.pollMinutes() } : {},\n      message: selectionLost\n        ? '所选账号已不存在，请重新选择或填写 PAT'\n        : '请填写 Qoder PAT（或设置环境变量）',\n      selectionLost,\n      selectionExplicit,\n      ...(pool === undefined ? {} : { pool }),\n    }\n  }\n\n  deps.regionUsable?.(region, true)\n\n  const catalog = deps.catalogs[region].current()\n  const enabledKeys = new Set(deps.enabledModelKeys(region))\n  const budgets = deps.contextBudgets(region)\n  const models = catalog.map(model => {\n    // apply the saved context budget to each model's web row.\n    const budget = budgets[model.key]\n    const effectiveWindow = budget !== undefined && model.contextTiers?.includes(budget)\n      ? { contextWindow: budget, nativeContextWindow: model.contextWindow }\n      : { contextWindow: model.contextWindow, nativeContextWindow: model.contextWindow }\n    return {\n      ...webModelOf(model),\n      ...effectiveWindow,\n    }\n  })\n\n  // 首屏文档（`detail=fast`）**不触发任何上游重读**：`refreshUsage` 是一次\n  // 真实的上游调用，而它正是 issue #77 那类「页面等几十秒」的根源——卡片在拿到\n  // 整份文档之前什么都不画。首屏改用缓存里已有的读数；随后那份完整文档照常\n  // 现场重读，数字与从前完全一致，只是不再挡住账号列表的出现。\n  const usageEntry = fast ? deps.usage(region) : await freshUsageEntryOf(deps, region)\n  const offKeysRaw = deps.offModelKeys(region)\n  // 回显**只**来自用户保存的选择，绝不按能力补并。\n  //\n  // 这里原先写作 `offKeysRaw.includes(key) || !m.supportsThinking`：一旦上游把某\n  // 模型报成非推理，它就被强制并入 `offModelKeys`，于是那一行「可关闭思考」无论\n  // 用户怎么取消勾选、保存后重开设置页又是勾上的 —— 保存其实成功了，是回显层\n  // 覆盖（issue #1 的第二个症状）。并入的理由也不成立：非推理模型根本没有 off\n  // 档可言（`qoderThinkingLevelMap` 对它们返回 undefined），把它画成勾选只是在\n  // 展示一个不存在的配置。\n  //\n  // 能力判定已经在数据源那一侧修好（`catalog.ts` 的 `supportsThinkingOf`），\n  // 回显层不该再持有第二份判据 —— 两份判据必然漂移。\n  const offModelKeys = catalog.filter(m => offKeysRaw.includes(m.key)).map(m => m.key)\n\n  const credentialRejected = usageEntry?.error === 'credential-rejected'\n  // 恢复建议必须建立在**实测**上：把「本区域还有其他账号，但刚才都没能通过\n  // 上游校验」这句话说出口之前，得真的去问过那些账号。此前这里是\n  // `accounts.length <= 1` 的猜测——只要存在第二条记录就宣称「可以切换一个\n  // 试试」，而那条记录可能同样过期（用户实拍：两条同名记录、一条已过期，卡片\n  // 却说「试试上面那个」）。`credentialRecovery` 逐个探测其余账号，只把真正\n  // 答过话的那个承诺给用户；dep 缺席（旧宿主）时退回原来的保守猜测。\n  let recovery: QoderWebRecovery | undefined\n  if (credentialRejected) {\n    // 首屏同样不探测：`credentialRecovery` 会为每个其余账号打一次上游。用原来\n    // 那条保守猜测（没有实测就只说「可能需要重新登录」），完整文档随后照常\n    // 实测并给出真正的建议。\n    recovery = deps.credentialRecovery === undefined || fast\n      ? { reloginRequired: accounts.length <= 1 }\n      : await deps.credentialRecovery(region, serving.id)\n  }\n\n  let pool: QoderWebPool | undefined\n  if (deps.pool !== undefined) {\n    pool = await buildPoolView(deps, region, accounts, catalog, serving.id, fast)\n  }\n\n  const lastQuotaExhaustion = deps.lastQuotaExhaustion?.(region)\n  return {\n    status: 'signed-in',\n    accountId: serving.id,\n    accountName: serving.accountName,\n    region,\n    enabled: deps.regionEnabled(region),\n    showCreditsInMainUi: deps.regionCreditsShown(region),\n    showCampaigns: deps.regionCampaignsShown?.(region) ?? true,\n    creditPosition: deps.creditPosition?.(region) ?? 'composer',\n    ...lastQuotaExhaustion === undefined ? {} : { lastQuotaExhaustion },\n    ...deps.sidebarPanelEnabled?.() === true ? { sidebarPanelEnabled: true } : {},\n    ...deps.pollMinutes?.() !== undefined ? { pollMinutes: deps.pollMinutes() } : {},\n    source: serving.source,\n    selectionExplicit: selectedId !== undefined && selectedId !== '',\n    accounts: accounts.map(webAccountOf(deps, region)),\n    models,\n    enabledModelKeys: models.filter(m => enabledKeys.has(m.key)).map(m => m.key),\n    offModelKeys,\n    imageModelKeys: deps.imageModelKeys(region).filter(key => catalog.some(m => m.key === key)),\n    // 「保存过图片选择」与集合内容无关地透传：卡片要靠它区分「从未选过」\n    // （套核对表种子）与「选成了空集」（尊重全关）。见 issue #22 的次因。\n    imageSelectionSaved: deps.imageSelectionSaved?.(region)\n      ?? deps.imageModelKeys(region).length > 0,\n    ...(usageEntry?.usage?.credits === undefined ? {} : { credits: usageEntry.usage.credits }),\n    ...(usageEntry?.error !== undefined ? { creditsError: redactQoderText(usageEntry.error) } : {}),\n    // 上次**重读**失败、但快照完好：卡片/composer 显示旧数字并说明它旧，而不是\n    // 把数字抹掉。这个覆盖层与 `refreshError` 字段在契约里写了几版，宿主此前\n    // 从没人赋值（卡片分支一直是死代码）。\n    ...(usageEntry?.staleError === undefined ? {} : { refreshError: redactQoderText(usageEntry.staleError) }),\n    // 数据的**真实读取时刻**。composer 页脚此前显示的是「客户端 fetch 返回的\n    // 时刻」，于是刷新失败时它会跟着更新 —— 看起来像数据是新的。宿主手里一直\n    // 有 `atMs`，只是在上面那行被丢掉了。\n    ...(usageEntry?.usage?.atMs === undefined ? {} : { creditsAtMs: usageEntry.usage.atMs }),\n    ...(credentialRejected && recovery ? { credentialRejected: true, recovery } : {}),\n    contextBudgets: budgets,\n    thinkingEfforts: deps.thinkingEfforts(region),\n    ...(pool === undefined ? {} : { pool }),\n  }\n}\n\n/** Build the pool's web view, including per-account rows tied to the probes. */\nasync function buildPoolView(\n  deps: QoderWebRouteDeps,\n  region: QoderRegion,\n  accounts: readonly QoderAccountEntryLike[],\n  catalog: readonly QoderModelInfo[],\n  /** The account actually billing traffic, from the region's resolved serving credential. */\n  servingAccountId: string | undefined,\n  /** First-paint document: read only what the Host already measured (issue #77). */\n  fast = false,\n): Promise<QoderWebPool | undefined> {\n  const pool = deps.pool!\n  const prefs = pool.preferences(region)\n  const probes = pool.poolProbes(region)\n  const now = Date.now()\n  const memberSet = new Set(prefs.memberAccountIds)\n  /** 当前确实存在的账号 id —— 用来把配置里的残渣过滤掉。 */\n  const knownIds = new Set(accounts.map(account => account.id))\n  const targetId = prefs.targetModelId || ''\n  // 「免费即 0」这条契约的投影只有一份（`poolModelOf`）：卡片的下拉、卡片的目标\n  // 解析、测试路由的目标解析都读它，三处不可能各写一套。\n  const targetModels = poolModelsOfCatalog(catalog)\n  const target = resolvePoolTarget({\n    // 与测试路由**逐字同源**：同一份目录（`deps.catalogs`，含未勾选的模型）、\n    // 同一条解析（issue #33）。「自动」这一档挑法的规则见 `resolvePoolTarget`：\n    // 最近测成功过的优先、跳过刚被排过队的（issue #26）。\n    catalog: targetModels,\n    preferredId: prefs.targetModelId,\n    probes,\n    nowMs: now,\n  })\n\n  // Membership is explicit; effective membership is what the pool can actually\n  // resolve a credential for.\n  //\n  // `current` answers \"who is BILLING traffic right now\" — a DIFFERENT question\n  // from \"who the ranking says should serve\" or \"which model is the test\n  // target\". It must come from the region's resolved serving credential\n  // (`servingAccountId`), never from the target model id or a list position:\n  // guessing it would make the card assert a switch that was never applied.\n  const checkinSupported = pool.checkinSupported(region)\n  // 新形态（含刷新时刻）；dep 缺席（旧宿主）时退回旧的布尔表。\n  const checkinSnapshot = pool.checkinSnapshot?.(region) ?? {}\n  const checkinLegacy = pool.checkinState?.(region) ?? {}\n  const effectiveIds: string[] = []\n  const rows: QoderWebPoolAccount[] = []\n  /**\n   * 「serving 号自己是否已被排除」与「池里还有没有人能接管」。\n   *\n   * 这两件事必须在**循环之前**算出来，因为每一行的 `current` 都要用它。\n   * 「还有没有人能接管」按 `prefs.memberAccountIds` 直接算，不等\n   * `effectiveIds` —— 后者要跑完循环才知道，而循环里就要这个答案。\n   * 判据与请求路径一致：成员 ∩ 未被排除（`nextFailoverCredential` 里\n   * `rankPool(...)[0]` 用的同一条 `exclusionOf`）。\n   */\n  const servingExcluded = servingAccountId !== undefined\n    && exclusionOf(probes[servingAccountId], now, target.modelId) !== undefined\n  const anyMemberCanServe = prefs.memberAccountIds\n    .some(id => exclusionOf(probes[id], now, target.modelId) === undefined)\n  /**\n   * 实际在服务的账号。\n   *\n   * 用户实拍（2026-10-18）：serving 号标着「当前使用」，同一行却写着\n   * 「✗ 用量已达上限」，读起来像自相矛盾。工作簿（workbuddy）对这件事的处理\n   * 是：serving 号被排除且无人接管时直接答 `undefined` —— 注释写明理由是\n   * 「把它报成在用，会和正下方那张写着同一个号被限流的表自相矛盾」。\n   *\n   * 这里照做，但把条件收窄到**真的没人接管**：池开着、且所有成员都被排除。\n   * 只要还有别的号能接管，`current` 就落在接管者身上（见下面的行循环），\n   * 「有人在买单」这句话仍然成立。\n   * 池关着时不做这个降级 —— 没有第二个人，报「没人在用」只会让标题变空。\n   */\n  const liveServing = servingExcluded && prefs.enabled && !anyMemberCanServe\n    ? undefined\n    : servingAccountId\n  // 成员积分：卡片路由付费拉取（workbuddy 同规），失败降级为「—」而不是\n  // 让整个文档失败。非成员不读（从未测量过，显示「—」是诚实的）。\n  //\n  // 首屏文档不走这条路：`memberCredits` 是**每成员一次上游 usage 读数**，\n  // 池里六个号就是六次串在文档尾巴上的真实请求，任何一次慢都会把整个账号\n  // 列表扣住（issue #77 的形态）。`cachedMemberCredits` 只答宿主内存里已有的\n  // 快照，取不到就是「—」。宿主没有这个 dep 时**宁可不给 pool 段**，也不在\n  // 首屏偷偷付这笔钱 —— 那等于把要修的问题原样保留。\n  let memberCredits: ReadonlyMap<string, QoderPoolCredits> | undefined\n  if (fast) {\n    // 宿主编译时没有本地快照来源 → 首屏干脆不给 pool 段（卡片随后由完整文档\n    // 补齐）。给了也是空的，而空表会让「添加 PAT」入口跟着消失。\n    if (pool.cachedMemberCredits === undefined) return undefined\n    memberCredits = pool.cachedMemberCredits(region, prefs.memberAccountIds)\n  } else {\n    memberCredits = await pool.memberCredits?.(region, prefs.memberAccountIds).catch(() => undefined)\n  }\n  /**\n   * 池开启时的**接管候选人**：`rankPool` 第一个可用的成员。\n   *\n   * ⚠️ 它**不是**「每个请求的第一发」——此前这里的注释把方向写反了。真实请求\n   * 路径（`src/shim.ts` 的 `handleChat`）每次都先 `resolveServing()`，也就是\n   * `store.resolve(sources, selectedAccountId)`：**第一发永远打给用户选中的号**。\n   * 只有首字节之前被硬拒（auth / 限流 / 额度 / 瞬时），才走\n   * `nextFailoverCredential` → `rankPool(candidates,...)[0]` 重试。所以这个\n   * 候选人只在「选中号此刻被排除」时才会真正接管；选中号好着时，第一发根本\n   * 轮不到它，把它报成「当前使用」同样是假话。\n   *\n   * 判据必须与请求路径逐字相同（同一个 `rankPool`、同一个 `orderAccountIds`、\n   * 同一个目标模型作用域），否则接管发生时卡片会指错人。\n   * 取不到候选（没有可用成员）时退回 `undefined` —— 说不出就不说。\n   */\n  let livePriorityAccount: string | undefined\n  if (prefs.enabled) {\n    const candidates = []\n    for (const accountId of prefs.memberAccountIds) {\n      const probe = probes[accountId]\n      const reading = memberCredits?.get(accountId)\n      candidates.push({\n        account: { id: accountId, accountName: accountId },\n        ...reading === undefined ? {} : { credits: reading },\n        ...probe === undefined ? {} : { probe },\n      })\n    }\n    const chosen = rankPool(candidates, now, target.modelId, prefs.orderAccountIds)\n      .find(row => row.excludedBy === undefined)\n    livePriorityAccount = chosen?.account.id\n  }\n  for (const account of accounts) {\n    const member = memberSet.has(account.id)\n    const probe = probes[account.id]\n    // 按**目标模型**作用域判：卡片测的就是 `targetModelId`，所以拿它对。\n    // 一条关于别的模型的结论不适用——A 可用、B 429 时，两个模型下都写\n    // 「可用」就是错的（此前正是如此，因为 probe 不带模型）。\n    const excludedBy = exclusionOf(probe, now, target.modelId)\n    // 「此刻在发号」的真实判据（与请求路径逐字对齐，见上面 livePriorityAccount）：\n    //   · 池开 **且** 选中号被排除 → 接管者（rankPool 第一个可用的成员）——\n    //     每个请求仍先打给选中号，首字节前被拒后由接管者重试并计费。\n    //   · 其余情形 → `liveServing`，即 `resolveServing` 的第一发目标：池开着但\n    //     选中号好着时，第一发就在它身上，rankPool 名次只是候补；池关着时即使\n    //     它被排除也是它 —— 没有换号机制，下一个请求确实还会打给它，报「在用」\n    //     才是诚实的（`index.ts` 的 `accountCreditsOf` 同规）。\n    // 被排除的号不会因此拿到绿点——点色由 `accountDotTone` 决定（current 且可用\n    // 才绿），「当前」标记与红点并存说的是真话：它在服务，但它坏了。\n    const isCurrent = prefs.enabled && servingExcluded\n      ? livePriorityAccount === account.id\n      : liveServing === account.id\n    if (member) {\n      const cred = await pool.credentialFor(region, account.id)\n      if (cred !== undefined) effectiveIds.push(account.id)\n    }\n    const reading = member === true ? memberCredits?.get(account.id) : undefined\n    rows.push({\n      accountId: account.id,\n      accountName: account.accountName,\n      // 这个 PAT 归谁管：只有 `vault` 的能在这里删（见 QoderWebPoolAccount.source）。\n      // 卡片据此不给 settings/env 的行显示删除按钮，而不是给一个点了会 409 的按钮。\n      source: account.source,\n      ...(reading === undefined ? {} : {\n        credits: reading.total,\n        expiringSoon: reading.expiringSoon,\n        ...(reading.nearestExpiryMs === undefined ? {} : { nearestExpiryMs: reading.nearestExpiryMs }),\n        // 套餐到期（issue #31 建议 1）：与积分到期分开带走，卡片才能把\n        // 「分什么时候作废」与「账号还能用多久」说成两句话。\n        ...(reading.planExpiresAtMs === undefined ? {} : { planExpiresAtMs: reading.planExpiresAtMs }),\n      }),\n      ...(probe === undefined ? {} : {\n        probe: {\n          outcome: probe.outcome,\n          atMs: probe.atMs,\n          ...(probe.source === undefined ? {} : { source: probe.source }),\n          ...(probe.retryAtMs === undefined ? {} : { retryAtMs: probe.retryAtMs }),\n          // 时刻的来源（issue #32）：`upstream-reported` 是上游说的，\n          // `quota-refresh` 是按签到快照推的。不透传，卡片就只能把两者\n          // 显示成同一句话。\n          ...(probe.retrySource === undefined ? {} : { retrySource: probe.retrySource }),\n          // 排队信息（issue #26）：卡片要显示「前面还有 N 个」。\n          ...(probe.queue === undefined ? {} : { queue: probe.queue }),\n          ...(probe.message === undefined ? {} : { message: probe.message }),\n          // 透传作用域，卡片才能在「这条结论不是当前模型」时说出来。\n          // 写侧加字段而读侧不透传，卡片就永远看不到它——那就是没改。\n          ...(probe.modelId === undefined ? {} : { modelId: probe.modelId }),\n        },\n      }),\n      ...(excludedBy === undefined ? {} : { excludedBy }),\n      // 今天是否已签到 + 下一窗何时刷新：两者同源，都只有真打过上游才存在。\n      // `undefined` 表示还没读过 —— UI 说「未知」而不是断言「未签到」\n      // （见 QoderWebPoolAccount.checkedInToday）。`refreshAtMs` 缺席时不说倒计时，\n      // 绝不用本地零点或「上次 +24h」编一个（用户实拍：官网页面上那个数字才是对的）。\n      ...(checkinSupported && checkinSnapshot[account.id] !== undefined\n        ? {\n            checkedInToday: checkinSnapshot[account.id]!.claimed,\n            ...(checkinSnapshot[account.id]!.refreshAtMs === undefined\n              ? {}\n              : { checkinRefreshAtMs: checkinSnapshot[account.id]!.refreshAtMs }),\n          }\n        : checkinSupported && checkinLegacy[account.id] !== undefined\n          ? { checkedInToday: checkinLegacy[account.id] === true }\n          : {}),\n      current: isCurrent,\n      member,\n    })\n  }\n\n  /**\n   * 「这一行的 current 是怎么来的」。\n   *\n   * 用户实拍（2026-10-18）：account-a 标着「当前使用」，同一行却写着\n   * 「✗ 用量已达上限」；上面 account-b 还有 100 分、目标模型列写着\n   * 「✓ 可用」。读起来像自相矛盾。真实请求路径（`src/shim.ts`）是：\n   *\n   *   · 每一发的第一击都是 `resolveServing()` —— 用户**选中**的号；池开着不会\n   *     改变这一点（此前本文件的注释把它写成「请求先发 rankPool 第一名」，方向\n   *     是反的，本轮已按代码逐行核实并纠正）。\n   *   · 只有选中号在首字节前被硬拒，池才会让 `rankPool` 第一个可用的成员\n   *     **接管**这次请求并由它计费。\n   *\n   * 所以 `current` 有两种来源，必须让 UI 说出来，否则「当前使用」与同一行的\n   * 「用量已达上限」会读起来互相打架：\n   *\n   *   - `selected`：选中号在服务（池开与否都一样——它没被排除时第一发就在它身上）；\n   *   - `failover`：选中号此刻被排除、接管者是这个成员 ——「接管」不是「回落」，\n   *     它是当前唯一真正在买单的人。\n   *\n   * 还有一种更糟的情形（workbuddy 同款判断）：选中号被排除、而**池里没有别人\n   * 能接管**时，`current` 全是 false、本字段缺席，配 `servingUnavailable: true` —\n   * 「谁在计费」的诚实答案是「没有人」：下一个请求会直接失败而不是记在谁头上。\n   */\n  const servingSource = liveServing === undefined\n    ? undefined\n    : prefs.enabled && servingExcluded ? 'failover' : 'selected'\n  /**\n   * 清洗过的用户顺序：只保留**当前确实存在的账号**。\n   *\n   * 配置里的 `orderAccountIds` 在删除账号后不会自动收缩（与 `memberAccountIds`\n   * 同一个残渣问题），原样透传会让卡片把名次算在一个已经不存在的行上。\n   */\n  const orderedIds = (prefs.orderAccountIds ?? []).filter(id => knownIds.has(id))\n  return {\n    enabled: prefs.enabled,\n    checkinSupported: pool.checkinSupported(region),\n    ...(target.modelId === undefined ? {} : { targetModelId: target.modelId }),\n    ...(target.source === 'stale' && target.staleModelId !== undefined ? { staleTargetModelId: target.staleModelId } : {}),\n    targetModelSource: target.source,\n    ...(servingSource === undefined ? {} : { servingSource }),\n    // 池开启时**选中号被拒后的接管候选**（rankPool 第一个可用的）。仅当选中号\n    // 被排除时它才是「在发号的人」（`current` 已按这条判据落好）；面板不要拿它\n    // 直接当绿点依据，读每行的 `current`。\n    ...(livePriorityAccount === undefined ? {} : { priorityAccountId: livePriorityAccount }),\n    // serving 号被排除、又没人接管：没有「在用的账号」这件事本身也是事实，\n    // 交给卡片去说「池里没有可用的账号」而不是留一个空白标题。\n    ...(servingExcluded && liveServing === undefined ? { servingUnavailable: true } : {}),\n    memberAccountIds: prefs.memberAccountIds,\n    // 只透传「真的还在池里的」id：删掉的账号残留在配置里时，卡片拿它排\n    // 名次会得到一个指向不存在的行号。\n    ...(orderedIds.length === 0 ? {} : { orderAccountIds: orderedIds }),\n    ...(prefs.probeInputTokens && prefs.probeInputTokens > 0 ? { probeInputTokens: prefs.probeInputTokens } : {}),\n    effectiveMemberAccountIds: effectiveIds,\n    accounts: rows,\n    catalog: targetModels,\n  }\n}\n"
    },
    {
      "path": "src/shim.ts",
      "content": "/**\n * Qoder 回环 shim：进程内 HTTP 服务（127.0.0.1 随机端口）。\n *\n * 安全模型与 dsh-connect-workbuddy 一致（参考其 `src/shim.ts`）：\n * - 随机端口 + 进程内 32 字节随机 secret（pi-ai 只拿到 secret 当 apiKey，\n *   真实的 Qoder 凭据绝不交给 pi-ai）；\n * - Host / Origin / Content-Type 三重入站校验（必须在路由判定之前），\n *   请求体有 64MB 上限；\n * - 常量时间比对 Authorization。\n *\n * 职责：把 pi-ai 的 OpenAI 聊天请求翻译成 Qoder 网关请求，并把 Qoder 的\n * OpenAI 形状 SSE 原样转发为 OpenAI chunks；错误分类映射为 DSH 可判定的\n * HTTP 状态 + error.code。\n *\n * 首字节之前的失败一律回 **非 200 的 JSON 错误**（不是 SSE 错误帧）：pi-ai\n * 的 openai-completions 客户端只认非 2xx 响应体的 `error.message/code`，\n * 对 200 流里的 `error` 字段完全不读（chunk 循环只取 `choices[0]`，\n * `finish_reason:\"error\"` 会被塌缩成一句无信息的 \"Provider finish_reason:\n * error\"）。只有 JSON 错误能把真实的 kind/code 送进宿主的分类器。\n *\n * 账号池故障转移（参考 dsh-connect-workbuddy 的 `src/shim.ts` 相同模式）：\n * - 每次请求先 `resolveServing()` 解析**本次该买单的账号**——就是用户显式\n *   选中的号（缺省落到 `credential()` 的默认解析：settings → env → 首个\n *   vault）；账号池的排序**不参与第一发**，它只在下面的接管路径里出场；\n * - 首块字节写出前若上游硬拒（auth / 限流 / 额度 / 瞬时），记录该账号的失败\n *   （`onServingFailure` → live-request 写回账号池），间隔\n *   `failoverGapMs`（默认 2s，可中断）后再 `failoverAccount()` 取下一个候选\n *   重试 —— **只在未写任何 SSE 前重试**，一旦首个 delta 已转发，之后的错误\n *   原样进流（不回放、不换号）；策略层若重复返回已试过的账号，shim 侧也刹车；\n * - 客户端中途断开（响应流 close）会中止上游请求，且**不**为该次失败记测量\n *   （那是断开，不是账号的错）；\n * - 被账号池接管时，首个内容帧以引用块前缀说明「本次由账号池账号 X 服务」\n *   （必须走 `choices[0].delta.content`——空 choices 的自定义帧会被 pi-ai\n *   直接跳过，用户将完全看不到换号）。\n *\n * @module dsh-connect-qoder/shim\n */\n\nimport { createServer } from 'node:http'\nimport type { AddressInfo } from 'node:net'\nimport { timingSafeEqual } from 'node:crypto'\nimport { randomBytes } from 'node:crypto'\nimport type { QoderUpstreamClient, QoderChatDelta, QoderQueueState, UpstreamErrorKind } from './upstream.ts'\nimport { QoderUpstreamError, isQoderUpstreamError, upstreamUnavailableOf } from './upstream.ts'\nimport type { QoderModelInfo } from './catalog.ts'\nimport { shouldAnnounceFailover } from './failover-notice.ts'\n\n/** One resolvable serving credential, as the shim sees it. */\nexport interface QoderServingAccount {\n  accountId: string\n  accountName: string\n  pat: string\n}\n\nexport interface QoderShimOptions {\n  upstream: QoderUpstreamClient\n  /**\n   * Fallback credential resolution (settings → env). Used when the pool-elected\n   * serving account is undefined, i.e. the \"auto\"/default path.\n   */\n  credential: () => string | undefined\n  /**\n   * The account this request should bill through, decided BEFORE any byte is\n   * written. Undefined means \"fall back to `credential()`\", which is how a pool\n   * disabled / no-usable-member region keeps serving its selected account.\n   */\n  resolveServing?: () => Promise<QoderServingAccount | undefined>\n  /**\n   * The next account to try after `triedIds` all failed before the first byte.\n   * Undefined means failover is exhausted; the request then reports the last\n   * failure.\n   */\n  failoverAccount?: (triedIds: readonly string[]) => Promise<QoderServingAccount | undefined>\n  /**\n   * Record one serving account's pre-first-byte failure (pool measurement).\n   *\n   * `context` 说这条失败**凭什么**被判成这个 kind（issue #6）：`kind` 只说「像\n   * 什么」，不说「凭什么」。`auth` 既可能是业务码 `105` 确认的凭据被拒（此时\n   * 永久剔除账号是对的），也可能只是 HTTP 403 兜底猜的（此时永久剔除会把一个\n   * 排队/限流中的账号踢出池且不自愈）。宿主写池记录需要这个区别，所以把上游\n   * 状态与业务码一起递过去。\n   */\n  onServingFailure?: (\n    accountId: string,\n    kind: UpstreamErrorKind,\n    message: string,\n    context?: {\n      status?: number | undefined\n      code?: string | undefined\n      /**\n       * 上游申报的等待时长（毫秒），issue #26。\n       *\n       * 缺席 = 上游没申报。此前这条被丢掉，池子把「等 30 秒」放大成 30 分钟。\n       */\n      retryAfterMs?: number | undefined\n      /**\n       * 上游说「我在排队」的证据，issue #26。\n       *\n       * 缺席 = 上游没提排队；这时不许把失败说成「排队中」。\n       */\n      queue?: QoderQueueState | undefined\n    },\n  ) => void\n  /**\n   * 判定「这条换号通知是否已经对用户说过」，说过就把这条并入上一次、不再重复写。\n   *\n   * 为什么需要它：一次 Agent 回合里有十几轮模型调用（思考 / 运行命令 / 读取 /\n   * 编辑…）。用户的账号当日用尽后，**每一轮**都会先撞 110、再换到同一个备用号\n   * 回答——`notice` 是每轮请求的局部变量，于是十几条一模一样的引用条被逐条写进\n   * 回答正文。用户看到的是复读，而不是信息。\n   *\n   * 判据（账号、失败种类、接管账号）全是稳定事实，重复即同一个事实；只要它们\n   * 不变就不再播报，**换成了另一个账号回答时仍会播报**。\n   *\n   * 实现方应当有界且能自愈：上游恢复后清掉记录，否则「今天说过」会变成「永远\n   * 不再说」。\n   */\n  hasAnnouncedFailover?: (from: QoderServingAccount, to: QoderServingAccount, kind: UpstreamErrorKind) => boolean\n  /**\n   * 这个（接管）账号目前是否还处于「当日用量用尽」的排除状态。\n   *\n   * 池关着（默认）时 `onServingFailure` 不写记录，`failoverAccount` 也不存在，\n   * 于是没有账号池的单账号用户每轮都要付一次「换号失败 + 2 秒等待」：shim 无从\n   * 知道这件事。由宿主用池状态回答，已知被排除时直接回错（或直接放行，取决于\n   * `failoverAccount` 返回什么），不再空跑一次上游。\n   */\n  isAccountExcluded?: (accountId: string) => boolean\n  /**\n   * 换号成功后，把「哪个账号、因为什么、换成了谁」交给宿主措辞。\n   *\n   * 返回 undefined 表示不提示。**只有真正换了号才会被调用**（由\n   * `shouldAnnounceFailover` 把关），所以这里不必再判断是否发生了换号。\n   *\n   * 措辞归宿主：账号名的展示方式、是否点名接管账号、哪些失败值得播报，都是\n   * 产品决策，不该硬编码在 shim 里。\n   */\n  failoverNotice?: (\n    from: QoderServingAccount,\n    to: QoderServingAccount,\n    kind: UpstreamErrorKind,\n    /**\n     * 上游说「我在排队」的证据（issue #26）；缺席 = 上游没提排队。\n     *\n     * 排队在 kind 那一层是 `transient`，光看 kind 只能说「上游暂时异常」——\n     * 而上游逐字说的是「在排队，服务是好的」。措辞归宿主，所以证据递给它。\n     */\n    context?: { queue?: QoderQueueState | undefined },\n  ) => string | undefined\n  /** 模型显示名 → Qoder 内部 key。未知时原样发送。 */\n  modelKeyOf?: (displayName: string) => string | undefined\n  /** 该模型是否支持图像输入（用于请求校验，可选）。 */\n  supportsImagesOf?: (displayName: string) => boolean\n  /**\n   * 该模型在设置里保存的思考强度档位（模型显示名 → 档位名）。\n   *\n   * 「设置里选一次、之后每个请求自动带上」——与 Qoder 客户端同形态\n   * （它的事件名就叫 `reasoning-effort-changed`）。返回 undefined 表示没保存\n   * 过，请求不带档位字段，由上游用模型自己的默认档。\n   */\n  reasoningEffortOf?: (displayName: string) => string | undefined\n  /**\n   * 换号重试前的间隔（默认 {@link FAILOVER_ACCOUNT_GAP_MS}）。测试注入 0。\n   * 上游限流按请求体积触发，零间隔连环重试会让每个候选都撞同一堵墙。\n   */\n  failoverGapMs?: number\n  /**\n   * 上游说「在排队、等 N 秒再来」时，shim 自己先等掉这一次的上限，毫秒\n   * （issue #29）。默认 {@link QUEUE_WAIT_MAX_MS}，测试注入 0 关闭或注入小值。\n   *\n   * ## 为什么要在 shim 里等，而不是把失败交给宿主\n   *\n   * 宿主的重试阶梯是**递增**的（5s → 10s → 20s → 30s，带抖动）。上游明确说\n   * 「等 30 秒」时，前两次重试一定短于 30 秒 —— issue #29 的现场是 28 次重试、\n   * 296 秒白等，其中 11 次是在上游说「等 30 秒」之后 5 秒内就重发的。\n   *\n   * 更关键的是：`pi-ai` 那条路由**没有** `providerRetryAfterMs` 通道（issue\n   * #24 已复核），插件无法让宿主精确等待。所以在自己这一层等掉上游要求的时长，\n   * 是唯一能让「等 30 秒」真的等于 30 秒的办法，而且不消耗宿主的重试预算。\n   *\n   * 上限之外（或等过一次仍排队）就原样抛给宿主 —— 此时宿主至少还有剩余预算。\n   */\n  queueWaitMaxMs?: number\n  /** 请求体字节上限（默认 64MB，对齐 workbuddy）。测试可注入小值。 */\n  requestBodyLimit?: number\n  userTypeOf?: () => string | undefined\n  logger?: (message: string) => void\n}\n\nexport interface QoderShim {\n  /** 等 server 就绪后可用。 */\n  ready: Promise<void>\n  baseUrl: string\n  secret: string\n  close: () => Promise<void>\n  port: number\n}\n\nconst CONTENT_TYPE_JSON = 'application/json'\n\n/** 请求体上限（workbuddy 同值）：长对话体可以很大，但必须有界。 */\nconst REQUEST_BODY_LIMIT = 64 * 1024 * 1024\n\n/**\n * 换号重试前的间隔（workbuddy 同值）。\n *\n * 上游限流按请求体积触发：零间隔连环重试会让每个候选账号都撞上同一堵墙\n * （4 个账号一秒内全部失败）。批量测试已在账号间等 400ms\n * （`POOL_BATCH_GAP_MS`）；故障转移重试是用户正在等的真实请求，给上游窗口\n * 更多喘息空间。等待是可中断的：客户端断开就立刻停，而不是睡满全程。\n */\nconst FAILOVER_ACCOUNT_GAP_MS = 2_000\n\n/**\n * 排队时 shim 自己最多等多久（issue #29）。\n *\n * 取 60 秒：上游实测申报值多为 30 秒（`queueType: p3`），留一倍余量给\n * 「申报 45 秒」这类形态；再长的等待对用户来说已经等于卡死，交给宿主重试环\n * 与用户自己决定更诚实。超过这个值就原样抛给宿主，不做截断等待 ——\n * 「只等一半再重发」正是 issue #29 抱怨的那种行为。\n */\nconst QUEUE_WAIT_MAX_MS = 60_000\n\n/**\n * 浏览器 Origin（存在时）必须指向回环。非浏览器客户端（插件自己的 fetch、\n * pi-ai）根本不发 Origin，直接放行；DNS-rebinding 页面的 Host 可以伪造，\n * 但 Origin 会暴露它的真实域名。\n */\nfunction originIsLoopback(origin: string | undefined): boolean {\n  if (origin === undefined || origin.trim() === '') return true\n  try {\n    const { hostname } = new URL(origin)\n    return hostname === '127.0.0.1' || hostname === 'localhost' || hostname === '::1' || hostname === '[::1]'\n  } catch {\n    return false\n  }\n}\n\n/**\n * 写给宿主的 `code` 翻译表。\n *\n * 宿主（`@deepseek-ai/dsh-llm` + llm-pi-ai）从失败文案里读英文短语来决定\n * 「原地重试（默认 5 次指数退避）」还是「跨供应商故障转移」：`RATE_LIMIT` /\n * `SERVER` / `TIMEOUT` / `TRANSPORT` / `EMPTY_RESPONSE` 在原地重试集里。\n *\n * `rate-limited` 是那个被字面翻译害惨的 kind：上游 429 的冷却常常以小时计\n * （探针从响应体里解析恢复时间），若按 `rate_limit_exceeded` 送达，宿主会把\n * 整个重试预算烧在一个不可能在退避窗口内恢复的端点上。翻成 `quota_exceeded`\n * 是宿主认得的词，也符合上游「此刻不可用」的实际语义；HTTP 状态保持 429\n * 不动（那是上游真实返回的），上游自己的消息仍原文透传给人读。\n */\nconst KIND_HOST_CODE: Partial<Readonly<Record<UpstreamErrorKind, string>>> = {\n  'rate-limited': 'quota_exceeded',\n}\n\n/** 首字节前失败写给宿主的 code（宿主按它分类）；流内错误帧仍用原 code。 */\nfunction hostErrorCode(kind: UpstreamErrorKind): string {\n  return KIND_HOST_CODE[kind] ?? ERROR_MAP[kind].code\n}\n\n/**\n * 净化写给宿主的失败文案里**裸的 401/403 数字**。\n *\n * 这是国际版「API 密钥无效」假警报的根因（用户实拍：对话报密钥无效、同一条\n * 账号在卡片里却只是「用量已达上限」）。\n *\n * 宿主对 pi-ai 失败**不是**按 HTTP 状态分类，而是**对文案跑正则**\n * （app.asar 内 `classifyPiAiError`）：\n *\n * ```js\n * if (/\\b(?:401|403)\\b/.test(message)) return \"AUTH\";   // ← 第一道，命中即返回\n * if (isQuotaExceededError(message)) return QUOTA_EXCEEDED;\n * ```\n *\n * 而本插件为了溯源，一直把上游原文（含 `HTTP 403 {\"code\":\"110\",…}`）拼进这条\n * 文案。于是**配额耗尽被第一道正则截走判成 AUTH**，宿主用中立文案\n * `message.failure.auth`（「API 密钥无效」）覆盖掉提供方消息 —— 一个明天就\n * 自动恢复的账号被读成凭据坏了。实测 `isQuotaExceededError` 对同一串文本是\n * `true`：分类结果是**顺序**造成的，不是判据不认。\n *\n * 只替换**裸数字**，且只在非 auth 类上做：\n * - `auth` 必须原文照送。上游真的吐 `401 TOKEN_EXPIRE` 时，AUTH 正是正确答案；\n *   而「未配置 PAT」那条中文没有状态码，宿主会显示原文（比换成「API 密钥无效」\n *   更有用），所以这一档**不做**任何装饰。\n * - `429`/`5xx`/`400` 不受影响：`429 → RATE_LIMIT`、`5xx → SERVER`（原地重试）、\n *   `400 → INVALID_REQUEST` 都是期望的分类。**状态码数字必须整词替换**，\n *   否则 `1401`、`4030` 这类业务数字会被改坏（这是溯源信息）。\n *\n * 边界判据是**两条否定环视**（对抗审核 S1 发现 `\\b` 不够）：\n * - `(?<![\\w.])` 左侧：数字/字母/下划线/句点之前不算独立状态码，于是 `1401`、\n *   `v403`、`a403b`、`code_403` 全部保留；`code=403`、`HTTP 403 {` 仍然命中。\n * - `(?!\\d)(?!\\.\\d)` 右侧：后面跟数字或「小数点+数字」时不算，于是 `4030x` 保留、\n *   **`401.5` 这种小数不再被改写成非法的 `4xx.5`**。句末句号（`HTTP 403.`）不受\n *   影响，因为 `(?!\\.\\d)` 要求点后紧跟数字。\n *\n * 换成 `4xx` 而不是删掉数字：状态码是给人读的溯源信息，抹掉会让「为什么失败」\n * 变得不可查 —— 这是本项目反复吃过亏的地方。\n */\nexport function hostMessageText(kind: UpstreamErrorKind, message: string): string {\n  if (kind === 'auth') return message\n  return message.replace(SANITIZE_BARE_STATUS, '4xx')\n}\n\n/**\n * 「裸的 401/403」的判据，只有一处定义 —— 前缀、正文、后缀都由它统一净化。\n *\n * 抽成常量而不是在三处各写一遍：净化一旦漏掉某一段拼接文本，那个数字就会绕过\n * 它自己被送进宿主的正则分类器（前缀漏净化的那次回归就是这么来的）。\n */\nconst SANITIZE_BARE_STATUS = /(?<![\\w.])(?:401|403)(?!\\d)(?!\\.\\d)/gu\n\n/**\n * 净化任意写给宿主的片段（前缀、正文、后缀都走它）。\n *\n * `auth` 档原文照送，所以调用方判断 kind 之后再决定要不要调它。\n */\nfunction sanitizeForHost(text: string): string {\n  return text.replace(SANITIZE_BARE_STATUS, '4xx')\n}\n\n/**\n * 写给宿主的**完整**失败文案：带 kind 名与状态码前缀，再统一净化。\n *\n * 为什么要带前缀：宿主只按正则猜分类，猜不中就落到 `TRANSPORT`（不可原地重试\n * 的兜底）。留一串没有任何线索的中文（例如只净化的 `上游信封错误: HTTP 4xx\n * {\"code\":\"115\"}`）会被猜成 `TRANSPORT`；而带上 `quota-exhausted` 之后，\n * `isQuotaExceededError` 的 `quota ... exceeded` 判据立刻命中。\n *\n * **状态码由本函数负责加、也由本函数负责净化，`note` 后缀同样一起净化**\n * （对抗审核 S3：原先 suffix 拼在净化之后，将来它若带上游信息就会绕过净化）。\n * 前置判断放在 `auth` 那一行：那一档必须原文送达，一个字符都不能改。\n */\nexport function hostFailureMessage(\n  kind: UpstreamErrorKind,\n  status: number,\n  message: string,\n  suffix = '',\n): string {\n  if (kind === 'auth') return message\n  return sanitizeForHost(`qoder upstream ${kind} (http ${status}): ${hostMessageText(kind, message)}${suffix}`)\n}\n\n/**\n * 把上游申报的重试间隔写进**给宿主的失败文案**（issue #24）。\n *\n * 为什么非写文案不可：宿主在 pi-ai 这条路由上**只从文案分类**\n * （`llm-pi-ai/src/stream.ts` 的 `classifyPiAiError` 拿到的就是 `failure.message`），\n * 失败对象上没有 `providerRetryAfterMs` 的通道 —— 那条通道只有 Anthropic /\n * DeepSeek 那两个直连适配器有（它们的 `providerError(raw, status, headers)` 读\n * `retry-after` 头）。所以「上游说等 5 秒」这件事，在本路由上唯一能影响宿主\n * 行为的办法就是让它出现在文案里，且**不要**被 `hostMessageText` 的净化吞掉\n * （那个净化只动裸 401/403，不动我们这段）。\n *\n * 措辞固定为 `retry-after 5s`：`llm-retry` 不解析文案，所以这不是给机器读的，\n * 是给用户与后续排查读的 —— 现在他们能直接看到「上游只要求等 5 秒」，而不是\n * 「上游报了个 4xx」。\n */\nexport function retryAfterNote(retryAfterMs: number | undefined): string {\n  if (retryAfterMs === undefined || !Number.isFinite(retryAfterMs) || retryAfterMs <= 0) return ''\n  const seconds = retryAfterMs / 1000\n  // 保留一位小数即可（上游给的通常就是整数秒）；避免 5000ms 打成 5.0s 之外的噪音。\n  const shown = Number.isInteger(seconds) ? String(seconds) : seconds.toFixed(1)\n  return ` [upstream retry-after ${shown}s]`\n}\n\n/**\n * 构造给宿主的失败文案，并把上游申报的重试间隔附在后面。\n *\n * 这一层存在是为了让「文案」与「头」两个出口用同一个判据：`retryAfterNote`\n * 负责文案，`Retry-After` 头负责非流式响应（见 `writeJson` 的调用点）。\n * 两处都从 `QoderUpstreamError.retryAfterMs` 读，不各自解析一遍。\n */\nexport function hostFailureMessageOf(error: { kind: UpstreamErrorKind, status: number, message: string, retryAfterMs?: number | undefined }, suffix = ''): string {\n  return hostFailureMessage(error.kind, error.status, error.message, `${suffix}${retryAfterNote(error.retryAfterMs)}`)\n}\n\n/** HTTP 状态 + error.code 双映射表（DSH 依据 code 判定原地重试 vs failover）。 */\nconst ERROR_MAP: Record<UpstreamErrorKind, { status: number; code: string }> = {\n  network: { status: 502, code: 'connection_error' },\n  auth: { status: 401, code: 'invalid_api_key' },\n  'rate-limited': { status: 429, code: 'rate_limit_exceeded' },\n  'invalid-request': { status: 400, code: 'invalid_request_error' },\n  'content-policy': { status: 400, code: 'content_policy_rejected' },\n  'quota-exhausted': { status: 429, code: 'quota_exceeded' },\n  transient: { status: 502, code: 'upstream_error' },\n  unknown: { status: 500, code: 'upstream_error' },\n}\n\n/**\n * Round about which upstream failures are worth spending a failover attempt\n * on. A request never starts, wait / fix input / the model is gone, a\n * content-policy refusal is about THIS message (the next account would be\n * refused the same way), and a mid-stream error has already committed bytes.\n * Only a failure where the serving account was the problem and nothing has\n * been written yet deserves to move to the next account.\n */\nfunction isFailoverEligible(kind: UpstreamErrorKind): boolean {\n  return kind === 'auth'\n    || kind === 'rate-limited'\n    || kind === 'quota-exhausted'\n    || kind === 'network'\n    || kind === 'transient'\n}\n\n/** 可中断的等待：signal 中止时立即结束，而不是睡满全程。 */\nfunction sleepAbortable(ms: number, signal: AbortSignal): Promise<void> {\n  return new Promise((resolve) => {\n    if (ms <= 0 || signal.aborted) return resolve()\n    const timer = setTimeout(resolve, ms)\n    signal.addEventListener('abort', () => { clearTimeout(timer); resolve() }, { once: true })\n  })\n}\n\nexport function createQoderShim(options: QoderShimOptions): QoderShim {\n  const { upstream } = options\n  const logger = options.logger ?? (() => {})\n  const secret = randomBytes(32).toString('base64url')\n  const secretBuf = Buffer.from(secret)\n\n  let baseUrlValue = ''\n  let portValue = 0\n  let closeFn: () => Promise<void> = async () => {}\n\n  const ready = new Promise<void>((resolveReady, rejectReady) => {\n    const server = createServer((req, res) => {\n      void handleRequest(req, res).catch((error) => {\n        const upstream = isQoderUpstreamError(error)\n        const status = upstream ? ERROR_MAP[error.kind].status : 500\n        const code = upstream ? hostErrorCode(error.kind) : 'internal_error'\n        const raw = String((error as Error).message ?? 'internal error')\n        // 与下面两条路径用同一个 formatter：这条也会承载上游错误（`handleRequest`\n        // 内层未捕获的抛出），只净化而不带 kind 前缀会落到宿主的 TRANSPORT 兜底。\n        writeJson(res, status, {\n          error: {\n            message: upstream ? hostFailureMessageOf({ ...error, message: raw }) : raw,\n            code,\n            type: 'qoder_error',\n          },\n        }, upstream ? error.retryAfterMs : undefined)\n      })\n    })\n\n    server.on('error', (error) => {\n      rejectReady(error)\n    })\n\n    server.listen(0, '127.0.0.1', () => {\n      const addr = server.address() as AddressInfo\n      baseUrlValue = `http://127.0.0.1:${addr.port}`\n      portValue = addr.port\n      resolveReady()\n    })\n\n    closeFn = () => new Promise<void>((resolve, reject) => {\n      server.close((error) => (error ? reject(error) : resolve()))\n    })\n  })\n\n  async function handleRequest(req: import('node:http').IncomingMessage, res: import('node:http').ServerResponse): Promise<void> {\n    if (!checkHost(req)) {\n      writeJson(res, 403, { error: { message: 'bad host', code: 'host_not_allowed' } })\n      return\n    }\n    if (!originIsLoopback(req.headers.origin)) {\n      writeJson(res, 403, { error: { message: 'Origin must be a loopback origin', code: 'origin_not_allowed' } })\n      return\n    }\n    if (!checkAuthorization(req, secretBuf)) {\n      writeJson(res, 401, { error: { message: 'invalid api key', code: 'invalid_api_key' } })\n      return\n    }\n    if (!checkContentType(req)) {\n      writeJson(res, 415, { error: { message: 'unsupported media type', code: 'invalid_request_error' } })\n      return\n    }\n\n    const url = new URL(req.url ?? '/', 'http://127.0.0.1')\n    if (req.method === 'GET' && (url.pathname === '/healthz' || url.pathname === '/healthz/')) {\n      writeJson(res, 200, { ok: true })\n      return\n    }\n    if (req.method === 'GET' && url.pathname === '/v1/models') {\n      await handleModels(res)\n      return\n    }\n    if (req.method === 'POST' && url.pathname === '/v1/chat/completions') {\n      await handleChat(req, res)\n      return\n    }\n    writeJson(res, 404, { error: { message: 'not found', code: 'invalid_request_error' } })\n  }\n\n  function checkHost(req: import('node:http').IncomingMessage): boolean {\n    const host = req.headers.host ?? ''\n    return /^127\\.0\\.0\\.1:\\d+$/.test(host)\n  }\n\n  function checkAuthorization(req: import('node:http').IncomingMessage, expected: Buffer): boolean {\n    const header = req.headers.authorization\n    if (typeof header !== 'string') return false\n    const match = /^Bearer (.+)$/.exec(header)\n    if (!match) return false\n    const actual = Buffer.from(match[1] ?? '')\n    if (actual.length !== expected.length) return false\n    return timingSafeEqual(actual, expected)\n  }\n\n  function checkContentType(req: import('node:http').IncomingMessage): boolean {\n    if (req.method === 'GET') return true\n    const ct = req.headers['content-type'] ?? ''\n    return ct.startsWith(CONTENT_TYPE_JSON)\n  }\n\n  function resolveFallbackCredential(): string {\n    const pat = options.credential()\n    if (!pat) {\n      throw new QoderUpstreamError('auth', '未配置 Qoder PAT：请在插件设置里填写，或设置环境变量', 401)\n    }\n    return pat\n  }\n\n  async function handleModels(res: import('node:http').ServerResponse): Promise<void> {\n    // 目录由宿主维护，shim 只回 id 列表；这里从 catalog 的 key 派生出 id 序列。\n    const ids = listModelIds()\n    const models = ids.map((id) => ({ id, object: 'model', owned_by: 'qoder' }))\n    writeJson(res, 200, { object: 'list', data: models })\n  }\n\n  function listModelIds(): string[] {\n    // The Host owns the roster; this shim serves the ids of the current catalog\n    // so OpenAI clients that enumerate before model selection see the same set.\n    return []\n  }\n\n  async function handleChat(req: import('node:http').IncomingMessage, res: import('node:http').ServerResponse): Promise<void> {\n    let raw: string\n    try {\n      raw = await readBody(req, options.requestBodyLimit ?? REQUEST_BODY_LIMIT)\n    } catch (error) {\n      if ((error as Error).message === 'request body too large') {\n        // 文案与宿主 INVALID_REQUEST 分类器的既有分支对齐（\"request body too\n        // large\"），413 在原地重试集之外——同一个超大体换谁重发都一样被拒。\n        writeJson(res, 413, { error: { message: 'request body too large', code: 'invalid_request_error' } })\n        return\n      }\n      throw error\n    }\n    let body: Record<string, unknown>\n    try {\n      body = JSON.parse(raw) as Record<string, unknown>\n    } catch {\n      writeJson(res, 400, { error: { message: 'invalid JSON body', code: 'invalid_request_error' } })\n      return\n    }\n    const model = typeof body.model === 'string' ? body.model : ''\n    const messages = Array.isArray(body.messages) ? body.messages as Array<Record<string, unknown>> : []\n    const stream = body.stream !== false\n\n    if (messages.length === 0) {\n      writeJson(res, 400, { error: { message: 'messages is required', code: 'invalid_request_error' } })\n      return\n    }\n\n    const key = options.modelKeyOf ? options.modelKeyOf(model) ?? model : model\n    const supportsImages = options.supportsImagesOf ? options.supportsImagesOf(model) : false\n    // 设置里为该模型保存的思考强度。选中档位本身就是「开启思考并指定强度」，\n    // 所以它与布尔 is_reasoning 是同一件事的两个粒度——档位存在时按开启处理。\n    const savedEffort = options.reasoningEffortOf ? options.reasoningEffortOf(model) : undefined\n    const hasImages = messages.some(m => Array.isArray(m.content) && (m.content as Array<Record<string, unknown>>).some(p => p?.type === 'image_url'))\n    if (hasImages && !supportsImages) {\n      // 模型名是**请求体**带来的动态文本，一样要过净化：宿主对这条 400 也用同一个\n      // 正则分类器，而它的第一道判据是裸 401/403。若目录里存在 `gpt-401` 这类名字，\n      // 原文送达就会把「不支持图片」读成「API 密钥无效」（对抗审核 §6.2 指出）。\n      writeJson(res, 400, {\n        error: {\n          message: hostMessageText('invalid-request', `模型 ${model} 不支持图像输入`),\n          code: 'invalid_request_error',\n        },\n      })\n      return\n    }\n\n    if (!stream) {\n      writeJson(res, 400, { error: { message: 'only streaming is supported', code: 'invalid_request_error' } })\n      return\n    }\n\n    // `tool_choice` 的处理与 workbuddy 的 prepareChatBody 同义：cosy 模板没有\n    // tool_choice 字段，其他形态无法透传；但 `\"none\"` 必须落实为「不带 tools」，\n    // 否则宿主明确禁止工具时上游仍看得到它们。\n    const toolChoice = body.tool_choice\n    const tools = toolChoice === 'none' || !Array.isArray(body.tools) ? undefined : body.tools\n\n    // reasoning 档：DSH 的 thinking 选择落在 `reasoning_effort` 上。Qoder 的\n    // 线是布尔 `is_reasoning`：`off` → false；任何正档 → true；否则回落到\n    // stream_options.include_reasoning。设置里为这个模型保存过档位时，档位\n    // 本身即表示「开启并指定强度」，因此以它为准（除非请求明确说 off）。\n    //\n    // **没有保存值时采用请求里带下来的那一档。** 那是宿主从适配器报上去的默认档\n    // 物化出来的（`defaultEffort` → `reasoningEffort`），也就是上游自己声明的\n    // 默认档（用户实拍：「这里既然有默认设置选择的思考强度，选择的时候就应该\n    // 直接进入到这个对应的默认设置，而不是跳动到 default」）。\n    //\n    // 此前这一档被**丢掉**了：shim 只认自己那张保存表，于是界面上写着\n    // 「medium（上游默认）」、请求体里却没有档位字段 —— 上游拿到的还是它自己\n    // 的默认（碰巧一致），而用户换一个模型、宿主换一个档位，界面与实际行为就\n    // 对不上了。请求里的档位是宿主**此刻**的决定，比一张可能过期的保存表更近。\n    const requestedOff = body.reasoning_effort === 'off'\n    const requestedEffort = typeof body.reasoning_effort === 'string' && body.reasoning_effort !== ''\n      ? body.reasoning_effort\n      : undefined\n    const effort = savedEffort ?? requestedEffort\n    const isReasoning = effort !== undefined && !requestedOff ? true : isReasoningRequested(body)\n    const reasoningEffort = requestedOff ? undefined : effort\n\n    // 客户端断开要中止上游（否则上游继续烧额度），且断开前的失败不该记成账号\n    // 的测量。监听**响应**的 close 而非请求的：请求流被读完后 Node 会自行\n    // destroy 请求对象（`req.destroyed` 在正常读完时也会变 true），只有响应\n    // 的 close 才代表 socket 真的拆了。\n    const controller = new AbortController()\n    res.on('close', () => controller.abort())\n    if (res.destroyed) controller.abort()\n\n    // 用账号池解析本次服务的账号（可多账号 / 池接管 / 默认回落）。\n    let serving: QoderServingAccount | undefined\n    try {\n      serving = await (options.resolveServing ? options.resolveServing() : Promise.resolve(undefined))\n      if (serving === undefined) {\n        serving = { accountId: 'default', accountName: '', pat: resolveFallbackCredential() }\n      }\n    } catch (error) {\n      const upstream = isQoderUpstreamError(error)\n      const mapped = upstream ? ERROR_MAP[error.kind] : { status: 500, code: 'upstream_error' }\n      const raw = String((error as Error).message ?? 'internal error')\n      // 第三处写给宿主的失败路径（凭据解析阶段）。与 handleChat 用同一个\n      // formatter：留一串没有 kind 线索的中文会被宿主猜成 TRANSPORT。\n      writeJson(res, mapped.status, {\n        error: {\n          message: upstream ? hostFailureMessageOf({ ...error, message: raw }) : raw,\n          code: mapped.code,\n          type: 'qoder_error',\n        },\n      }, upstream ? error.retryAfterMs : undefined)\n      return\n    }\n\n    const requestId = `chatcmpl-${randomBytes(12).toString('hex')}`\n    const created = Math.floor(Date.now() / 1000)\n    const tried: string[] = []\n    const gapMs = options.failoverGapMs ?? FAILOVER_ACCOUNT_GAP_MS\n    const queueWaitMaxMs = options.queueWaitMaxMs ?? QUEUE_WAIT_MAX_MS\n    /**\n     * 本轮请求是否已经用掉了「排队自己等一次」的额度（issue #29）。\n     *\n     * 每个**请求**只等一次：上游说「等 30 秒」，我们等 30 秒后重发；若重发\n     * 仍排队，就原样交给宿主 —— 继续等会让用户面对一条永远不返回的请求，\n     * 而宿主至少还能用剩余的重试预算做决定。\n     */\n    let queueWaited = false\n    // 换号成功后置为提示文案，在写出首帧时一次性消费（置回 undefined）。\n    //\n    // ⚠️ 采集时机在**换号之后**，不是每轮开头：首轮还没失败，开头采集拿不到\n    // 「为什么换」；换号发生在上一个 catch 里，那里的 error.kind 才是原因。\n    let notice: string | undefined\n    // 整条响应是否已经吐过字节（含提示帧）。提示只允许写在这里出现的第一次——\n    // 之后写的任何内容都排在上一段已提交正文后面，会变成夹在回答中间的复读。\n    let wroteBytes = false\n\n    // 本轮尝试：写 SSE 头 + 转发流。返回前若抛错且尚未写出任何字节，则上游\n    // `wroteAny` 保持 false，可进入换号重试。\n    for (;;) {\n      let wroteAny = false\n      let hasToolCalls = false\n      let inputTokens = 0\n      let outputTokens = 0\n      /**\n       * 缓存命中数（issue #4）。与上面两个**计数方式不同**：\n       *\n       * `inputTokens` / `outputTokens` 是 `> 0` 才覆盖的（流里多帧会重复报，\n       * 只认非零值）；缓存命中数则允许本身就是 0（上游明确报「缓存一个都没\n       * 命中」是很正常的一件事）。所以用 `undefined` 当「还没拿到」，一旦上游\n       * 报过就记下来（含 0），不再被后面的帧覆盖成别的数。\n       */\n      let cachedTokens: number | undefined\n      try {\n        await upstream.chatStream(serving.pat, key, messages, {\n          ...(tools === undefined ? {} : { tools }),\n          isReasoning,\n          ...(reasoningEffort === undefined ? {} : { reasoningEffort }),\n          isVl: supportsImages,\n          signal: controller.signal,\n          onDelta: (delta) => {\n            if (!wroteAny) {\n              res.writeHead(200, {\n                'Content-Type': 'text/event-stream',\n                'Cache-Control': 'no-cache',\n                'Connection': 'keep-alive',\n                // 反向代理（若有）不得缓冲 SSE。\n                'X-Accel-Buffering': 'no',\n              })\n              // 池接管时必须让用户看见：通知文本作为首个**内容**帧写出\n              // （choices[0].delta.content）。空 choices 的自定义帧会被 pi-ai\n              // 的 chunk 循环直接跳过（`if (!choice) continue`），用户将完全\n              // 不知道换号发生过。\n              //\n              // 闸门是「**整条响应**的第一个字节」：一次换号就是「第一次尝试\n              // 失败 → 第二次尝试成功」，提示恰恰要在第二个尝试的首个 delta 上\n              // 才有位置可写。而 `wroteAny` 每轮尝试都复位，用它当闸门会让\n              // 「本轮先失败、换号后成功」把提示写在前一段已提交正文的后面。\n              if (notice !== undefined && !wroteBytes) {\n                writeNoticeChunk(res, requestId, created, model, notice)\n              }\n              notice = undefined\n              wroteAny = true\n              wroteBytes = true\n            }\n            if (delta.inputTokens > 0) inputTokens = delta.inputTokens\n            if (delta.outputTokens > 0) outputTokens = delta.outputTokens\n            // `!== undefined`（而不是 `> 0`）：上游报「0 个命中」是有效答案，\n            // 而「这一帧没报」才是 undefined。两者在宿主那里含义不同。\n            if (delta.cachedTokens !== undefined) cachedTokens = delta.cachedTokens\n            if (delta.toolCalls !== undefined) hasToolCalls = true\n            writeDeltaChunk(res, requestId, created, model, delta)\n          },\n        })\n        // chatStream 正常结束：统计块 + [DONE]。finish_reason 依据是否出现过\n        // tool_call；有 token 统计时附带 usage。\n        if (res.destroyed) return\n        const done = makeChunk(requestId, created, model)\n        done.choices[0]!.finish_reason = hasToolCalls ? 'tool_calls' : 'stop'\n        if (inputTokens > 0 || outputTokens > 0) {\n          done.usage = {\n            prompt_tokens: inputTokens,\n            completion_tokens: outputTokens,\n            total_tokens: inputTokens + outputTokens,\n            // 缓存命中数透传给宿主（issue #4）。宿主 `parseChunkUsage` 读的正是\n            // `prompt_tokens_details.cached_tokens`，缺了它就按 0 显示 ——\n            // 于是 GUI 的「缓存命中」恒为 0%，而那个 0% 是不可信的读数。\n            //\n            // **不要把 `cachedTokens` 加进 `prompt_tokens` / `total_tokens`**：\n            // 实测上游 `cached_tokens` 是 `prompt_tokens` 的子集（2032 / 2038），\n            // 相加会把缓存前缀算两遍。宿主自己会做减法，两边各按「子集」理解。\n            ...cachedTokens === undefined ? {} : { prompt_tokens_details: { cached_tokens: cachedTokens } },\n          }\n        }\n        res.write(`data: ${JSON.stringify(done)}\\n\\n`)\n        res.write('data: [DONE]\\n\\n')\n        res.end()\n        return\n      } catch (error) {\n        if (wroteAny) {\n          // 已提交字节：错误进流（不换号、不重放——回放会让客户端看到两段\n          // 拼接的回答）。\n          writeErrorChunk(res, requestId, created, model, error)\n          return\n        }\n        // 上游说「在排队、等 N 秒再来」时，先自己等掉这一次再重发（issue #29）。\n        //\n        // 判据都来自上游自己的字段：`queue.isQueued === true`、申报了正的等待\n        // 时长，且**上游不是整体拒服务**（issue #30）。\n        //\n        // 最后一条不能省：`serviceAvailable: false` 时同一个信封里 `isQueued`\n        // 照样是 `true`（现场 `queueCount: 0`、`subCode: RESOURCE_LIMIT`），但那\n        // 30 秒不是「轮到你」的时刻，只是下次探活的最早时间 —— 队列里没人，等\n        // 多久都不会轮到自己。而 `queueWaited` 是**请求内**的局部变量，宿主每次\n        // 重试都是新请求，所以「每请求只等一次」拦不住累积：一条用户请求会被\n        // 放大成 5 次 30 秒的白等（#30 现场）。\n        //\n        // 判据与「要不要换号」共用同一个纯函数，免得两处对同一个字段给出相反\n        // 的解读（#30 指出的不一致）。字段缺席时照旧等 —— 不推断。\n        //\n        // 三道闸门保证不会把请求变成永远不返回：\n        // ① 每个请求只等一次（`queueWaited`）；② 申报值必须 ≤ 上限；\n        // ③ 等待可中断（客户端断开立即放弃）。\n        if (\n          !queueWaited\n          && isQoderUpstreamError(error)\n          && error.queue?.isQueued === true\n          && !upstreamUnavailableOf(error.queue)\n          && queueWaitMaxMs > 0\n          && error.retryAfterMs !== undefined\n          && error.retryAfterMs > 0\n          && error.retryAfterMs <= queueWaitMaxMs\n        ) {\n          queueWaited = true\n          const waitMs = error.retryAfterMs\n          logger(`shim: upstream queued, waiting ${waitMs}ms before retrying ${key}`)\n          await sleepAbortable(waitMs, controller.signal)\n          if (controller.signal.aborted) return\n          continue\n        }\n        if (isQoderUpstreamError(error) && isFailoverEligible(error.kind) && !controller.signal.aborted) {\n          // 每一次失败尝试都记测量，包括没有后继可试的最后一次——那正是下一个\n          // 请求最该避开的账号。客户端已断开时不记：断开不是账号的错。\n          options.onServingFailure?.(serving.accountId, error.kind, error.message, {\n            status: error.status,\n            code: error.code,\n            // issue #26：上游申报的等待时长与排队证据一并递过去。此前两者都\n            // 没递，于是真实请求撞到排队时，池子把它记成「连不上上游」。\n            ...error.retryAfterMs === undefined ? {} : { retryAfterMs: error.retryAfterMs },\n            ...error.queue === undefined ? {} : { queue: error.queue },\n          })\n          tried.push(serving.accountId)\n          let next: QoderServingAccount | undefined\n          try {\n            next = options.failoverAccount ? await options.failoverAccount(tried) : undefined\n          } catch {\n            next = undefined\n          }\n          // 宿主已知「这个号今天已经用尽」时，别再拿同一个请求去撞一次墙。\n          //\n          // 这条守卫只在**有过候选**（`next !== undefined`）时才有意义：那说明\n          // 宿主愿意换号，只是候选恰好又被池标记为排除。没有候选时什么都不改变，\n          // 失败照常按原路径回给宿主。等待放在守卫**之后**——过去这里先睡 2 秒\n          // 再重试，一个用尽的日子 = 每轮白等 2 秒 + 一次必然失败的上游调用。\n          if (next !== undefined && options.isAccountExcluded?.(next.accountId) === true) {\n            logger(`shim: failover candidate ${next.accountId} is already excluded; not retrying it`)\n            next = undefined\n          }\n          // 策略层被要求跳过已试账号，但 shim 不依赖这一点：候选若重复，同一\n          // 请求体会对同一账号无限重发、空烧额度。`tried` 是唯一刹车，shim 侧\n          // 也查一遍。\n          if (next !== undefined && !tried.includes(next.accountId)) {\n            logger(`shim failover: ${serving.accountId} → ${next.accountId} (${error.kind})`)\n            // 用户选中的账号失败了，这事必须让用户看见——否则他看到一段正常\n            // 回答，既不知道换过号，也不知道自己选的账号已经出问题。\n            // 文案正文由配置项提供（宿主据此决定是否提示、怎么措辞），shim 只\n            // 负责「何时放进去」：首帧之前。\n            const from = serving\n            const to = next\n            // 播报**紧邻这次换号的那次失败**，且后一次覆盖前一次。\n            //\n            // A 网络故障 → B 被限流 → C 成功时，要说的是「B 被限流」：B 才是\n            // 差一点接管这次回答的账号，而「A 网络中断」是不完整且更没用的一半。\n            // 首帧只会写出一条提示，所以多次换号最终只留最后一次——这正好是\n            // 用户最需要知道的那一次：为什么最后不是由你选的账号回答。\n            if (\n              shouldAnnounceFailover({\n                switched: true,\n                fromAccountId: from.accountId,\n                toAccountId: to.accountId,\n                kind: error.kind,\n              })\n              // 同一个事实只说一次：一轮回合里每轮调用的失败原因与接管账号\n              // 都一样时，用户不需要读十几遍。（换成了另一个账号回答，仍然会\n              // 说——判据包含接管账号。）\n              && options.hasAnnouncedFailover?.(from, to, error.kind) !== true\n            ) {\n              notice = options.failoverNotice?.(from, to, error.kind, {\n                ...error.queue === undefined ? {} : { queue: error.queue },\n              })\n            }\n            serving = next\n            // 零间隔连环重试会让每个候选都撞上同一个按体积计费的限流墙；\n            // 等待可中断，客户端断开就不再睡。\n            await sleepAbortable(gapMs, controller.signal)\n            if (controller.signal.aborted) return\n            continue\n          }\n        }\n        if (isQoderUpstreamError(error)) {\n          // 没有下一个候选（或失败本就不值得换号）：首字节未写，回**非 200\n          // JSON 错误**。pi-ai 对 200 流里的 error 字段完全失明（塌缩成\n          // \"Provider finish_reason: error\"），只有非 2xx 响应体能把真实的\n          // 状态、宿主可分类的 code 与上游原文送进宿主的分类器。尝试过多个\n          // 账号时在消息里注明数量——否则池子换过号仍失败读起来就像用户选定\n          // 的那一个账号单独失败。\n          const note = tried.length > 1 ? ` (after trying ${tried.length} accounts)` : ''\n          const mapped = ERROR_MAP[error.kind]\n          writeJson(res, mapped.status, {\n            error: {\n              // 文案交给 `hostFailureMessageOf` 统一拼齐并净化：状态码由它加、也由\n              // 它净化，`note` 与上游申报的重试间隔都从它过一遍（S3：拼在净化\n              // 之后就会绕过）。\n              message: hostFailureMessageOf({ ...error, message: error.message.slice(0, 400) }, note),\n              code: hostErrorCode(error.kind),\n              type: 'qoder_error',\n            },\n          }, error.retryAfterMs)\n          return\n        }\n        // 非上游错误（组装问题等）：交外层统一 500。\n        throw error\n      }\n    }\n  }\n\n  /** 从请求体决定本次的 `is_reasoning`（见在线路上的注释）。 */\n  function isReasoningRequested(body: Record<string, unknown>): boolean {\n    const effort = typeof body.reasoning_effort === 'string' ? body.reasoning_effort : undefined\n    if (effort === 'off') return false\n    if (effort !== undefined && effort !== '') return true\n    const streamOptions = body.stream_options as Record<string, unknown> | undefined\n    return streamOptions?.include_reasoning === true\n  }\n\n  /** 池接管的通知帧：一段以引用块前缀开头的**内容**帧（pi-ai 可见）。 */\n  function writeNoticeChunk(\n    res: import('node:http').ServerResponse,\n    id: string,\n    created: number,\n    model: string,\n    notice: string,\n  ): void {\n    const chunk = makeChunk(id, created, model)\n    chunk.choices[0]!.delta.content = `\\n\\n> [dsh-connect-qoder] ${notice}\\n\\n`\n    res.write(`data: ${JSON.stringify(chunk)}\\n\\n`)\n  }\n\n  function writeDeltaChunk(\n    res: import('node:http').ServerResponse,\n    id: string,\n    created: number,\n    model: string,\n    delta: QoderChatDelta,\n  ): void {\n    const chunk = makeChunk(id, created, model)\n    const choice = chunk.choices[0]!\n    if (delta.role !== '') choice.delta.role = delta.role\n    if (delta.content !== '') choice.delta.content = delta.content\n    if (delta.reasoningContent !== '') choice.delta.reasoning_content = delta.reasoningContent\n    if (delta.toolCalls !== undefined) choice.delta.tool_calls = delta.toolCalls\n    res.write(`data: ${JSON.stringify(chunk)}\\n\\n`)\n  }\n\n  function writeErrorChunk(\n    res: import('node:http').ServerResponse,\n    id: string,\n    created: number,\n    model: string,\n    error: unknown,\n  ): void {\n    if (res.destroyed) return\n    const errChunk = makeChunk(id, created, model)\n    errChunk.choices[0]!.finish_reason = 'error'\n    const upstream = isQoderUpstreamError(error)\n    const code = upstream ? ERROR_MAP[error.kind].code : 'upstream_error'\n    const raw = String((error as Error).message ?? 'internal error')\n    // 流内帧同样要净化：宿主对 pi-ai 的 `case \"error\"` 分支拿\n    // `message.errorMessage` 跑同一个 `classifyPiAiError`，所以这条路径漏了\n    // 净化，配额失败一样会被读成 AUTH —— 而且此时 200 已提交，用户已经在看\n    // 一个半截回复，错误分类错得更难排查。\n    errChunk.error = {\n      message: upstream ? hostFailureMessage(error.kind, error.status, raw) : raw,\n      code,\n      type: 'qoder_error',\n    }\n    res.write(`data: ${JSON.stringify(errChunk)}\\n\\n`)\n    res.write('data: [DONE]\\n\\n')\n    res.end()\n  }\n\n  function makeChunk(id: string, created: number, model: string): {\n    id: string\n    object: string\n    created: number\n    model: string\n    choices: Array<{ index: number; delta: Record<string, unknown>; finish_reason: string | null }>\n    usage?: Record<string, unknown>\n    error?: Record<string, unknown>\n  } {\n    return {\n      id,\n      object: 'chat.completion.chunk',\n      created,\n      model,\n      choices: [{ index: 0, delta: {}, finish_reason: null }],\n    }\n  }\n\n  /**\n   * 写一条 JSON 响应。`retryAfterMs` 可选：带上就发 `Retry-After`（秒，向上取整）。\n   *\n   * 这个头是给**别的**消费者看的（浏览器/中间层/未来的宿主能力）。宿主在当前\n   * pi-ai 路由上**不读它**（`llm-pi-ai` 的失败只有 `{message, code}`），所以\n   * 上游申报值真正影响等待的那条路是**文案**（见 `retryAfterNote`）。两个出口都\n   * 从同一个 `QoderUpstreamError.retryAfterMs` 来，不各解析一遍。\n   */\n  function writeJson(\n    res: import('node:http').ServerResponse,\n    status: number,\n    body: unknown,\n    retryAfterMs?: number | undefined,\n  ): void {\n    if (res.writableEnded || res.destroyed) return\n    const text = JSON.stringify(body)\n    const headers: Record<string, string> = { 'Content-Type': 'application/json; charset=utf-8' }\n    if (retryAfterMs !== undefined && Number.isFinite(retryAfterMs) && retryAfterMs > 0) {\n      headers['Retry-After'] = String(Math.ceil(retryAfterMs / 1000))\n    }\n    res.writeHead(status, headers)\n    res.end(text)\n  }\n\n  function readBody(req: import('node:http').IncomingMessage, limit: number): Promise<string> {\n    return new Promise((resolve, reject) => {\n      const chunks: Buffer[] = []\n      let size = 0\n      let over = false\n      req.on('data', (chunk: Buffer) => {\n        if (over) return\n        size += chunk.length\n        if (size > limit) {\n          over = true\n          reject(new Error('request body too large'))\n          // 排干剩余上传而不是 destroy：destroy 会在 413 写回前拆掉 socket，\n          // 客户端只会看到 \"other side closed\" 而不是可读的状态码。\n          req.resume()\n          return\n        }\n        chunks.push(chunk)\n      })\n      req.on('end', () => { if (!over) resolve(Buffer.concat(chunks).toString('utf8')) })\n      req.on('error', reject)\n    })\n  }\n\n  return {\n    ready,\n    get baseUrl(): string {\n      return baseUrlValue\n    },\n    get port(): number {\n      return portValue\n    },\n    secret,\n    close: async () => {\n      await closeFn()\n    },\n  }\n}"
